const h=[{id:"vb10-1",s:"",cc:"Khoản 2 liều Ì Nghị định số 172.2025/M)D-C.P.",gt:"Nghị định áp dụng đối với cán bộ, công chức theo Luật Cán bộ, công chức năm 2025 và cán bộ, công chức đã thôi việc, nghỉ hưu. Viên chức không thuộc phạm vi điều chỉnh của Nghị định này.",mn:"Đối tượng: CBCC đang công tác + CBCC đã thôi việc, nghỉ hưu (không gồm viên chức).",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, đối tượng áp dụng của Nghị định bao gồm những ai?",o:["Cán bộ, công chức và người lao động hợp đồng trong cơ quan nhà nước","Chỉ cán bộ, công chức đang công tác","Cán bộ, công chức và viên chức trong các đơn vị sự nghiệp công lập","Cán bộ, công chức theo quy định của Luật Cán bộ, công chức năm 2025 và cán bộ, công chức đã thôi việc, nghỉ hưu"],c:3},{id:"vb10-2",s:"",cc:"Khoản 1 Điều 2 Nghị định số 172/2025/NĐ- CP.",gt:"Nguyên tắc xử lý kỷ luật: khách quan, công bằng; công khai, nghiêm minh; chính xác, kịp thời; đúng thẩm quyền, trình tự, thủ tục.",mn:"Nguyên tắc kỷ luật: khách quan, công bằng - công khai, nghiêm minh - chính xác, kịp thời - đúng thẩm quyền, trình tự.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, các nguyên tắc xử lý kỷ luật bao gồm những nội dung nào sau đây?",o:["Bảo đảm sự lãnh đạo của Đảng: kết hợp tiêu chuẩn chức danh với chỉ tiêu biên chế","Bảo đảm khách quan, công bằng; công khai, nghiêm minh; chính xác, kịp thời; đúng thẩm quyền, trình tự, thủ tục","Công khai, minh bạch; bảo đảm thứ bậc hành chính và phối hợp chặt chẽ","Tuân thủ Hiến pháp và pháp luật; bảo đảm tính hệ thống, liên tục"],c:1},{id:"vb10-3",s:"",cc:"Khoản 2 Điều 2 Nghị định số 172/2025/N))-CP. LÀI LIỆU ÔN CE CÔNG €HUC VIÊN CHỨC FÐI NGUYỄN YONA 09953502H1",gt:"Mỗi hành vi vi phạm chỉ bị xử lý một lần bằng một hình thức kỷ luật. Nếu có từ 02 hành vi vi phạm trở lên thì xem xét, kết luận từng hành vi và quyết định chung bằng một hình thức cao nhất tương ứng.",mn:"Ì hành vi = I hình thức; nhiều hành vi -. 1 hình thức cao nhất.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, mỗi hành vi vi phạm được xử lý như thế nào?",o:["Mỗi hành vi vi phạm chỉ bị xử lý một lần bằng một hình thức kỷ luật; nếu có từ 02 hành vi vi phạm trở lên thì xem xét, kết luận từng hành vi và quyết định chung bằng một hình thức cao nhất tương ứng","Mỗi hành vi vi phạm bị xử lý nhiều lần để bảo đảm tính răn đe","Nhiều hành vi vi phạm thì cộng dồn các hình thức kỷ luật","Mỗi hành vi vi phạm bị xử lý bằng tất cả các hình thức kỷ luật tương ứng"],c:0},{id:"vb10-4",s:"",cc:"Nhoốn #8 Điều 2 Nghị định số 172.20025, NGO-CP.",gt:"Cán bộ, công chức vi phạm lần đầu đã bị kỷ luật mà trong thời hạn 12 tháng kể từ ngày quyết định có hiệu lực tiếp tục vi phạm hành vi đã bị kỷ luật thì bị coi là tái phạm.",mn:"lái phạm: trong 12 tháng lại vi phạm hành vi đã bị kỷ luật,",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, cán bộ, công chức có hành vi vi phạm lần đầu đã bị xử lý kỷ luật mà trong thời hạn bao lâu kể từ ngày quyết định có hiệu lực lại tiếp tục vi phạm hành vi đã bị kỷ luật thì bị coi là tái phạm?",o:["24 tháng","06 tháng","12 tháng","36 tháng"],c:2},{id:"vb10-5",s:"",cc:"Khoản 9 Điều 2 Nghị định số 172/2025/NI-C.P.",gt:"Quyết định xử lý kỷ luật cán bộ, công chức có hiệu lực 12 tháng kể từ ngày có hiệu lực thi hành. Trong thời gian này, nếu không tiếp tục vi phạm đến mức phải kỷ luật thì quyết định đương nhiên chấm dứt hiệu lực mà không cần văn bản về việc chấm dứt.",mn:"Quyết định kỷ luật có hiệu lực 12 tháng.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, quyết định xử lý kỷ luật cán bộ, công chức có hiệu lực trong thời gian bao lâu kể từ ngày có hiệu lực thi hành?",o:["06 tháng","12 tháng","24 tháng","18 tháng"],c:1},{id:"vb10-6",s:"",cc:"Nhian 5 liều ^ Nghị định số 152? 20s N‡YCP.",gt:"Không áp dụng xử phạt hành chính thay cho kỷ luật hành chính; xử lý kỷ luật hành chính không thay cho truy cứu trách nhiệm hình sự nếu hành vi vi phạm đến mức bị xử lý hình sự. Hai loại trách nhiệm này độc lập.",mn:"Kỷ luật hành chính KHÔNG thay cho truy cứu hình sự.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, mối quan hệ giữa xử lý kỷ luật hành chính và truy cứu trách nhiệm hình sự được quy định như thế nào?",o:["Chỉ áp dụng một trong hai biện pháp tùy theo lựa chọn của cơ quan","Xử lý kỷ luật hành chính có thể thay thế truy cứu trách nhiệm hình sự","Truy cứu trách nhiệm hình sự thay thế hoàn toàn xử lý kỷ luật hành chính","Không áp dụng xử phạt hành chính thay cho kỷ luật hành chính; xử lý kỷ luật hành chính không thay cho truy cứu trách nhiệm hình sự nếu hành vi vi phạm đến mức bị xử lý hình sự"],c:3},{id:"vb10-7",s:"",cc:"Khoản 6© Điều 2 Nghị định số 172/2025/NĐ-CP.",gt:"Cán bộ, công chức bị kỷ luật về đảng thì trong thời hạn 30 ngày kể từ ngày công bố quyết định kỷ luật về đảng, cơ quan phải thực hiện quy trình xử lý kỷ luật hành chính (nếu có), bảo đảm tương xứng với kỷ luật về đảng.",mn:"Kỷ luật đảng -. 30 ngày xử lý kỷ luật hành chính tương xứng.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, khi cán bộ, công chức bị xử lý kỷ luật về đảng thì việc xử lý kỷ luật hành chính được thực hiện trong thời hạn nào?",o:["Trong thời hạn 30 ngày kể từ ngày công bố quyết định kỷ luật về đảng, cơ quan phải thực hiện quy trình xử lý kỷ luật hành chính (nếu có), bảo đảm tương xứng với kỷ luật về đảng","Trong thời hạn 60 ngày kể từ ngày công bố quyết định kỷ luật về đảng","Trong thời hạn 90 ngày kể từ ngày công bố quyết định kỷ luật về đảng","Không bắt buộc về thời hạn"],c:0},{id:"vb10-8",s:"",cc:"liêm ở khoản 3 Điều 2 Nghị định số 172/2025/NĐ-CP.",gt:"Đang thi hành quyết định kỷ luật mà vi phạm tiếp ở hình thức nhẹ hơn hoặc bằng hình thức đang thi hành thì áp dụng hình thức kỷ luật nặng hơn một mức so với hình thức đảng thì hành.",mn:"Đang bị kỷ luật, vi phạm tiếp (nhẹ hơn/bằng). nặng hơn 1 mức so với hình thức đang thi hành.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, trường hợp cán bộ, công chức đang thi hành quyết định kỷ luật mà tiếp tục có hành vi vi phạm bị xử lý ở hình thức nhẹ hơn hoặc bằng hình thức đang thi hành thì áp dụng hình thức kỷ luật nào?",o:["Cộng dồn hai hình thức kỷ luật","Áp dụng hình thức kỷ luật của hành vi vi phạm mới","Giữ nguyên hình thức kỷ luật đang thi hành","Áp dụng hình thức kỷ luật nặng hơn một mức so với hình thức kỷ luật đang thi hành"],c:3},{id:"vb10-9",s:"",cc:"liêu 3 Nghị định số 172/2025/NĐ-CP. Ji]: v£] ài ¡ M 3 LÀI LIỆU ÔN CE CÔNG €HUC VIÊN CHỨC FÐI NGUYỄN YONA 09953502H1",gt:"Các trường hợp chưa xem xét xử lý kỷ luật: đảng điều trị bệnh hiểm nghèo, mất khả năng nhận thức, ốm nặng điều trị nội trú; nữ mang thai, nghỉ thai sản, nuôi con dưới 12 tháng (và nắm nuôi con dưới 12 tháng trong một số trường hợp): đang bị khởi tố, tạm giữ, tạm giam.",mn:"Chưa xem xét: bệnh hiểm nghèo/ốm nặng - thai sản, nuôi con <12 tháng — đang bị khởi tố, tạm giữ., tạm giam.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, trường hợp nào sau đây thuộc các trường hợp CHƯA xem xét xử lý kỷ luật?",o:["Cán bộ, công chức không hoàn thành nhiệm vụ trong năm","Cán bộ, công chức đang điều trị bệnh hiểm nghèo, mất khả năng nhận thức, ốm nặng đang điều trị nội trú; nữ đang mang thai, nghỉ thai sản, nuôi con dưới 12 tháng tuổi; đang bị khởi tố, tạm giữ, tạm giam","Cán bộ, công chức đang trong thời gian tập sự","Cán bộ, công chức chuẩn bị nghỉ hưu"],c:1},{id:"vb10-10",s:"",cc:"Nhuốn — Piệu 4 Nghị định số 172 2U05. NE-C. Đ.",gt:"Các trường hợp miễn kỷ luật: mất năng lực hành vi dân sự khi vi phạm; chấp hành quyết định cấp trên đã báo cáo; vi phạm trong tình thế cấp thiết, bất khả kháng: lạm dụng quy trình, không vụ lợi nhưng thiệt hại khách quan; đổi mới, sáng tạo được cho phép, vì lợi ích chung; đã qua đời. Phương án B, C là tình tiết giảm nhẹ (không phải miễn).",mn:"Miễn kỷ luật: mất NLHVDS - chấp hành lệnh đã báo cáo - cấp thiết bất khả kháng - lạm dụng thiệt hại khách quan - đổi mới vì lợi ích chung — đã qua đời.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, trường hợp nào sau đây thuộc các trường hợp được MIỄN kỷ luật?",o:["Được xác nhận mất năng lực hành vi dân sự khi có hành vi vi phạm; phải chấp hành quyết định của cấp trên đã báo cáo theo quy định; vi phạm trong tình thế cấp thiết, do bất khả kháng; thực hiện đúng quy trình, không vụ lợi nhưng thiệt hại khách quan; đổi mới, sáng tạo được cho phép vì lợi ích chung; đã qua đời","Tự giác nhận khuyết điểm và nộp lại tài sản tham nhũng","Chủ động báo cáo vi phạm và khắc phục hậu quả","Vi phạm lần đầu, chưa gây hậu quả nghiêm trọng"],c:0},{id:"vb10-11",s:"",cc:"Nhoan 3 Điều 4 Nghị định số 172 2005. NĐ -CP.",gt:"Tình tiết giảm nhẹ: chủ động báo cáo vi phạm, tự giác nhận trách nhiệm và tự nhận hình thức kỷ luật tương xứng: chủ động cung cấp thông tin, hồ sơ; chủ động chấm dứt hành vi vi phạm, tự giác nộp tài sản tham nhũng, bồi thường, khác phục hậu quả. Phương án B. C,D là tình tiết tăng nặng.",mn:"Giảm nhẹ: chủ động báo cáo — tự giác nhận — nộp tài sản, khắc phục hậu quả.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, tình tiết nào sau đây được xem là tình tiết GIÁẢM NHẸ mức kỷ luật?",o:["Vi phạm có tổ chức, là người chủ mưu","Đối phó, quanh co, cản trở quá trình kiểm tra, thanh tra","Chủ động báo cáo vi phạm, tự giác nhận trách nhiệm và tự nhận hình thức kỷ luật tương xứng: chủ động cung cấp thông tin, hồ sơ; chủ động chấm dứt hành vi vi phạm, tự giác nộp tài sản tham nhũng, bồi thường thiệt hại, khác phục hậu quả","Lợi dụng chức vụ, quyền hạn để trục lợi"],c:2},{id:"vb10-12",s:"",gt:"Tình tiết tăng nặng: đối phó, quanh co, cản trở kiểm tra, thanh tra, điều tra; bao che cho người vi phạm; đe dọa, trù dập, trả thù người tố cáo; vi phạm có tổ chức, là người chủ mưu; lợi dụng chức vụ, quyền hạn để trục lợi. Phương án B, C, D là tình tiết giảm nhẹ.",mn:"lăng nặng: đối phó, cản trở - bao che, trù dập — chủ mưu, có tổ chức - lợi dụng chức vụ trục lợi.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, tình tiết nào sau đây được xem là tình tiết TĂNG NẶNG mức kỷ luật?",o:["Chủ động cung cấp thông tin về người cùng vi phạm","Chủ động báo cáo vi phạm và tự giác nhận trách nhiệm","Tự giác nộp lại tài sản tham nhũng và khắc phục hậu quả mm _— mm nữ 4","Đối phó, quanh co, cản trở quá trình kiểm tra, thanh tra, điều tra; bao che cho người vi phạm; đe dọa, trù dập, trả thù người tố cáo; vi phạm có tổ chức, là người chủ mưu; lợi dụng chức vụ, quyền hạn để trục lợi"],c:3},{id:"vb10-13",s:"",cc:"Diên E khoản 3 Điều 5 Nghị định số 172/2025/NĐ-CP.",gt:"Thời hiệu xử lý kỷ luật là 05 năm (60 tháng) đối với hành vi vi phạm đến mức phải kỷ luật bằng hình thức khiển trách.",mn:"Thời hiệu khiển trách: 05 năm (60 tháng).",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, thời hiệu xử lý kỷ luật đối với hành vi vi phạm đến mức phải kỷ luật bằng hình thức khiển trách là [..........",o:["02 năm (24 tháng)","10 năm (120 tháng)","05 năm (60 tháng)","03 năm (36 tháng)"],c:2},{id:"vb10-14",s:"",cc:"liêm b khoản 3 Điều 5 Nghị định số 172/2025/NĐ-CP.",gt:"Thời hiệu xử lý kỷ luật là 10 năm (120 tháng) đối với hành vi vi phạm không thuộc trường hợp phải kỷ luật bằng hình thức khiển trách (tức các vi phạm nặng hơn).",mn:"Thời hiệu: 05 năm (khiển trách) / 10 năm (còn lại).",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, thời hiệu xử lý kỷ luật đối với hành vi vi phạm không thuộc trường hợp phải kỷ luật bằng hình thức khiển trách là bao nhiêu?",o:["05 năm (60 tháng)","10 năm (120 tháng)","07 năm (84 tháng)","15 năm (180 tháng)"],c:1},{id:"vb10-15",s:"",cc:"Khoản 4 Điều 5 Nghị định số 172:2025,/NI)-CP.",gt:"Các hành vi không áp dụng thời hiệu: đảng viên vi phạm đến mức khai trừ; vi phạm về bảo vệ chính trị nội bộ: xâm hại lợi ích quốc gia, dân tộc về quốc phòng, an ninh, đối ngoại; sử dụng văn bằng, chứng chỉ, giấy chứng nhận, xác nhận giả hoặc không hợp pháp.",mn:"Không thời hiệu: khai trừ đảng — bảo vệ chính trị nội bộ — xâm hại QP, AN, đối ngoại - văn bằng giả.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, hành vi vi phạm nào sau đây KHÔNG áp dụng thời hiệu xử lý kỷ luật?",o:["Đảng viên vi phạm đến mức phải kỷ luật khai trừ; vi phạm về công tác bảo vệ chính trị nội bộ; xâm hại lợi ích quốc gia, dân tộc về quốc phòng, an ninh, đối ngoại; sử dụng văn bằng, chứng chỉ, giấy chứng nhận, xác nhận giả hoặc không hợp pháp","Hành vi vi phạm đến mức kỷ luật khiển trách","Hành vi vi phạm lần đầu","Hành vi vi phạm về chế độ làm việc"],c:0},{id:"vb10-16",s:"",cc:"Khodn 5 Điều 5 Nghị định số 172.2025/MD-C.P.",gt:"Thời hạn xử lý kỷ luật không quá 90 ngày; trường hợp có tình tiết phức tạp cần thanh tra, kiểm tra để xác minh làm rõ thêm thì có thể kéo dài nhưng không quá 150 ngày.",mn:"Thời hạn kỷ luật: 90 ngày; phức tạp tối đa 150 ngày.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, thời hạn xử lý kỷ luật là bao nhiêu và có thể kéo dài đến mức nào đối với vụ việc phức tạp?",o:["Không quá 30 ngày; phức tạp không quá 60 ngày","Không quá 60 ngày; phức tạp không quá 90 ngày","Không quá 90 ngày; trường hợp có tình tiết phức tạp cần thanh tra, kiểm tra để xác mình thì có thể kéo dài nhưng không quá 150 ngày","Không quá 120 ngày; phức tạp không quá 180 ngày"],c:2},{id:"vb10-17",s:"",cc:"Khoản 1 Điều 5 Nghị định số 172/2025/NĐ-CP.",gt:"Thời hiệu xử lý kỷ luật được tính từ thời điểm có hành vi vi phạm cho đến thời điểm cấp có thẩm quyền ra thông báo bằng văn bản về việc xem xét xử lý kỷ luật.",mn:"Thời hiệu: tính từ thời điểm vi phạm đến khi có thông báo xem xét kỷ luật.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, thời hiệu xử lý kỷ luật được tính từ thời điểm nào?",o:["Từ thời điểm có hành vi vi phạm cho đến thời điểm cấp có thẩm quyền ra thông báo bằng văn bản về việc xem xét xử lý kỷ luật","Từ thời điểm phát hiện hành vi vi phạm","Từ thời điểm ban hành quyết định xử lý kỷ luật","Từ thời điểm cán bộ, công chức thừa nhận hành vi vi phạm"],c:0},{id:"vb10-18",s:"",cc:"Khoan © Điều › Nghị định số 172. 2005 NGÓ-CP.",gt:"Không tính vào thời hiệu, thời hạn: thời gian chưa xem xét xử lý kỷ luật (Điều 3); thời gian điều tra, truy tố, xét xử theo tố tụng hình sự; thời gian khiếu nại hoặc khởi kiện vụ án hành chính về quyết định xử lý kỷ luật.",mn:"Không tính: thời gian chưa xem xét (13) — tố tụng hình sự - khiếu nại. khởi kiện,",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, thời gian nào sau đây KHÔNG tính vào thời hiệu, thời hạn xử lý kỷ luật?",o:["Thời gian cơ quan tổ chức họp kiểm điểm","Thời gian cán bộ, công chức đi công tác, học tập","Thời gian nghỉ phép hằng năm của cán bộ, công chức","Thời gian chưa xem xét xử lý kỷ luật theo Điều 3; thời gian điều tra, truy tố, xét xử theo thủ tục tố tụng hình sự; thời gian thực hiện khiếu nại hoặc khởi kiện vụ án hành chính về quyết định xử lý kỷ luật"],c:3},{id:"vb10-19",s:"",cc:"Khoản 2 Điều 3 Nghị định số 172-2025. NĐ -CP.",gt:"Công chức nữ đang nuôi con dưới 12 tháng tuổi thuộc trường hợp chưa xem xét xử lý kỷ luật, trừ khi có văn bản đề nghị xem xét xử lý kỷ luật. Đây là chưa xem xét (tạm hoãn), không phải miễn kỷ luật.",mn:"Nuôi con “12 tháng: chưa xem xét kv luật (trừ khi tự đề nghị).",t:"m",q:"Một tình huống: Bà A là công chức đang nuôi con 08 tháng tuổi thì bị phát hiện có hành vi vi phạm đến mức phải xử lý kỷ luật. Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, việc xử lý kỷ luật đối với bà A được thực hiện như thế nào?",o:["Xử lý kỷ luật ngày theo trình tự thông thường","Chưa xem xét xử lý kỷ luật trong thời gian bà A nuôi con dưới 12 tháng tuổi, trừ trường hợp bà A có văn bản đề nghị xem xét xử lý kỷ luật","Miễn xử lý kỷ luật hoàn toàn","Chuyển sang xử phạt hành chính thay cho kỷ luật"],c:1},{id:"vb10-20",s:"",cc:"Điệm ở khoôn 2 Liệu 4 Nghị định số 172-2022. NĐ-C D.",gt:"Công chức thực hiện đề xuất đổi mới, sáng tạo được cơ quan có thẩm quyền cho phép, đúng chủ trương, động cơ trong sáng, vì lợi ích chung nhưng có thiệt hại xảy ra thì thuộc trường hợp được miễn kỷ luật - cơ chế bảo vệ cán bộ dám nghĩ, dám làm.",mn:"Đổi mới được cho phép, trong sáng, vì lợiích chung.. miễn kỷ luật.",t:"m",q:"Một tình huống: Ông B là công chức, thực hiện đề xuất đổi mới được cơ quan có thẩm quyền cho phép, đúng chủ trương, có động cơ trong sáng, vì lợi ích chung nhưng có thiệt hại xảy ra. Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, ông B được xử lý như thế nào?",o:["Được miễn kỷ luật","Bị kỷ luật ở mức giảm nhẹ","Bị kỷ luật khiển trách","Bị buộc bồi thường toàn bộ thiệt hại"],c:0},{id:"vb10-21",s:"",cc:"Khoan II liệu 2 Nghị định số 172/2025/NĐ-CP.",gt:"Không được cử người có quan hệ thân thích (vợ, chồng, cha, mẹ, con, anh, chị, em ruột, cô, dì, chú, bác, cậu ruột...) hoặc người có quyền, nghĩa vụ liên quan đến hành vi vi phạm làm thành viên Hội đồng kỷ luật hoặc người chủ trì cuộc họp kiểm điểm — bảo đảm khách quan.",mn:"Không cử người thân/người có liên quan vào Hội đồng kỷ luật, chủ trì kiểm điểm.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, những người nào KHÔNG được cử làm thành viên Hội đồng kỷ luật hoặc người chủ trì cuộc họp kiểm điểm?",o:["Người phụ trách công tác tổ chức cán bộ","Người đứng đầu cơ quan, tổ chức, đơn vị","Đại diện tổ chức công đoàn cơ quan","Người có quan hệ thân thích (vợ, chồng, cha, mẹ, con, anh, chị, em ruột...) hoặc người có quyền, nghĩa vụ liên quan đến hành vi vi phạm bị xem xét xử lý kỷ luật"],c:3},{id:"vb10-22",s:"",cc:"Khoản 7 Điều 2 Nghị định số 172:2005/MD- C.P.",gt:"Nghiêm cấm mọi hành vi xâm phạm thân thể, tinh thần, danh dự, nhân phẩm trong quá trình xử lý kỷ luật — bảo đảm tính nhận văn, đúng pháp luật. §® Miẹo nhớ: Cấm xâm phạm thân thể, tinh thần, danh dự, nhân phẩm khi xử lý kỷ luật.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, hành vi nào sau đây bị nghiêm cấm trong quá trình xử lý kỷ luật?",o:["Việc thành lập Hội đồng kỷ luật","Mọi hành vi xâm phạm thân thể, tinh thần, danh dự, nhân phẩm trong quá trình xử lý kỷ luật","Việc tổ chức họp kiểm điểm","Việc lưu hồ sơ kỷ luật vào lý lịch cán bộ, công chức"],c:1},{id:"vb10-23",s:"",cc:"Khoản 10 Điều 2 Nghị định số 172/2025/NĐ-CP.",gt:"Cơ quan, tổ chức, đơn vị mới thực hiện xem xét xử lý kỷ luật và áp dụng hình thức tương ứng với vị trí hiện đang đảm nhiệm; cơ quan cử có trách nhiệm phối hợp, cung cấp toàn bộ hồ sơ liên quan.",mn:"Vi phạm ở cơ quan cử, phát hiện sau khi chuyển: cơ quan mới xử lý (cơ quan cử cung cấp hồ sơ).",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, trường hợp cán bộ, công chức có hành vi vi phạm ở cơ quan cử, đến khi chuyển sang cơ quan mới mới phát hiện và vẫn còn thời hiệu thì ai xử lý?",o:["Không xử lý vi đã chuyển công tác","Cơ quan cử phải triệu hồi và xử lý","Cơ quan, tổ chức, đơn vị mới thực hiện xem xét xử lý kỷ luật và áp dụng hình thức tương ứng với vị trí hiện đang đảm nhiệm; cơ quan cử có trách nhiệm phối hợp, cung cấp hồ sơ","Cơ quan quản lý cấp trên trực tiếp xử lý"],c:2},{id:"vb10-24",s:"",cc:"Khoản 4 Điều 2 Nghị định số 172:2025/MD-CP.",gt:"Khi xem xét xử lý kỷ luật phải căn cứ vào nội dung, động cơ, tính chất, mức độ, hậu quả, nguyên nhân vi phạm, hoàn cảnh cụ thể; tình tiết tăng nặng, giảm nhẹ; thái độ tiếp thu, sửa chữa; việc khác phục hậu quả - đánh giá toàn diện.",mn:"Căn cứ kỷ luật: nội dung, động cơ, tính chất, mức độ, hậu quả + tăng nặng/giảm nhẹ - thái độ, khắc phục.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, khi xem xét xử lý kỷ luật phải căn cứ vào những yếu tố nào?",o:["Chỉ căn cứ vào hình thức kỷ luật về đảng","Chỉ căn cứ vào hậu quả của hành vi vi phạm","Nội dung, động cơ, tính chất, mức độ, hậu quả, nguyên nhân vi phạm, hoàn cảnh cụ thể; các tình tiết tăng nặng, giảm nhẹ; thái độ tiếp thu và sửa chữa; việc khắc phục khuyết điểm, vi phạm, hậu quả","Chỉ căn cứ vào thâm niên công tác và chức vụ của người vi phạm"],c:2},{id:"vb10-25",s:"",cc:"Khoản 9 Điều 2 Nghị định số 172/2025/NMI)-CP.",gt:"Các tài liệu liên quan và quyết định kỷ luật phải được lưu giữ trong hồ sơ cán bộ, công chức; hình thức kỷ luật phải ghi vào lý lịch của cán bộ, công chức.",mn:"Quyết định kỷ luật: lưu hồ sơ + ghi vào lý lịch. s",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, các tài liệu liên quan đến việc xử lý kỷ luật và quyết định kỷ luật được xử lý như thế nào?",o:["Phải được lưu giữ trong hồ sơ cán bộ, công chức; hình thức kỷ luật phải ghi vào lý lịch của cán bộ, công chức","Chỉ lưu tại cơ quan thanh tra, không ghi vào lý lịch","Hủy sau khi quyết định kỷ luật hết hiệu lực","Chỉ thông báo miệng, không lưu hồ sơ"],c:0},{id:"vb10-26",s:"",cc:"Điểm a khoản 3 Điều 2 Nghị định số 172/2025/NĐ-CP.",gt:"Đang thi hành kỷ luật cảnh cáo mà vi phạm tiếp ở mức nhẹ hơn (khiển trách) thì áp dụng hình thức kỷ luật nặng hơn một mức so với hình thức đang thi hành (cảnh cáo), tức mức cao hơn cảnh cáo.",mn:"Đang cảnh cáo, vi phạm nhẹ hơn. › nặng hơn 1 mức so với cảnh cáo.",t:"m",q:"Một tình huống: Ông C là công chức đang thi hành quyết định kỷ luật cảnh cáo thì tiếp tục có hành vi vi phạm mới đến mức bị kỷ luật khiển trách (nhẹ hơn). Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, hình thức kỷ luật áp dụng đối với ông C là gì?",o:["Miễn xử lý vị hành vi mới nhẹ hơn","Áp dụng hình thức khiển trách của hành vi mới","Giữ nguyên hình thức cảnh cáo đang thi hành","Áp dụng hình thức kỷ luật nặng hơn một mức so với hình thức đang thi hành (cảnh cáo), tức là cách chức nêu ông C giữ chức vụ hoặc hình thức nặng hơn tương ứng"],c:3},{id:"vb10-27",s:"",cc:"liếm ở Nhoan 2 Điều ð Nghịụ định số 172. 20205-NĐ-C P.",gt:"Đối với hành vi vi phạm xác định được thời điểm chấm dứt thì thời điểm có hành vi vi phạm được tính từ thời điểm chấm dứt. (Nếu không xác định được thời điểm chấm dứt thì tính từ thời điểm có kết luận của cấp có thẩm quyền.)",mn:"Xác định được thời điểm chấm dứt › tính từ thời điểm chấm dứt.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, đối với hành vi vi phạm xác định được thời điểm chấm dứt thì thời điểm có hành vi vi phạm được tính như thế nào?",o:["Tính từ thời điểm bắt đầu hành vi vi phạm","Tính từ thời điểm chấm dứt hành vi vi phạm","Tính từ thời điểm phát hiện hành vi vi phạm","Tính từ thời điểm có kết luận của cấp có thẩm quyền"],c:1},{id:"vb10-28",s:"",cc:"Điều 2 Nghị định số 1220205 NĐ-CD.",gt:"Cả ba đều là nguyên tắc xử lý kỷ luật: khách quan, công bằng, công khai, nghiêm minh: mỗi hành vi chỉ bị xử lý một lần bằng một hình thức; nghiêm cấm xâm phạm thân thể, tinh thần, danh dự, nhân phẩm.",mn:"Nguyên tắc: khách quan, nghiêm minh -— ] hành vi 1 hình thức - cấm xâm phạm danh dự, nhân phẩm.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, các nguyên tắc sau có cùng thuộc nguyên tắc xử lý kỷ luật hay không: (i) khách quan, công bằng, công khai, nghiêm minh; (ii) mỗi hành vi chỉ bị xử lý một lần bằng một hình thức; (iii) nghiêm cấm xâm phạm thân thể, tinh thần, danh dự, nhân phẩm?",o:["Chỉ nguyên tắc (i) đúng","Cả ba nguyên tắc đều thuộc nguyên tắc xử lý kỷ luật","Chỉ nguyên tắc (i) và (ii) đúng","Không nguyên tắc nào đúng"],c:1},{id:"vb10-29",s:"",cc:"Điều 5 Nghị định số 17.2. 2025,NĐ)-C P.",gt:"Thời gian điều tra, truy tố, xét xử theo thủ tục tố tụng hình sự KHÔNG tính vào thời hiệu, thời hạn xử lý kỷ luật. Vì vậy phương án D sai. Các nhận định A. B, C đều đúng.",mn:"lhời gian tố tụng hình sự không tính vào thời hiệu, thời hạn kỷ luật.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, nhận định nào sau đây về thời hiệu, thời hạn xử lý kỷ luật là KHÔNG đúng?",o:["Thời hiệu là 05 năm đối với hành vi ở mức khiển trách, 10 năm đối với trường hợp khác","Thời hạn xử lý kỷ luật không quá 90 ngày, phức tạp không quá 150 ngày","Có bốn nhóm hành vi không áp dụng thời hiệu xử lý kỷ luật","Thời gian điều tra, truy tố, xét xử theo tố tụng hình sự được tính vào thời hiệu xử lý kỷ luật"],c:3},{id:"vb10-30",s:"",cc:"iu 2 Nghị định xố 172 20223-NĐ- CD.",gt:"Nguyên tắc cơ bản: khách quan, công bằng, công khai, nghiêm minh, chính xác, kịp thời, đúng thẩm quyền, trình tự, thủ tục; mỗi hành vi xử lý một lần bằng một hình thức; căn cứ toàn diện: không thay thế giữa kỷ luật hành chính và trách nhiệm hình sự: tương xứng với kỷ luật về đảng và nghiêm cấm xâm phạm danh dự, nhân phẩm.",mn:"Nguyên tắc: khách quan, nghiêm minh - 1 hành vi 1 hình thức - căn cứ toàn diện — không thay hình sự — tương xứng kỷ luật đảng..M Phân bổ sung cho Chương I: tăng cường điền khuyết số liệu, phân biệt thời hiệu - thời hạn, tình huống vận dụng về nguyên tắc xử lý kỷ luật, các trường hợp chưa xem xét, miền/giảm nhẹ/tông năng. Đáp án đối chiếu văn bản gốc.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, phương án nào sau đây phản ánh ĐÚNG và ĐẦY ĐỦ nhất các nguyên tắc cơ bản của xử lý kỷ luật?",o:["Xử lý kỷ luật hành chính thay cho truy cứu trách nhiệm hình sự","Chỉ cần bảo đảm xử lý nhanh và nghiêm khắc mọi vi phạm","Khách quan, công bằng, công khai, nghiêm minh, chính xác, kịp thời, đúng thẩm quyền, trình tự, thủ tục; mỗi hành vi xử lý một lần bằng một hình thức; căn cứ toàn diện vào tính chất, mức độ, tình tiết tăng nặng, giảm nhẹ; không thay thế giữa kỷ luật hành chính và trách nhiệm hình sự; bảo đảm tương xứng với kỷ luật về đảng và nghiêm cấm xâm phạm danh dự, nhân phẩm.. i0 LÀI LIỆU ÔN CE CÔNG €HUC VIÊN CHỨC FÐI NGUYỄN YONA 09953502H1","Mỗi hành vi vi phạm bị xử lý bằng nhiều hình thức để tăng tính răn đe"],c:2},{id:"vb10-31",s:"PHÂN BỐ SUNG 1- CHƯƠNG I: NGUYÊN TẮC, THỜI HIỆU - THỜI HẠN, CHƯA XEM XÉT, MIỄN/GIẢM NHẸ/TĂNG NẶNG (TRỌNG TÂM)",cc:"Điểm a khoản 3 Điều 5 Nghị định số 172:2025/NĐ-CP.",gt:"Thời hiệu xử lý kỷ luật là 05 năm (60 tháng) đối với hành vi vi phạm đến mức phải kỷ luật bằng hình thức khiển trách.",mn:"Thời hiệu: khiển trách 5 năm; còn lại 10 năm.",t:"m",q:"Điền vào chỗ trọng: Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, thời hiệu xử lý kỷ luật là [......... ] đối với hành vi vi phạm đến mức phải kỷ luật bằng hình thức khiển trách.",o:["05 năm (60 tháng)","02 năm (24 tháng)","10 năm (120 tháng)","12 tháng"],c:0},{id:"vb10-32",s:"PHÂN BỐ SUNG 1- CHƯƠNG I: NGUYÊN TẮC, THỜI HIỆU - THỜI HẠN, CHƯA XEM XÉT, MIỄN/GIẢM NHẸ/TĂNG NẶNG (TRỌNG TÂM)",cc:"fiêm b khoản 3 Điều 5 Nghị định số 172/2025/NĐ-CP.",gt:"Thời hiệu xử lý kỷ luật là 10 năm (120 tháng) đối với hành vi vi phạm không thuộc trường hợp kỷ luật khiển trách.",mn:"Vi phạm nặng hơn khiển trách ¬› thời hiệu 10 năm.",t:"m",q:"Điền vào chỗ trọng: Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, thời hiệu xử lý kỷ luật là [......... | đối với hành vi vi phạm không thuộc trường hợp áp dụng hình thức khiển trách.",o:["10 năm (120 tháng)","07 năm (84 tháng)","05 năm (60 tháng)","15 năm (180 tháng)"],c:0},{id:"vb10-33",s:"PHÂN BỐ SUNG 1- CHƯƠNG I: NGUYÊN TẮC, THỜI HIỆU - THỜI HẠN, CHƯA XEM XÉT, MIỄN/GIẢM NHẸ/TĂNG NẶNG (TRỌNG TÂM)",cc:"liếm d khoản 4 Điều 5 Nghị định số 172/2025/NĐ-CP.",gt:"Các hành vi không áp dụng thời hiệu gồm: đảng viên vi phạm đến mức khai trừ; vi phạm bảo vệ chính trị nội bộ; xâm hại lợi ích quốc gia, dân tộc về quốc phòng, an ninh, đối ngoại; và sử dụng văn bằng, chứng chỉ, giấy chứng nhận, xác nhận giả hoặc không hợp pháp. 112",mn:"Không áp dụng thời hiệu: khai trừ đảng - bảo vệ chính trị nội bộ — xâm hại lợi ích quốc gia — bằng cấp giả.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, hành vi vi phạm nào sau đây KHÔNG áp dụng thời hiệu xử lý kỷ luật?",o:["Vi phạm nội quy, quy chế của cơ quan lần đầu, hậu quả ít nghiêm trọng","Đi muốn, về sớm nhiều lần trong tháng","Vi phạm quy định về văn hóa giao tiếp ở công sở","Sử dụng văn bằng, chứng chỉ, giấy chứng nhận, xác nhận giả hoặc không hợp pháp"],c:3},{id:"vb10-34",s:"PHÂN BỐ SUNG 1- CHƯƠNG I: NGUYÊN TẮC, THỜI HIỆU - THỜI HẠN, CHƯA XEM XÉT, MIỄN/GIẢM NHẸ/TĂNG NẶNG (TRỌNG TÂM)",cc:"Khoản 5 Điều 5 Nghị định số 172/2025/NĐ- CP.",gt:"Thời hạn xử lý kỷ luật không quá 90 ngày; trường hợp phức tạp cần thanh tra, kiểm tra để xác mình thì kéo dài nhưng không quá 150 ngày.",mn:"Thời hạn xử lý kỷ luật: 90 ngày (phức tạp: 150 ngày).",t:"m",q:"Điền vào chỗ trọng: Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, thời hạn xử lý kỷ luật không quá [......... ]; trường hợp vụ việc có tình tiết phức tạp cần thanh tra, kiểm tra để xác minh thì có thể kéo dài nhưng không qua [........ l.",o:["60 ngày... 90 ngày","90 ngày... 150 ngày","30 ngày... 60 ngày","120 ngày... 180 ngày"],c:1},{id:"vb10-35",s:"PHÂN BỐ SUNG 1- CHƯƠNG I: NGUYÊN TẮC, THỜI HIỆU - THỜI HẠN, CHƯA XEM XÉT, MIỄN/GIẢM NHẸ/TĂNG NẶNG (TRỌNG TÂM)",cc:"Khoản 1 và khoản 5 Điều 5 Nghị định số 172/2025/NĐ-CP.",gt:"Thời hiệu tính từ thời điểm có hành vi vi phạm đến khi cấp có thẩm quyền ra thông báo xem xét xử lý kỷ luật (5 hoặc 10 năm). Thời hạn tính từ khi phát hiện vi phạm đến khi có quyết định kỷ luật (90/150 ngày).",mn:"Thời hiệu: từ khi vi phạm (5/10 năm). Thời hạn: từ khi phát hiện (90/150 ngày).",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, cần phân biệt thời hiệu và thời hạn xử lý kỷ luật. Nhận định nào sau đây ĐÚNG?",o:["Thời hiệu là 90 ngày; thời hạn là 5 năm hoặc 10 năm","Thời hiệu và thời hạn đều tính từ khi phát hiện vi phạm","Thời hiệu tính từ thời điểm có hành vi vi phạm đến khi ra thông báo xem xét xử lý kỷ luật; thời hạn tính từ khi phát hiện vi phạm đến khi có quyết định kỷ luật","Thời hạn tính từ khi có hành vi vi phạm; thời hiệu tính từ khi phát hiện"],c:2},{id:"vb10-36",s:"PHÂN BỐ SUNG 1- CHƯƠNG I: NGUYÊN TẮC, THỜI HIỆU - THỜI HẠN, CHƯA XEM XÉT, MIỄN/GIẢM NHẸ/TĂNG NẶNG (TRỌNG TÂM)",cc:"Khoản 2 Điều 2 Nghị định số 172/2025/NĐ-CP.",gt:"Mỗi hành vi vi phạm chỉ bị xử lý một lần bằng một hình thức. Nếu có từ 02 hành vi vi phạm trở lên thì xem xét, kết luận về từng hành vi và quyết định chung bằng một hình thức kỷ luật cao nhất tương ứng với hành vi vi phạm.",mn:"Nhiều hành vi: kết luận từng hành vi, quyết định 1 hình thức cao nhất. 13 LÀI LIỆU ÔN CE CÔNG €HUC VIÊN CHỨC FÐI NGUYỄN YONA 09953502H1",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, trong cùng một thời điểm xem xét, nếu cán bộ, công chức có từ 02 hành vi vi phạm trở lên thì xử lý như thế nào?",o:["Cộng dồn các hình thức kỷ luật của từng hành vi","Ra nhiều quyết định kỷ luật riêng cho từng hành vi","Chỉ xử lý hành vi vi phạm nghiêm trọng nhất, bỏ qua các hành vi khác","Xem xét, kết luận về từng hành vi và quyết định chung bằng một hình thức kỷ luật cao nhất tương ứng với hành vi vi phạm"],c:3},{id:"vb10-37",s:"PHÂN BỐ SUNG 1- CHƯƠNG I: NGUYÊN TẮC, THỜI HIỆU - THỜI HẠN, CHƯA XEM XÉT, MIỄN/GIẢM NHẸ/TĂNG NẶNG (TRỌNG TÂM)",cc:"f)iem E khoản 3 Điều 2 Nghị định số 172/2025/NĐ- CP.",gt:"Nếu đang thi hành kỷ luật mà có hành vi vi phạm mới ở hình thức nhẹ hơn hoặc bằng hình thức đang thi hành thì áp dụng hình thức nặng hơn một mức so với hình thức đang thi hành.",mn:"Đang thi hành KL + vi phạm mới nhẹ hơn/băng — nặng hơn 1 mức so với mức đang thi hành.",t:"m",q:"Một tình huống vận dụng: Ông A đang trong thời gian thi hành quyết định kỷ luật cảnh cáo thì tiếp tục có hành vi vi phạm mới chỉ đến mức khiển trách (nhẹ hơn). Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, ông A bị áp dụng hình thức kỷ luật nào?",o:["Áp dụng hình thức kỷ luật nặng hơn một mức so với hình thức đang thi hành (tức cách chức/buộc thôi việc tùy đối tượng)","Áp dụng hình thức khiển trách cho hành vi mới","Giữ nguyên hình thức cảnh cáo đang thi hành","Không xử lý vị đang trong thời gian thi hành kỷ luật"],c:0},{id:"vb10-38",s:"PHÂN BỐ SUNG 1- CHƯƠNG I: NGUYÊN TẮC, THỜI HIỆU - THỜI HẠN, CHƯA XEM XÉT, MIỄN/GIẢM NHẸ/TĂNG NẶNG (TRỌNG TÂM)",cc:"khuaận 8 Điều 2 Nghị định vô 172 2025 NO-CP.",gt:"Trong thời hạn 12 tháng kể từ ngày quyết định xử lý kỷ luật có hiệu lực mà tiếp tục vi phạm hành vi đã bị kỷ luật thì bị coi là tái phạm.",mn:"lái phạm: vi phạm lại trong 12 tháng kể từ khi QD kỷ luật có hiệu lực.",t:"m",q:"Điền vào chỗ trọng: Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, cán bộ, công chức có hành vi vi phạm lần đầu đã bị xử lý kỷ luật mà trong thời hạn |........ ] kể từ ngày quyết định xử lý kỷ luật có hiệu lực lại tiếp tục vi phạm hành vi đã bị kỷ luật thì bị coi là tái phạm.",o:["06 tháng","24 tháng","12 tháng","36 tháng"],c:2},{id:"vb10-39",s:"PHÂN BỐ SUNG 1- CHƯƠNG I: NGUYÊN TẮC, THỜI HIỆU - THỜI HẠN, CHƯA XEM XÉT, MIỄN/GIẢM NHẸ/TĂNG NẶNG (TRỌNG TÂM)",cc:"RhuÊn 9 Điều 2 Nghị định số 1722025 NG-CP.",gt:"(Quyết định xử lý kỷ luật có hiệu lực 12 tháng kể từ ngày có hiệu lực thi hành; nếu trong thời gian này không tiếp tục vi phạm đến mức bị kỷ luật thì đương nhiên chấm dứt hiệu lực mà không cần văn bản.",mn:"Hiệu lực (}Ð kỷ luật: 12 tháng (không vi phạm tiếp, › tự chấm dứt)..14",t:"m",q:"Điền vào chỗ trọng: Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, quyết định xử lý kỷ luật cán bộ, công chức có hiệu lực [........ kể từ ngày có hiệu lực thi hành.",o:["06 tháng","12 tháng","24 tháng","Vô thời hạn"],c:1},{id:"vb10-40",s:"PHÂN BỐ SUNG 1- CHƯƠNG I: NGUYÊN TẮC, THỜI HIỆU - THỜI HẠN, CHƯA XEM XÉT, MIỄN/GIẢM NHẸ/TĂNG NẶNG (TRỌNG TÂM)",cc:"Khoản 6 Điều 2 Nghị định số 172:2025/MD-CP.",gt:"Trong thời hạn 30 ngày kể từ ngày công bố quyết định kỷ luật về đảng, cơ quan phải thực hiện quy trình xử lý kỷ luật hành chính (nếu có); hình thức kỷ luật hành chính phải tương xứng với kỷ luật về đảng.",mn:"Kỷ luật đảng. 30 ngày làm kỷ luật hành chính tương xứng.",t:"m",q:"Điền vào chỗ trọng: Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, cán bộ, công chức bị xử lý kỷ luật về đảng thì trong thời hạn c.nneexn. | kể từ ngày công bố quyết định kỷ luật về đảng, cơ quan phải thực hiện quy trình xử lý kỷ luật hành chính (nếu có).",o:["30 ngày","15 ngày","45 ngày","60 ngày"],c:0},{id:"vb10-41",s:"PHÂN BỐ SUNG 1- CHƯƠNG I: NGUYÊN TẮC, THỜI HIỆU - THỜI HẠN, CHƯA XEM XÉT, MIỄN/GIẢM NHẸ/TĂNG NẶNG (TRỌNG TÂM)",cc:"Khoản 2 Điều 3 Nghị định số 172/2005/NĐ-CP.",gt:"Các trường hợp chưa xem xét xử lý kỷ luật gồm: đang điều trị bệnh hiểm nghèo/mất khả năng nhận thức/ốm nặng điều trị nội trú; nữ đang mang thai, nghỉ thai sản, nuôi con dưới 12 tháng tuổi (hoặc nam nuôi con dưới 12 tháng trong trường hợp đặc biệt); đang bị khởi tố, tạm giữ, tạm giam.",mn:"Chưa xem xét KL: bệnh hiểm nghèo/Ốm nặng ~ thai sản/nuôi con <12 tháng — đang bị khởi tố, tạm giam.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, trường hợp nào sau đây thuộc các trường hợp CHƯA xem xét xử lý kỷ luật?",o:["Cán bộ, công chức đang nghỉ phép năm theo kế hoạch","Cán bộ, công chức đang đi công tác nước ngoài","Cán bộ, công chức nữ đang trong thời gian mang thai, nghỉ thai sản, nuôi con dưới 12 tháng tuổi","Cán bộ, công chức đang tham gia khóa đào tạo dài hạn"],c:2},{id:"vb10-42",s:"PHÂN BỐ SUNG 1- CHƯƠNG I: NGUYÊN TẮC, THỜI HIỆU - THỜI HẠN, CHƯA XEM XÉT, MIỄN/GIẢM NHẸ/TĂNG NẶNG (TRỌNG TÂM)",cc:"liếm e khoản 2 Điều 4 Nghị định số 172, 2025,NID-CP.",gt:"Trường hợp được miễn kỷ luật gồm: mất năng lực hành vi dân sự khi vi phạm; phải chấp hành quyết định của cấp trên; vì phạm trong tình thế cấp thiết bất khả kháng; làm đúng thẩm quyền, trình tự, không vụ lợi nhưng có thiệt hại khách quan; thực hiện đối mới, sáng tạo được cho phép; và người vi phạm đã qua đời. (Các phương án còn lại là tình tiết giảm nhẹ.)",mn:"Miễn KL: mất năng lực - theo lệnh cấp trên ~ tình thế cấp thiết — đổi mới sáng tạo - đã qua đời. A l5",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, trường hợp nào sau đây được MIỄN kỷ luật?",o:["Chủ động báo cáo vi phạm và tự giác nhận trách nhiệm","Tự giác nộp lại tài sản tham nhũng","Chủ động khắc phục hậu quả do mình gây ra","Người vi phạm đã qua đời"],c:3},{id:"vb10-43",s:"PHÂN BỐ SUNG 1- CHƯƠNG I: NGUYÊN TẮC, THỜI HIỆU - THỜI HẠN, CHƯA XEM XÉT, MIỄN/GIẢM NHẸ/TĂNG NẶNG (TRỌNG TÂM)",cc:"liệm a khoản 3 HDiều 4 Nghị định sốo 172/2025/NM)- CP.",gt:"Tình tiết giảm nhẹ gồm: chủ động báo cáo vi phạm, tự giác nhận trách nhiệm, tự nhận hình thức kỷ luật tương xứng; chủ động cung cấp thông tin về người cùng vi phạm; chủ động chấm dứt vì phạm, khắc phục hậu quả, nộp lại tài sản. Các phương án còn lại là tình tiết tăng nặng.",mn:"Ciiảm nhẹ: chủ động báo cáo, tự nhận lỗi, khắc phục hậu quả, nộp lại tài sản.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, tình tiết nào sau đây là tình tiết GIẢM NHẸ mức kỷ luật?",o:["Đối phó, quanh co, cản trở quá trình kiểm tra, thanh tra","Chủ động báo cáo vi phạm, tự giác nhận trách nhiệm và tự nhận hình thức kỷ luật tương xứng","Vi phạm có tổ chức, là người chủ mưu","Bao che cho người vi phạm, trù dập người tố cáo"],c:1},{id:"vb10-44",s:"PHÂN BỐ SUNG 1- CHƯƠNG I: NGUYÊN TẮC, THỜI HIỆU - THỜI HẠN, CHƯA XEM XÉT, MIỄN/GIẢM NHẸ/TĂNG NẶNG (TRỌNG TÂM)",gt:"Tình tiết tăng nặng gồm: không kiểm điểm, không sửa chữa, không bồi hoàn; đối phó, quanh co, cản trở, bao che, trù dập; vi phạm có tổ chức, là chủ mưu, làm sai lệch chứng cứ; và lợi dụng chức vụ, quyền hạn, lợi dụng thiên tai, dịch bệnh... để trục lợi.",mn:"lăng nặng: không sửa chữa — đối phó, bao che — chủ mưu - lợi dụng chức vụ, thiên tai trục lợi.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, tình tiết nào sau đây là tình tiết TĂNG NẶNG mức kỷ luật?",o:["Tự giác nộp lại tiền, tài sản do vi phạm mà có","Lợi dụng chức vụ, quyền hạn; lợi dụng tình trạng thiên tai, dịch bệnh để trục lợi","Chủ động chấm dứt hành vi vi phạm","Chủ động cung cấp thông tin, hồ sơ về người cùng vi phạm"],c:1},{id:"vb10-45",s:"PHÂN BỐ SUNG 1- CHƯƠNG I: NGUYÊN TẮC, THỜI HIỆU - THỜI HẠN, CHƯA XEM XÉT, MIỄN/GIẢM NHẸ/TĂNG NẶNG (TRỌNG TÂM)",cc:"Khoản 6 Điều 2 Nghị định số 172/2025/NĐ- CP.",gt:"Trường hợp bị kỷ luật về đảng bằng hình thức cao nhất liên quan đến hoạt động công vụ thì cơ quan tham mưu về tổ chức cán bộ báo cáo cấp có thẩm quyền xem xét, quyết định xử lý kỷ luật hành chính bằng hình thức cao nhất.",mn:"KL đảng cao nhất (liên quan công vụ) -› KL hành chính hình thức cao nhất. 16 LÀI LIỆU ÔN CE CÔNG €HUC VIÊN CHỨC FÐI NGUYỄN YONA 09953502H1",t:"m",q:"Một tình huống vận dụng: Ông B (công chức, đảng viên) bị xử lý kỷ luật về đảng bằng hình thức cao nhất liên quan đến hoạt động công vụ. Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, việc xử lý kỷ luật hành chính được thực hiện như thế nào?",o:["Cơ quan tham mưu về tổ chức cán bộ báo cáo cấp có thẩm quyền xem xét, quyết định xử lý kỷ luật hành chính bằng hình thức cao nhất","Không cần xử lý kỷ luật hành chính","Chỉ khiển trách về mặt hành chính","Tự động chuyển thành buộc thôi việc mà không cần xem xét"],c:0},{id:"vb10-46",s:"PHÂN BỐ SUNG 1- CHƯƠNG I: NGUYÊN TẮC, THỜI HIỆU - THỜI HẠN, CHƯA XEM XÉT, MIỄN/GIẢM NHẸ/TĂNG NẶNG (TRỌNG TÂM)",cc:"khoan ÍÍ liệu 2 Nghị định số 122 20205,NĐ- P.",gt:"Không được cử người thân thích (vợ. chõng. cha, mẹ, con, anh, chị, em ruột...) hoặc người có quyền, nghĩa vụ liên quan đến hành vi vi phạm làm thành viên Hội đồng kỷ luật hoặc người chủ trì cuộc họp kiểm điểm.",mn:"Cấm làm thành viên HĐKL: người thân thích + người có quyền lợi liên quan vụ việc.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, người nào sau đây KHÔNG được cử làm thành viên Hội đồng kỷ luật hoặc người chủ trì cuộc họp kiểm điểm?",o:["Đại diện bộ phận tham mưu về tổ chức cán bộ","Người đứng đầu cơ quan có thẩm quyền xử lý kỷ luật","Vợ, chồng, cha đẻ, mẹ đẻ, con đẻ, anh, chị, em ruột... hoặc người có quyền, nghĩa vụ liên quan đến hành vi vi phạm","Đại diện lãnh đạo cơ quan trực tiếp sử dụng công chức"],c:2},{id:"vb10-47",s:"PHÂN BỐ SUNG 1- CHƯƠNG I: NGUYÊN TẮC, THỜI HIỆU - THỜI HẠN, CHƯA XEM XÉT, MIỄN/GIẢM NHẸ/TĂNG NẶNG (TRỌNG TÂM)",cc:"khoan ð ‡iều ö Nghị định số 172. 20053 MỘ-CP.",gt:"Nguyên tắc: không áp dụng hình thức xử phạt hành chính thay cho hình thức kỷ luật; xử lý kỷ luật hành chính không thay cho truy cứu trách nhiệm hình sự nếu hành vi vi phạm đến mức bị xử lý hình sự.",mn:"KL hành chính Z thay xử phạt hành chính; Z thay truy cứu hình sự.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, nguyên tắc xử lý kỷ luật về mối quan hệ giữa kỷ luật hành chính và trách nhiệm hình sự được quy định như thế nào?",o:["Xử lý kỷ luật hành chính thay cho việc truy cứu trách nhiệm hình sự","Chỉ xử lý hình sự, bỏ qua kỷ luật hành chính","Nếu đã xử lý hình sự thì không xử lý kỷ luật hành chính","Không áp dụng xử phạt hành chính thay cho kỷ luật; xử lý kỷ luật hành chính không thay cho truy cứu trách nhiệm hình sự nếu hành vi đến mức bị xử lý hình sự"],c:3},{id:"vb10-48",s:"PHÂN BỐ SUNG 1- CHƯƠNG I: NGUYÊN TẮC, THỜI HIỆU - THỜI HẠN, CHƯA XEM XÉT, MIỄN/GIẢM NHẸ/TĂNG NẶNG (TRỌNG TÂM)",cc:"hhoàn Ð ‡)iệeu ¬ äYQhi định số 1272.2005. NI -C P.",gt:"Không tính vào thời hiệu, thời hạn: thời gian chưa xem xét xử lý kỷ luật (Điều 3); thời gian điều tra, truy tố, xét xử theo thủ tục tố tụng hình sự (nếu có); thời gian khiếu nại hoặc khởi kiện vụ án hành chính cho đến khi ra quyết định xử lý kỷ luật thay thế.",mn:"Không tính vào thời hiệu /thời hạn: thời gian chưa xem xét - tố tụng hình sự — khiếu nại:khởi kiện..17 LÀI LIỆU ÔN CE CÔNG €HUC VIÊN CHỨC FÐI NGUYỄN YONA 09953502H1",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, nội dung nào sau đây KHÔNG được tính vào thời hiệu, thời hạn xử lý kỷ luật?",o:["Thời gian nghỉ phép năm của cán bộ, công chức","Thời gian cán bộ, công chức đi công tác","Thời gian điều tra, truy tố, xét xử theo thủ tục tố tụng hình sự (nếu có)","Thời gian tham gia hội họp của cơ quan"],c:2},{id:"vb10-49",s:"PHÂN BỐ SUNG 1- CHƯƠNG I: NGUYÊN TẮC, THỜI HIỆU - THỜI HẠN, CHƯA XEM XÉT, MIỄN/GIẢM NHẸ/TĂNG NẶNG (TRỌNG TÂM)",cc:"Khoản 10 Điều 2 Nghị định số 172/2025/NĐ-CP.",gt:"Trường hợp này, cơ quan mới thực hiện việc xem xét xử lý kỷ luật và áp dụng hình thức tương ứng với vị trí hiện đảm nhiệm; cơ quan cử có trách nhiệm phối hợp, cung cấp toàn bộ hồ sơ liên quan.",mn:"Vi phạm ở cơ quan cử, phát hiện ở cơ quan mới. ¬ cơ quan mới xử lý, cơ quan cử cung cấp hồ sơ. 18 Phạm vi: liều ö đến Điều 12 — các hành vi bị xử lý kỷ luật và mức độ hậu quả: các hình thức kỷ luật; điều kiện áp dụng từng hình thức hRý luật: khiển trách, cảnh cáo, cách chức, buộc thôi việc, bãi nhiệm.",t:"m",q:"Một tình huống vận dụng: Bà C có hành vi vi phạm khi đang công tác tại cơ quan cử, sau khi chuyển sang cơ quan mới mới bị phát hiện và vẫn còn trong thời hiệu. Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, việc xử lý kỷ luật do cơ quan nào thực hiện?",o:["Cơ quan mới thực hiện xem xét xử lý kỷ luật; cơ quan cử có trách nhiệm phối hợp, cung cấp hồ sơ","Không xử lý vi đã chuyển công tác","Cơ quan cử nơi xảy ra hành vi vi phạm thực hiện","Hai cơ quan cùng ra quyết định kỷ luật"],c:0},{id:"vb10-50",s:"CHƯƠNG II - CÁC HÀNH VI VI PHẠM VÀ HÌNH THỨC KỶ LUẬT ĐỐI VỚI CÁN BỘ, CÔNG CHỨC",cc:"Khoan I Điều 6 Nghị định số 172:2025/NM)D- CD.",gt:"Hành vi bị xử lý kỷ luật gồm: vi phạm quy định của Đảng liên quan đến hoạt động công vụ; vi phạm nghĩa vụ của cán bộ, công chức; làm những việc không được làm; vi phạm đạo đức công vụ, văn hóa giao tiếp ở công sở, với Nhân dân; vi phạm nội quy, quy chế của cơ quan.",mn:"Hành vi bị kỷ luật: quy định Đăng - nghĩa vụ - việc không được làm - đạo đức, văn hóa - nội quy, quy chế.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, các hành vi nào sau đây thuộc nhóm hành vi bị xử lý kỷ luật?",o:["Chỉ vi phạm pháp luật về phòng, chống tham nhũng","Chỉ vi phạm về tài chính, kế toán","Chỉ vi phạm nội quy, quy chế của cơ quan","Vi phạm quy định của Đảng liên quan đến hoạt động công vụ; vì phạm nghĩa vụ của cán bộ, công chức; làm những việc không được làm; vi phạm đạo đức công vụ, văn hóa giao tiếp; vi phạm nội quy, quy chế của cơ quan"],c:3},{id:"vb10-51",s:"CHƯƠNG II - CÁC HÀNH VI VI PHẠM VÀ HÌNH THỨC KỶ LUẬT ĐỐI VỚI CÁN BỘ, CÔNG CHỨC",cc:"Khoản 2 Điều 6 Nghị định số 172/2025/NĐ-CP.",gt:"Mức độ hành vi vi phạm gồm ba mức: ít nghiêm trọng (tác động nội bộ, ảnh hưởng uy tín cơ quan); nghiêm trọng (tác động ngoài nội bộ, gây dư luận xấu, giảm uy tín); rất nghiêm trọng (tác động toàn xã hội, dư luận rất bức xúc, mất uy tín). ® Miẹo nhớ: 3 mức: ít nghiêm trọng - nghiêm trọng - rất nghiêm trọng.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, mức độ của hành vi vi phạm được phân loại thành nhưng mức nào?",o:["Nhẹ; trung bình; năng","Ít nghiêm trọng: nghiêm trọng: rất nghiêm trọng","Ít nghiêm trọng: nghiêm trọng: đặc biệt nghiêm trọng","Vi phạm lần đầu; tái phạm; vi phạm nhiều lần"],c:1},{id:"vb10-52",s:"CHƯƠNG II - CÁC HÀNH VI VI PHẠM VÀ HÌNH THỨC KỶ LUẬT ĐỐI VỚI CÁN BỘ, CÔNG CHỨC",cc:"liêm c khoản 2 Điều 6 Nghị định số 172/2025/NĐ-CP, 19",gt:"Vi phạm gây hậu quả rất nghiêm trọng là vi phạm có tính chất, mức độ, tác hại rất lớn, phạm vi tác động đến toàn xã hội, gây dư luận rất bức xúc, làm mất uy tín của cơ quan. Phương án B là 'ít nghiêm trọng, C là nghiêm trọng'.",mn:"Rất nghiêm trọng: tác động toàn xã hội, dư luận rất bức xúc, mất uy tín.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, vi phạm gây hậu quả 'rất nghiêm trọng' được xác định như thế nào?",o:["Vi phạm có tác động ngoài phạm vi nội bộ, gây dư luận xấu","Vi phạm có tác động trong phạm vi nội bộ, ảnh hưởng đến uy tín của cơ quan","Vi phạm có tính chất, mức độ, tác hại rất lớn, phạm vi tác động đến toàn xã hội, gây dư luận rất bức xúc trong cán bộ, công chức và Nhân dân, làm mất uy tín của cơ quan, tổ chức, đơn vị công tác","Vi phạm lần đầu, chưa gây hậu quả"],c:2},{id:"vb10-53",s:"CHƯƠNG II - CÁC HÀNH VI VI PHẠM VÀ HÌNH THỨC KỶ LUẬT ĐỐI VỚI CÁN BỘ, CÔNG CHỨC",cc:"liệu 8 Nghị định số 172/2025/NĐ-CP.",gt:"Khiển trách áp dụng đối với cán bộ, công chức có hành vi vi phạm lần đầu, gây hậu quả ít nghiêm trọng (trừ một số trường hợp riêng), thuộc các nhóm: vi phạm nghĩa vụ, việc không được làm, đạo đức công vụ, nội quy, quy chế; pháp luật về phòng, chống tham nhữủng, tiết kiệm; tập trung dân chủ, phát ngôn; đầu tư, đất đai, tài chính... §® Miẹo nhớ: Khiển trách: vi phạm lần đầu, ít nghiêm trọng.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, hình thức kỷ luật khiển trách áp dụng đối với cán bộ, công chức trong trường hợp nào?",o:["Sử dụng văn bằng giả để được tuyển dụng","Có hành vi vi phạm gây hậu quả rất nghiêm trọng","Đã bị cảnh cáo mà tái phạm","Có hành vi vi phạm lần đầu, gây hậu quả ít nghiêm trọng (trừ một số trường hợp riêng), thuộc các nhóm vi phạm về nghĩa vụ, việc không được làm, đạo đức công vụ, nội quy, quy chế và các quy định khác của pháp luật"],c:3},{id:"vb10-54",s:"CHƯƠNG II - CÁC HÀNH VI VI PHẠM VÀ HÌNH THỨC KỶ LUẬT ĐỐI VỚI CÁN BỘ, CÔNG CHỨC",cc:"liệu 9 Nghị định số 172/2025/NĐ-CP.",gt:"Cảnh cáo áp dụng khi: đã bị khiển trách mà tái phạm; hoặc vi phạm lần đầu gây hậu quả nghiêm trọng: hoặc cán bộ, công chức lãnh đạo, quản lý không thực hiện đúng chức trách, người đứng đầu để xảy ra vi phạm pháp luật nghiêm trọng trong phạm vi phụ trách mà không có biện pháp ngăn chặn (dự lần đầu, ít nghiêm trọng).",mn:"Cảnh cáo: khiển trách mà tái phạm / lần đầu nghiêm trọng / lãnh đạo không làm dụng chức trách.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, hình thức kỷ luật cảnh cáo áp dụng đối với cán bộ, công chức trong trường hợp nào?",o:["Có hành vi vi phạm lần đầu gây hậu quả ít nghiêm trọng","Đã bị khiển trách mà tái phạm; hoặc có hành vi vi phạm lần đầu gây hậu quả nghiêm trọng: hoặc cán bộ, công chức lãnh đạo, quản lý không thực hiện đúng chức trách, người đứng đầu để xảy ra vi phạm nghiêm trọng trong phạm vi phụ trách","Nghiện ma túy","Sử dụng văn bằng giả để được tuyển dụng"],c:1},{id:"vb10-55",s:"CHƯƠNG II - CÁC HÀNH VI VI PHẠM VÀ HÌNH THỨC KỶ LUẬT ĐỐI VỚI CÁN BỘ, CÔNG CHỨC",cc:"Diểu IU Nghị định số 172-205 NEĐ-C. Đ.",gt:"Hình thức cách chức chỉ áp dụng đối với cán bộ, công chức giữ chức vụ lãnh đạo, quản lý. Người không giữ chức vụ thì không thể bị cách chức.",mn:"Cách chức: chỉ với người giữ chức vụ lãnh đạo, quản lý.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, hình thức kỷ luật cách chức áp dụng đối với đối tượng nào?",o:["Cán bộ, công chức giữ chức vụ lãnh đạo, quản lý","Mọi cán bộ, công chức không phân biệt chức vụ","Công chức không giữ chức vụ lãnh đạo, quản lý „20 LÀI LIỆU ÔN CE CÔNG €HUC VIÊN CHỨC FÐI NGUYỄN YONA 09953502H1","Cán bộ do bầu cử"],c:0},{id:"vb10-56",s:"CHƯƠNG II - CÁC HÀNH VI VI PHẠM VÀ HÌNH THỨC KỶ LUẬT ĐỐI VỚI CÁN BỘ, CÔNG CHỨC",cc:"Điều!P Nghị định vô E22 2005. NĐ CĐ.",gt:"Cách chức áp dụng khi: đã bị cảnh cáo mà tái phạm; hoặc vi phạm lần đầu gây hậu quả rất nghiêm trọng nhưng chưa đến mức buộc thôi việc, bãi nhiệm, có thái độ tiếp thu, sửa chữa; hoặc sử dụng giấy tờ không hợp pháp để được quy hoạch, bầu cử, phê chuẩn, bổ nhiệm vào chức vụ.",mn:"Cách chức: cảnh cáo mà tái phạm ¿ rất nghiêm trọng nhưng tiếp thu ¿ giấy tờ không hợp pháp để được bổ nhiệm.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, hình thức kỷ luật cách chức áp dụng đối với cán bộ, công chức lãnh đạo, quản lý trong trường hợp nào?",o:["Sử dụng văn bằng giả để được tuyển dụng","Vi phạm lần đầu gây hậu quả ít nghiêm trọng","Nghiện ma túy","Đã bị cảnh cáo mà tái phạm; hoặc vi phạm lần đầu gây hậu quả rất nghiêm trọng nhưng chưa đến mức buộc thôi việc, bãi nhiệm và có thái độ tiếp thu, sửa chữa; hoặc sử dụng giấy tờ không hợp pháp để được quy hoạch, bầu cử, phê chuẩn, bổ nhiệm vào chức vụ"],c:3},{id:"vb10-57",s:"CHƯƠNG II - CÁC HÀNH VI VI PHẠM VÀ HÌNH THỨC KỶ LUẬT ĐỐI VỚI CÁN BỘ, CÔNG CHỨC",cc:"Điều 11 Nghị định vô 172 2025 9E CĐ.",gt:"Buộc thôi việc áp dụng với công chức khi: đã bị cách chức (lãnh đạo, quản lý) hoặc cảnh cáo (không giữ chức vụ) mà tái phạm; vi phạm lần đầu rất nghiêm trọng nhưng không tiếp thu, sửa chữa; sử dụng văn bằng, chứng chỉ gia để được tuyển dụng: nghiện ma túy (có kết luận của cơ sở v tế hoặc thông báo của cơ quan có thẩm quyền).",mn:"Buộc thôi việc: cách chức/cảnh cáo mà tái phạm - rất nghiêm trọng không tiếp thu — văn bằng giả để tuyển dụng - nghiện ma túy. 21",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, hình thức kỷ luật buộc thôi việc áp dụng đối với công chức trong trường hợp nào?",o:["Đã bị cách chức (với lãnh đạo, quản lý) hoặc cảnh cáo (với người không giữ chức vụ) mà tái phạm; hoặc vi phạm lần đầu rất nghiêm trọng nhưng không tiếp thu, sửa chữa; hoặc sử dụng văn bằng, chứng chỉ gia để được tuyển dụng; hoặc nghiện ma túy","Vi phạm lần đầu gây hậu quả ít nghiêm trọng","Sử dụng giấy tờ không hợp pháp để được bổ nhiệm","Để xảy ra vi phạm trong phạm vi phụ trách"],c:0},{id:"vb10-58",s:"CHƯƠNG II - CÁC HÀNH VI VI PHẠM VÀ HÌNH THỨC KỶ LUẬT ĐỐI VỚI CÁN BỘ, CÔNG CHỨC",gt:"Công chức sử dụng văn bằng, chứng chỉ, giấy chứng nhận, xác nhận giả hoặc không hợp pháp để được tuyển dụng vào cơ quan thì bị buộc thôi việc. (IL,ưu ý phân biệt: dùng giấy tờ không hợp pháp đề được quy hoạch, bổ nhiệm thì bị cách chức.) ® Miẹo nhớ: Văn bằng giả để tuyển dụng. buộc thôi việc.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, công chức sử dụng [......... | để được tuyển dụng vào cơ quan, tổ chức, đơn vị thì bị áp dụng hình thức kỷ luật buộc thôi việc.",o:["giấy tờ không hợp pháp để được quy hoạch","văn bằng, chứng chỉ, giấy chứng nhận, xác nhận giả hoặc không hợp pháp","hồ sơ không đầy đủ thành phần","lý lịch chưa được xác nhận"],c:1},{id:"vb10-59",s:"CHƯƠNG II - CÁC HÀNH VI VI PHẠM VÀ HÌNH THỨC KỶ LUẬT ĐỐI VỚI CÁN BỘ, CÔNG CHỨC",cc:"Điều 12 Nghị định số 172:2025/NĐ-CP.",gt:"Bãi nhiệm áp dụng đối với cán bộ có hành vi vi phạm theo Luật Tổ chức Quốc hội, Luật Tổ chức chính quyền địa phương, Luật Bầu cử đại biểu Quốc hội và đại biểu Hội đồng nhân dân và quy định khác có liên quan; thẩm quyền, trình tự, thủ tục bãi nhiệm theo quy định của pháp luật.",mn:"Bãi nhiệm: với cán bộ (theo Luật TỔ chức QH, TCCQDP, Bầu cử).",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, hình thức kỷ luật bãi nhiệm áp dụng đối với đối tượng nào và theo quy định nào?",o:["Áp dụng đối với mọi cán bộ, công chức","Áp dụng đối với công chức lãnh đạo, quản lý","Áp dụng đối với cán bộ có hành vi vi phạm theo quy định của Luật Tổ chức Quốc hội, Luật Tổ chức chính quyền địa phương, Luật Bầu cử đại biểu Quốc hội và đại biểu Hội đồng nhân dân và quy định khác có liên quan","Áp dụng đối với công chức không giữ chức vụ"],c:2},{id:"vb10-60",s:"CHƯƠNG II - CÁC HÀNH VI VI PHẠM VÀ HÌNH THỨC KỶ LUẬT ĐỐI VỚI CÁN BỘ, CÔNG CHỨC",cc:"Khoản 4 Điều L1 Nghị định số 172/2025/NĐ-CP.",gt:"Công chức nghiện ma túy bị buộc thôi việc; trường hợp này phải có kết luận của cơ sở v tế hoặc thông báo của cơ quan có thẩm quyền.",mn:"Nghiện ma túy _› buộc thôi việc (có kết luận y tế/thông báo cơ quan có thẩm quyền). ¡1.22 LÀI LIỆU ÔN CE CÔNG €HUC VIÊN CHỨC FÐI NGUYỄN YONA 09953502H1",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, công chức nghiện ma túy bị áp dụng hình thức kỷ luật nào, và cần có điều kiện gì?",o:["Cách chức; nếu là công chức lãnh đạo, quản lý","Cảnh cáo; không cần điều kiện gì","Khiển trách; chỉ cần có dấu hiệu nghĩ ngờ","Buộc thôi việc; phải có kết luận của cơ sở y tế hoặc thông báo của cơ quan có thẩm quyền"],c:3},{id:"vb10-61",s:"CHƯƠNG II - CÁC HÀNH VI VI PHẠM VÀ HÌNH THỨC KỶ LUẬT ĐỐI VỚI CÁN BỘ, CÔNG CHỨC",cc:"Điều 8 Nghị định số I2 7033 NĐ-CP,",gt:"Ông A vi phạm lần đầu, gây hậu quả ít nghiêm trọng thì hình thức phù hợp là khiển trách.",mn:"Lần đầu, ít nghiêm trọng.. khiển trách.",t:"m",q:"Một tình huống: Ông A là công chức không giữ chức vụ lãnh đạo, quản lý, vi phạm lần đầu gây hậu quả ít nghiêm trọng về nội quy cơ quan. Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, hình thức kỷ luật phù hợp đối với ông A là gì?",o:["Cách chức","Cảnh cáo","Khiếển trách","Buộc thôi việc"],c:2},{id:"vb10-62",s:"CHƯƠNG II - CÁC HÀNH VI VI PHẠM VÀ HÌNH THỨC KỶ LUẬT ĐỐI VỚI CÁN BỘ, CÔNG CHỨC",cc:"Khoản 1 Điều 9 Nghị định số 172-2005 NĐ - CD.",gt:"Công chức đã bị khiển trách mà tái phạm thì bị áp dụng hình thức cảnh cáo.",mn:"Đã khiển trách mà tái phạm. cảnh cáo.",t:"m",q:"Một tình huống: Bà B là công chức đã bị kỷ luật khiển trách, trong thời hạn quy định lại tái phạm chính hành vi đã bị kỷ luật. Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, hình thức kỷ luật áp dụng đối với bà B là gì?",o:["Khiển trách lần hai","Cảnh cáo","Cách chức","Buộc thôi việc"],c:1},{id:"vb10-63",s:"CHƯƠNG II - CÁC HÀNH VI VI PHẠM VÀ HÌNH THỨC KỶ LUẬT ĐỐI VỚI CÁN BỘ, CÔNG CHỨC",cc:"Khoốn 1 Điều 10 Nghị định số 172/2025-7NĐ-CP.",gt:"Công chức lãnh đạo, quản lý đã bị cảnh cáo mà tái phạm thì bị áp dụng hình thức cách chức.",mn:"Lãnh đạo đã cảnh cáo mà tái phạm -.. cách chức.",t:"m",q:"Một tình huống: Ông C là công chức lãnh đạo, đã bị kỷ luật cảnh cáo, trong thời hạn quy định lại tái phạm. Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, hình thức kỷ luật áp dụng đối với ông C là gì?",o:["Cách chức","Cảnh cáo lần hai","Khiển trách","Bãi nhiệm"],c:0},{id:"vb10-64",s:"CHƯƠNG II - CÁC HÀNH VI VI PHẠM VÀ HÌNH THỨC KỶ LUẬT ĐỐI VỚI CÁN BỘ, CÔNG CHỨC",cc:"Khoản 3 Điều 10 Nghị định số 172/2025/NĐ-CP.",gt:"Hành vi sử dụng giấy tờ không hợp pháp để được quy hoạch, bầu cử, phê chuẩn, bổ nhiệm vào chức vụ bị áp dụng hình thức cách chức. Cần phân biệt với việc dùng văn bằng giả để được tuyển dụng (bị buộc thôi việc).",mn:"C;iấy tờ không hợp pháp để bổ nhiệm —. cách chức; văn bằng giả để tuyển dụng. buộc thôi việc.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, hành vi 'sử dụng giấy tờ không hợp pháp để được quy hoạch, bầu cử, phê chuẩn, bổ nhiệm vào chức vụ' bị áp dụng hình thức kỷ luật nào?",o:["Cảnh cáo","Khiển trách","Buộc thôi việc..23","Cách chức"],c:3},{id:"vb10-65",s:"CHƯƠNG II - CÁC HÀNH VI VI PHẠM VÀ HÌNH THỨC KỶ LUẬT ĐỐI VỚI CÁN BỘ, CÔNG CHỨC",gt:"Điểm phân biệt: giấy tờ không hợp pháp để được quy hoạch, bầu cử, bổ nhiệm vào CHỨC VỤ. cách chức; văn bằng, chứng chỉ gia để được TUYỂN DỤNG.¬- buộc thôi việc.",mn:"Đề được chức vụ -¬ cách chức; đề được tuyển dụng - buộc thôi việc.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, phân biệt giữa 'cách chức' và 'buộc thôi việc' đối với hành vi sử dụng giấy tờ gia, nội dung nào sau đây là DÙNG?",o:["Sử dụng giấy tờ không hợp pháp để được quy hoạch, bầu cử, bổ nhiệm vào chức vụ thì bị cách chức; sử dụng văn bằng, chứng chỉ gia để được tuyển dụng thì bị buộc thôi việc","Cả hai hành vi đều bị buộc thôi việc","Cả hai hành vi đều bị cách chức","Cả hai hành vi đều chỉ bị cảnh cáo"],c:0},{id:"vb10-66",s:"CHƯƠNG II - CÁC HÀNH VI VI PHẠM VÀ HÌNH THỨC KỶ LUẬT ĐỐI VỚI CÁN BỘ, CÔNG CHỨC",cc:"J)iệm b khoản 2 liệu 6 Nghị định số 172/20/25/NI1D-C.P.",gt:"Vi phạm gây hậu quả nghiêm trọng là vi phạm có tác hại lớn, tác động ngoài phạm vi nội bộ, gây dư luận xấu, làm giảm uy tín của cơ quan. Khác với 'ít nghiêm trọng' (nội bộ) và 'rất nghiêm trọng' (toàn xã hội).",mn:"Nghiêm trọng: tác động ngoài nội bộ, dư luận xấu, giảm uy tín.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, vi phạm gây hậu quả 'nghiêm trọng' được xác định như thế nào?",o:["Vi phạm tác động đến toàn xã hội, gây dư luận rất bức xúc","Vi phạm tác động trong phạm vi nội bộ, ảnh hưởng uy tín cơ quan","Vi phạm có tính chất, mức độ, tác hại lớn, tác động ngoài phạm vi nội bộ, gây dư luận xấu trong cán bộ, công chức và Nhân dân, làm giảm uy tín của cơ quan, tổ chức, đơn vị công tác","Vi phạm chưa gây hậu quả"],c:2},{id:"vb10-67",s:"CHƯƠNG II - CÁC HÀNH VI VI PHẠM VÀ HÌNH THỨC KỶ LUẬT ĐỐI VỚI CÁN BỘ, CÔNG CHỨC",cc:"Khoản 2 Điều 7 Nghị định số 172/2025,/NI-CP.",gt:"Hình thức kỷ luật đối với công chức: khiển trách; cảnh cáo; cách chức (với công chức lãnh đạo, quản lý); buộc thôi việc. Công chức không có hình thức bãi nhiệm' (đó là của cán bộ).",mn:"Công chức: khiển trách - cảnh cáo - cách chức - buộc thôi việc.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, các hình thức kỷ luật nào sau đây áp dụng đối với CÔNG CHỨC?",o:["Khiển trách; cảnh cáo; cách chức; bãi nhiệm","Khiển trách; cảnh cáo; cách chức (với công chức lãnh đạo, quản lý); buộc thôi việc","Khiển trách; cảnh cáo; hạ bậc lương: buộc thôi việc","Cảnh cáo; giảng chức; cách chức; buộc thôi việc 1.24"],c:1},{id:"vb10-68",s:"CHƯƠNG II - CÁC HÀNH VI VI PHẠM VÀ HÌNH THỨC KỶ LUẬT ĐỐI VỚI CÁN BỘ, CÔNG CHỨC",cc:"khoan I Điều 7 Nghị định số 172/2025,NID-CP.",gt:"Hình thức kỷ luật đối với cán bộ: khiển trách; cảnh cáo; cách chức (với cán bộ được phê chuẩn, bổ nhiệm hoặc chỉ định); bãi nhiệm. Cán bộ không có hình thức 'buộc thôi việc.",mn:"Cán bộ: khiển trách — cảnh cáo - cách chức - bãi nhiệm.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, các hình thức kỷ luật nào sau đây áp dụng đối với CÁN BỘ?",o:["Cảnh cáo; giảng chức; cách chức; bãi nhiệm","Khiển trách; cảnh cáo; cách chức; buộc thôi việc","Khiển trách; cảnh cáo; hạ bậc lương; bãi nhiệm","Khiển trách; cảnh cáo; cách chức (với cán bộ được phê chuẩn, bổ nhiệm hoặc chỉ định); bãi nhiệm"],c:3},{id:"vb10-69",s:"CHƯƠNG II - CÁC HÀNH VI VI PHẠM VÀ HÌNH THỨC KỶ LUẬT ĐỐI VỚI CÁN BỘ, CÔNG CHỨC",cc:"Điểm b khoản 3 Điều 9 Nghị định số 172/2025/NĐ-CP.",gt:"Người đứng đầu để xảy ra hành vi vi phạm pháp luật nghiêm trọng trong phạm vi phụ trách mà không có biện pháp ngăn chặn thì bị cảnh cáo (dự vi phạm lần đầu, hậu quả ít nghiêm trọng) — đề cao trách nhiệm người đứng đầu.",mn:"Người đứng đầu để xảy ra vì phạm nghiêm trọng, không ngăn chặn ¬ cảnh cáo.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, người đứng đầu cơ quan, tổ chức, đơn vị để xảy ra hành vi vi phạm pháp luật nghiêm trọng trong phạm vi phụ trách mà không có biện pháp ngăn chặn thì bị áp dụng hình thức kỷ luật nào (dự vi phạm lần đầu, hậu quả ít nghiêm trọng)?",o:["Khiển trách","Cảnh cáo","Cách chức","Buộc thôi việc"],c:1},{id:"vb10-70",s:"CHƯƠNG II - CÁC HÀNH VI VI PHẠM VÀ HÌNH THỨC KỶ LUẬT ĐỐI VỚI CÁN BỘ, CÔNG CHỨC",cc:"Khoản 2 Điều 11 Nghị định số 172/2025/NĐ-CP. ¬r.n 1..25 LÀI LIỆU ÔN CE CÔNG €HUC VIÊN CHỨC FÐI NGUYỄN YONA 09953502H1",gt:"Công chức vi phạm lần đầu gây hậu quả rất nghiêm trọng, không tiếp thu, sửa chữa, không khác phục hậu quả và thuộc trường hợp tăng nặng thì bị buộc thôi việc. (Nếu có thái độ tiếp thu, sửa chữa và là lãnh đạo, quản lý thì có thể chỉ cách chức.)",mn:"Rất nghiêm trọng + không tiếp thu, không khắc phục. buộc thôi việc.",t:"m",q:"Một tình huống: Ông D là công chức, vi phạm lần đầu gây hậu quả rất nghiêm trọng, không có thái độ tiếp thu, sửa chữa, không khác phục hậu quả và thuộc trường hợp có tình tiết tăng nặng. Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, hình thức kỷ luật phù hợp đối với ông D là gì?",o:["Khiển trách","Cảnh cáo","Buộc thôi việc","Cách chức"],c:2},{id:"vb10-71",s:"CHƯƠNG II - CÁC HÀNH VI VI PHẠM VÀ HÌNH THỨC KỶ LUẬT ĐỐI VỚI CÁN BỘ, CÔNG CHỨC",cc:"liều J1 Nghị định số 172 2005. NĐ-CP.",gt:"Cả ba hành vi đều dân đến buộc thôi việc đối với công chức: sử dụng văn bằng giả để được tuyển dụng: nghiện ma túy (có kết luận y tế); đã bị cách chức mà tái phạm.",mn:"Buộc thôi việc: văn bằng giả tuyển dụng - nghiên ma túy — cách chức mà tái phạm.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, các hành vi sau có cùng dẫn đến hình thức kỷ luật buộc thôi việc đối với công chức hay không: (i) sử dụng văn bằng giả đề được tuyển dụng; (ii) nghiện ma túy; (iii) đã bị cách chức mà tái phạm?",o:["Cả ba hành vi đều dẫn đến buộc thôi việc","Chi hành vi (i) và (II) đúng","Chi hành vi () đúng","Không hành vi nào đúng"],c:0},{id:"vb10-72",s:"CHƯƠNG II - CÁC HÀNH VI VI PHẠM VÀ HÌNH THỨC KỶ LUẬT ĐỐI VỚI CÁN BỘ, CÔNG CHỨC",cc:"})iÖu ” và fheu TÚ Nghị định số 1722023 N9 CD.",gt:"Hình thức cách chức chỉ áp dụng với cán bộ, công chức giữ chức vụ lãnh đạo, quản lý. Công chức không giữ chức vụ thì không thể bị cách chức. Vì vậy phương án D sai.",mn:"Không giữ chức vụ thì không bị cách chức.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, nhận định nào sau đây về các hình thức kỷ luật là KHÔNG đúng?",o:["Cán bộ có thể bị khiển trách, cảnh cáo, cách chức, bãi nhiệm","Công chức có thể bị khiển trách, cảnh cáo, cách chức, buộc thôi việc","Công chức không giữ chức vụ lãnh đạo, quản lý văn có thể bị cách chức","Cách chức áp dụng đối với cán bộ, công chức giữ chức vụ lãnh đạo, quản lý"],c:2},{id:"vb10-73",s:"CHƯƠNG II - CÁC HÀNH VI VI PHẠM VÀ HÌNH THỨC KỶ LUẬT ĐỐI VỚI CÁN BỘ, CÔNG CHỨC",cc:"khuôn ì Điều 8 Nghị định số 1722 2035 N9 -CP.",gt:"Hành vi vi phạm quy định về quy chế tập trung dân chủ; tuyên truyền, phát ngôn; bảo vệ chính trị nội bộ mà lần đầu, gây hậu quả ít nghiêm trọng thì có thể bị khiển trách (theo các nhóm trường hợp áp dụng khiển trách)..826",mn:"Lần đầu, ít nghiêm trọng (tập trung dân chủ, phát ngôn...) ¬ khiển trách.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, hành vi 'vi phạm quy định về quy chế tập trung dân chủ; tuyên truyền, phát ngôn; bảo vệ chính trị nội bộ' gây hậu quả ít nghiêm trọng, lần đầu thì có thể bị áp dụng hình thức kỷ luật nào?",o:["Khiển trách","Cách chức","Buộc thôi việc","Bãi nhiệm"],c:0},{id:"vb10-74",s:"CHƯƠNG II - CÁC HÀNH VI VI PHẠM VÀ HÌNH THỨC KỶ LUẬT ĐỐI VỚI CÁN BỘ, CÔNG CHỨC",cc:"Các điều 7, 8, 9, 1U, 11, 12 Nghị định số 172/2025/NĐ- CĐ.",gt:"Thang hình thức kỷ luật theo mức độ tăng dân: khiển trách (lần đầu, ít nghiêm trọng), cảnh cáo (khiển trách mà tái phạm hoặc lần đầu nghiêm trọng) cách chức (cảnh cáo mà tái phạm, với người giữ chức vụ) ¬ buộc thôi việc (công chức) / bãi nhiệm (cán bộ).",mn:"Tháng: khiển rách. cảnh cáo.. cách chức.. buộc thôi việc/bãi nhiệm.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, phương án nào sau đây phản ánh ĐÚNG và ĐẦY ĐỦ nhất về thang hình thức kỷ luật theo mức độ vi phạm?",o:["Mọi vi phạm đều bị buộc thôi việc hoặc bãi nhiệm","Khiển trách (lần đầu, ít nghiêm trọng) ¬ cảnh cáo (khiển trách mà tái phạm hoặc lần đầu nghiêm trọng) - cách chức (cảnh cáo mà tái phạm, với người giữ chức vụ) ¬ buộc thôi việc/bãi nhiệm (mức cao nhất)","Chỉ có hại hình thức là khiển trách và buộc thôi việc","Hình thức kỷ luật không phù thuộc vào mức độ vi phạm"],c:1},{id:"vb10-75",s:"CHƯƠNG II - CÁC HÀNH VI VI PHẠM VÀ HÌNH THỨC KỶ LUẬT ĐỐI VỚI CÁN BỘ, CÔNG CHỨC",cc:"l)iêm a khoản 2 Điều 6 Nghị định số 172/2025/NĐ-CP.",gt:"Vi phạm gây hậu quả ít nghiêm trọng là vi phạm có tính chất, mức độ tác hại không lớn, tác động trong phạm vi nội bộ, ảnh hưởng đến uy tín của cơ quan.",mn:"Ít nghiêm trọng: tác động trong nội bộ, ảnh hưởng uy tín cơ quan.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, vi phạm gây hậu quả 'ít nghiêm trọng' được xác định như thế nào?",o:["Vi phạm gây hậu quả đặc biệt nghiêm trọng","Vi phạm tác động ngoài phạm vi nội bộ, gây dư luận xấu","Vi phạm tác động đến toàn xã hội","Vi phạm có tính chất, mức độ tác hại không lớn, tác động trong phạm vi nội bộ, làm ảnh hưởng đến uy tín của cơ quan, tổ chức, đơn vị công tác"],c:3},{id:"vb10-76",s:"CHƯƠNG II - CÁC HÀNH VI VI PHẠM VÀ HÌNH THỨC KỶ LUẬT ĐỐI VỚI CÁN BỘ, CÔNG CHỨC",cc:"Các điều 6, 9.9, 1D, II Nghị định số 172,/2025/M))-CP. 27 LÀI LIỆU ÔN CE CÔNG €HUC VIÊN CHỨC FÐI NGUYỄN YONA 09953502H1",gt:"Mức độ hậu quả (ít nghiêm trọng. nghiêm trọng, rất nghiêm trọng) cùng với yếu tố lần đầu/tái phạm và thái độ tiếp thu, khác phục là căn cứ xác định hình thức kỷ luật tương ứng. từ khiển trách đến buộc thôi việc, bãi nhiệm.",mn:"Hình thức kỷ luật = mức độ hậu quả + lần đầu/tái phạm + thái độ tiếp thu...828 Phôũn bổ sung cho Chương!I: phân biệt các hình thức kỷ luật đối với cán bộ và công chức; điều kiện áp dụng khiển trách, cảnh cáo, cách chức, buộc thôi việc, bãi nhiệm; tình huống vận dụng. Đáóạp án đối chiếu văn bản gốc.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, phương án nào sau đây phản ánh ĐÚNG mối quan hệ giữa mức độ hậu quả và hình thức kỷ luật?",o:["Mức độ hậu quả (ít nghiêm trọng, nghiêm trọng, rất nghiêm trọng) cùng với yếu tố lần đầu/tái phạm và thái độ tiếp thu là căn cứ để xác định hình thức kỷ luật tương ứng từ khiển trách đến buộc thôi việc, bãi nhiệm","Mức độ hậu quả không liên quan đến hình thức kỷ luật","Mọi mức độ hậu quả đều áp dụng hình thức khiển trách","Hình thức kỷ luật chỉ căn cứ vào chức vụ của người vi phạm"],c:0},{id:"vb10-77",s:"PHÂN BỐ SUNG 2 - CHƯƠNG II: CÁC HÌNH THỨC KỶ LUẬT VÀ HÀNH VI TƯƠNG ỨNG (TRỌNG TÂM)",cc:"Khoản 1 Điều 7 Nghị định số 172/2025/NĐ-CP.",gt:"Các hình thức kỷ luật đối với cán bộ: khiển trách, cảnh cáo, cách chức (đối với cán bộ được phê chuẩn, bổ nhiệm, chỉ định giữ chức vụ) và bãi nhiệm.",mn:"Cán bộ: khiển trách - cảnh cáo - cách chức - bãi nhiệm.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, các hình thức kỷ luật áp dụng đối với cán bộ gồm những hình thức nào?",o:["Khiển trách, cảnh cáo, hạ bậc lương, buộc thôi việc","Khiển trách, cảnh cáo, cách chức, buộc thôi việc","Khiển trách, cảnh cáo, giáng chức, cách chức","Khiển trách, cảnh cáo, cách chức, bãi nhiệm"],c:3},{id:"vb10-78",s:"PHÂN BỐ SUNG 2 - CHƯƠNG II: CÁC HÌNH THỨC KỶ LUẬT VÀ HÀNH VI TƯƠNG ỨNG (TRỌNG TÂM)",cc:"Khoản 2 Điều 7 Nghị định số 172.2025/NĐ-CP.",gt:"Các hình thức kỷ luật đối với công chức: khiển trách, cảnh cáo, cách chức (đối với công chức lãnh đạo, quản lý) và buộc thôi việc. (Không còn hình thức “hạ bậc lương”, “giảng chức” như quy định cử.)",mn:"Công chức: khiển trách - cảnh cáo - cách chức - buộc thôi việc.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, các hình thức kỷ luật áp dụng đối với công chức gồm những hình thức nào?",o:["Khiển trách, cảnh cáo, giáng chức, cách chức, buộc thôi việc","Khiển trách, cảnh cáo, hạ bậc lương, buộc thôi việc","Khiển trách, cảnh cáo, cách chức, buộc thôi việc","Khiển trách, cảnh cáo, cách chức, bãi nhiệm"],c:2},{id:"vb10-79",s:"PHÂN BỐ SUNG 2 - CHƯƠNG II: CÁC HÌNH THỨC KỶ LUẬT VÀ HÀNH VI TƯƠNG ỨNG (TRỌNG TÂM)",cc:"Điểm c khoản 2 Điều 7 Nghị định số 172/2025/NĐ-CP.",gt:"Hình thức cách chức chỉ áp dụng đối với công chức lãnh đạo, quản lý (người giữ chức vụ). Công chức không giữ chức vụ thì không áp dụng cách chức.",mn:"Cách chức: chỉ áp dụng với công chức lãnh đạo, quản lý. mm 29 LÀI LIỆU ÔN CE CÔNG €HUC VIÊN CHỨC FÐI NGUYỄN YONA 09953502H1",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, hình thức kỷ luật “cách chức” đối với công chức chỉ áp dụng cho đối tượng nào?",o:["Mọi công chức","Công chức lãnh đạo, quản lý","Công chức không giữ chức vụ lãnh đạo, quản lý","Công chức tập sự"],c:1},{id:"vb10-80",s:"PHÂN BỐ SUNG 2 - CHƯƠNG II: CÁC HÌNH THỨC KỶ LUẬT VÀ HÀNH VI TƯƠNG ỨNG (TRỌNG TÂM)",cc:"Điều 8 Nghị định số I2 2023 NĐ-CP,",gt:"Hình thức khiển trách áp dụng đối với cán bộ. công chức có hành vi vi phạm lần đầu, gây hậu quả ít nghiêm trọng (vi phạm nghĩa vụ, đạo đức công vụ, nội quy, pháp luật về phòng chống tham nhũng, đầu tư, đất đai, tài chính...)",mn:"Khiển trách: vi phạm lần đầu, hậu quả ít nghiêm trọng.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, hình thức kỷ luật khiển trách áp dụng đối với cán bộ, công chức trong trường hợp nào?",o:["Có hành vi vi phạm lần đầu, gây hậu quả ít nghiêm trọng thuộc các trường hợp luật định","Tái phạm sau khi đã bị cảnh cáo","Vi phạm lần đầu gây hậu quả rất nghiêm trọng","Sử dụng văn bằng giả để được tuyển dụng"],c:0},{id:"vb10-81",s:"PHÂN BỐ SUNG 2 - CHƯƠNG II: CÁC HÌNH THỨC KỶ LUẬT VÀ HÀNH VI TƯƠNG ỨNG (TRỌNG TÂM)",cc:"Nhooan ] và khoản 2 Điều 9 Nghị định số 172. 2025. NE- CĐ.",gt:"Hình thức cảnh cáo áp dụng khi: đã bị khiển trách mà tái phạm; hoặc vi phạm lần đầu gây hậu quả nghiêm trọng thuộc các trường hợp tại Điều 8; hoặc cán bộ lãnh đạo:người đứng đầu vi phạm lần đầu hậu quả ít nghiêm trọng trong một số trường hợp đặc thù.",mn:"Cảnh cáo: khiển trách rồi tái phạm, hoặc lần đầu hậu quả nghiêm trọng.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, hình thức kỷ luật cảnh cáo áp dụng đối với cán bộ, công chức trong trường hợp nào sau đây?",o:["Vi phạm lần đầu, gây hậu quả ít nghiêm trọng","Sử dụng văn bằng giả để được tuyển dụng","Nghiện ma túy","Đã bị khiển trách mà tái phạm, hoặc vi phạm lần đầu gây hậu quả nghiêm trọng"],c:3},{id:"vb10-82",s:"PHÂN BỐ SUNG 2 - CHƯƠNG II: CÁC HÌNH THỨC KỶ LUẬT VÀ HÀNH VI TƯƠNG ỨNG (TRỌNG TÂM)",cc:"khoan I và khoản! Liệu 1U Nghị định số 122 023 NE- CD.",gt:"Hình thức cách chức áp dụng đối với cán bộ, công chức lãnh đạo, quản lý khi: đã bị cảnh cáo mà tái phạm; vi phạm lần đầu gây hậu quả rất nghiêm trọng nhưng có thái độ tiếp thu, khác phục: hoặc sử dụng giấy tờ không hợp pháp để được quy hoạch, bầu cử, phê chuẩn, bổ nhiệm vào chức vụ.",mn:"Cách chức: cảnh cáo rồi tái phạm; hoặc dụng giấy tờ không hợp pháp để lên chức.. 30",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, hình thức kỷ luật cách chức áp dụng đối với cán bộ, công chức lãnh đạo, quản lý trong trường hợp nào sau đây?",o:["Vi phạm lần đầu, hậu quả ít nghiêm trọng","Đi muốn, về sớm nhiều lần","Đã bị cảnh cáo mà tái phạm; hoặc sử dụng giấy tờ không hợp pháp để được quy hoạch, bầu cử, bổ nhiệm vào chức vụ","Vi phạm nội quy cơ quan lần đầu"],c:2},{id:"vb10-83",s:"PHÂN BỐ SUNG 2 - CHƯƠNG II: CÁC HÌNH THỨC KỶ LUẬT VÀ HÀNH VI TƯƠNG ỨNG (TRỌNG TÂM)",cc:"Khoản 3 và khoản 4 Điều 11 Nghị định số 172.2025/NĐ-CP.",gt:"Hình thức buộc thôi việc áp dụng đối với công chức khi: đã bị cách chức/cảnh cáo mà tái phạm; vì phạm lần đầu gây hậu quả rất nghiêm trọng nhưng không tiếp thu, khắc phục; sử dụng văn bằng, chứng chỉ, giấy tờ giả để được tuyển dụng: hoặc nghiện ma túy (có kết luận của cơ sở v tế hoặc thông báo của cơ quan có thẩm quyền).",mn:"Buộc thôi việc: tái phạm nặng - băng cấp giả đề được tuyển dụng — nghiện ma túy.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, hình thức kỷ luật buộc thôi việc áp dụng đối với công chức trong trường hợp nào sau đây?",o:["Vi phạm nội quy cơ quan lần đầu","Sử dụng văn bằng, chứng chỉ, giấy chứng nhận, xác nhận giả hoặc không hợp pháp để được tuyển dụng: hoặc nghiện ma túy","Vi phạm đạo đức công vụ lần đầu, hậu quả ít nghiêm trọng","Chậm trễ trong xử lý công việc"],c:1},{id:"vb10-84",s:"PHÂN BỐ SUNG 2 - CHƯƠNG II: CÁC HÌNH THỨC KỶ LUẬT VÀ HÀNH VI TƯƠNG ỨNG (TRỌNG TÂM)",cc:"Khoản 3 Điều LÍ Nghị định số 172/2025/NĐ-CP.",gt:"Công chức sử dụng văn bằng, chứng chỉ gia hoặc không hợp pháp để được tuyển dụng bị áp dụng hình thức buộc thôi việc.",mn:"Bằng giả để được tuyển dụng. buộc thôi việc.",t:"m",q:"Một tình huống vận dụng: Ông D dụng bằng đại học giả để được tuyển dụng vào công chức, sau đó bị phát hiện. Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, ông D bị áp dụng hình thức kỷ luật nào?",o:["Khiển trách","Cảnh cáo","Cách chức","Buộc thôi việc"],c:3},{id:"vb10-85",s:"PHÂN BỐ SUNG 2 - CHƯƠNG II: CÁC HÌNH THỨC KỶ LUẬT VÀ HÀNH VI TƯƠNG ỨNG (TRỌNG TÂM)",cc:"khoản 1 Điều LÍ Nghị định số 172/2025/NĐ-CP.",gt:"Công chức không giữ chức vụ đã bị cảnh cáo mà tái phạm thì bị áp dụng hình thức buộc thôi việc (do không có hình thức cách chức đối với công chức không giữ chức vụ).",mn:"Công chức thường bị cảnh cáo + tái phạm ¬„ buộc thôi việc. 3 LÀI LIỆU ÔN CE CÔNG €HUC VIÊN CHỨC FÐI NGUYỄN YONA 09953502H1",t:"m",q:"Một tình huống vận dụng: Ông E là công chức không giữ chức vụ lãnh đạo, đã bị kỷ luật cảnh cáo, trong thời gian thi hành lại tái phạm hành vi đã bị kỷ luật. Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, ông E có thể bị áp dụng hình thức kỷ luật nào?",o:["Buộc thôi việc","Cảnh cáo lần hai","Khiển trách","Hạ bậc lương"],c:0},{id:"vb10-86",s:"PHÂN BỐ SUNG 2 - CHƯƠNG II: CÁC HÌNH THỨC KỶ LUẬT VÀ HÀNH VI TƯƠNG ỨNG (TRỌNG TÂM)",cc:"Điều J~ Nghị định số 172-205 NĐ-CP.",gt:"Hình thức bãi nhiệm áp dụng đối với cán bộ có hành vi vi phạm theo quy định của Luật Tổ chức Quốc hội, Luật Tổ chức chính quyền địa phương, Luật Bầu cử đại biểu Quốc hội và đại biểu Hội đồng nhân dân và quy định khác có liên quan.",mn:"Bãi nhiệm: chỉ áp dụng với cán bộ (theo Luật Tổ chức (3H, chính quyền địa phương, Bầu cử).",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, hình thức kỷ luật bãi nhiệm áp dụng đối với đối tượng nào?",o:["Công chức lãnh đạo, quản lý vi phạm nghiêm trọng","Cán bộ có hành vi vi phạm theo quy định của Luật Tổ chức Quốc hội, Luật Tổ chức chính quyền địa phương, Luật Bầu cử và quy định khác có liên quan","Công chức không giữ chức vụ lãnh đạo, quản lý","Viên chức quản lý"],c:1},{id:"vb10-87",s:"PHÂN BỐ SUNG 2 - CHƯƠNG II: CÁC HÌNH THỨC KỶ LUẬT VÀ HÀNH VI TƯƠNG ỨNG (TRỌNG TÂM)",cc:"ARhoaÊn 3 licu ÍÍ Nghị định số 1272. 2005.NĐ-(C.P.",gt:"Công chức nghiện ma túy bị buộc thôi việc; trường hợp này phải có kết luận của cơ sở y tế hoặc thông báo của cơ quan có thẩm quyền.",mn:"Nghiện ma túy -. buộc thôi việc (phải có kết luận y tế / thông báo cơ quan có thẩm quyền).",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, công chức nghiện ma túy bị áp dụng hình thức kỷ luật buộc thôi việc với điều kiện nào?",o:["Chỉ cần có tin báo của đồng nghiệp","Chỉ cần người đứng đầu nghị ngờ","Phải có kết luận của cơ sở y tế hoặc thông báo của cơ quan có thẩm quyền","Không cần điều kiện gì"],c:2},{id:"vb10-88",s:"PHÂN BỐ SUNG 2 - CHƯƠNG II: CÁC HÌNH THỨC KỶ LUẬT VÀ HÀNH VI TƯƠNG ỨNG (TRỌNG TÂM)",cc:"Điều ” Nghị định số 172 2005,NĐ-CP.",gt:"Hình thức kỷ luật cao nhất đối với cán bộ là bãi nhiệm; đối với công chức là buộc thôi việc. (C-ách chức chỉ áp dụng cho người giữ chức vụ lãnh đạo, quản lý.)",mn:"Cao nhất: cán bộ.. bãi nhiệm; công chức.. buộc thôi việc...32",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, phương án nào sau đây phân biệt DỤNG hình thức kỷ luật cao nhất áp dụng cho cán bộ và cho công chức?",o:["Cán bộ: bãi nhiệm; công chức: buộc thôi việc","Cán bộ: buộc thôi việc; công chức: bãi nhiệm","Cả hai đều là cách chức","Cả hai đều là buộc thôi việc"],c:0},{id:"vb10-89",s:"PHÂN BỐ SUNG 2 - CHƯƠNG II: CÁC HÌNH THỨC KỶ LUẬT VÀ HÀNH VI TƯƠNG ỨNG (TRỌNG TÂM)",cc:"Khoản 2 Điều 1U Nghị định số 172/2025/NĐ-CP.",gt:"Công chức lãnh đạo vi phạm lần đầu gây hậu quả rất nghiêm trọng nhưng có thái độ tiếp thu, sửa chữa, chủ động khác phục hậu quả và thuộc trường hợp tại khoản 3 Điều 4 thì có thể áp dụng hình thức cách chức (chưa đến mức buộc thôi việc).",mn:"Lãnh đạo, hậu quả rất nghiêm trọng nhưng biệt khác phục. cách chức (chưa buộc thôi việc).",t:"m",q:"Một tình huống vận dụng: Bà F là công chức lãnh đạo cấp phòng, vi phạm lần đầu gây hậu quả rất nghiêm trọng nhưng có thái độ tiếp thu, chủ động khác phục hậu quả, thuộc trường hợp được xem xét. Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, hình thức kỷ luật phù hợp có thể là gì?",o:["Khiển trách","Cảnh cáo","Cách chức","Buộc thôi việc"],c:2},{id:"vb10-90",s:"PHÂN BỐ SUNG 2 - CHƯƠNG II: CÁC HÌNH THỨC KỶ LUẬT VÀ HÀNH VI TƯƠNG ỨNG (TRỌNG TÂM)",cc:"Điều 7 Nghị định số 172:2025:NĐ-CP.",gt:"Hình thức cách chức chỉ áp dụng với công chức lãnh đạo, quản lý (người giữ chức vụ). Công chức không giữ chức vụ không thể bị cách chức. Vì vậy phương án C sai.",mn:"Công chức không giữ chức vụ - KHÔNG bị cách chức.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, nhận định nào sau đây về các hình thức kỷ luật là KHÔNG đúng?",o:["Cán bộ có thể bị bãi nhiệm","Công chức lãnh đạo, quản lý có thể bị cách chức","Công chức có thể bị buộc thôi việc","Công chức không giữ chức vụ có thể bị cách chức"],c:3},{id:"vb10-91",s:"PHÂN BỐ SUNG 2 - CHƯƠNG II: CÁC HÌNH THỨC KỶ LUẬT VÀ HÀNH VI TƯƠNG ỨNG (TRỌNG TÂM)",cc:"Khoản 1 Điều 8 Nghị định số 172/2025/NĐ-CP.",gt:"Vi phạm quy định về nghĩa vụ, đạo đức công vụ, văn hóa giao tiếp ở công sở, giao tiếp với Nhân dân, nội quy, quy chế (lần đầu, hậu quả ít nghiêm trọng) thuộc nhóm có thể bị khiển trách.",mn:"Khiển trách: vi phạm nghĩa vụ, đạo đức công vụ, văn hóa giao tiếp (lần đầu, ít nghiêm trọng). 33 LÀI LIỆU ÔN CE CÔNG €HUC VIÊN CHỨC FÐI NGUYỄN YONA 09953502H1",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, hành vi nào sau đây thuộc nhóm hành vi có thể bị áp dụng hình thức khiển trách (vi phạm lần đầu, hậu quả ít nghiêm trọng)?",o:["Sử dụng văn bằng giả để được tuyển dụng","Vi phạm quy định về đạo đức công vụ, văn hóa giao tiếp ở công sở, giao tiếp với Nhân dân","Nghiện ma túy","Tái phạm sau khi bị cảnh cáo"],c:1},{id:"vb10-92",s:"PHÂN BỐ SUNG 2 - CHƯƠNG II: CÁC HÌNH THỨC KỶ LUẬT VÀ HÀNH VI TƯƠNG ỨNG (TRỌNG TÂM)",cc:"Piếm b khoản š Liệu 9 Nghị định số 1-2,2005,NÉ CĐ.",gt:"Người đứng đầu để xảy ra vi phạm pháp luật nghiêm trọng trong phạm vi phụ trách mà không có biện pháp ngăn chặn (lần đầu, hậu quả ít nghiêm trọng) thuộc trường hợp áp dụng hình thức cảnh cáo.",mn:"Người đứng đầu buông lỏng để xảy ra vi phạm nghiêm trọng., cảnh cáo.",t:"m",q:"Một tình huống vận dụng: Ông G là người đứng đầu một đơn vị, để xảy ra hành vi vi phạm pháp luật nghiêm trọng trong phạm vi phụ trách mà không có biện pháp ngăn chặn (lần đầu, hậu quả ít nghiêm trọng). Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, ông G có thể bị áp dụng hình thức kỷ luật nào?",o:["Cảnh cáo","Khiển trách","Cách chức","Buộc thôi việc"],c:0},{id:"vb10-93",s:"PHÂN BỐ SUNG 2 - CHƯƠNG II: CÁC HÌNH THỨC KỶ LUẬT VÀ HÀNH VI TƯƠNG ỨNG (TRỌNG TÂM)",cc:"khoan ở Điều — Nghụ định số 172. 20053 MỘ-CP.",gt:"Thứ tự từ nhẹ đến nâng đối với công chức: khiển trách. cảnh cáo „ cách chức (với người giữ chức vụ). buộc thôi việc.",mn:"Công chức nhẹ.nặng: khiển trách — cảnh cáo — cách chức — buộc thôi việc.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, phương án nào sau đây sắp xếp ĐÚNG thứ tự các hình thức kỷ luật đối với công chức từ nhẹ đến nâng?",o:["Cảnh cáo ¬ khiển trách —¬ cách chức ¬ buộc thôi việc","Khiển trách ¬ cảnh cáo ¬ cách chức ¬ buộc thôi việc","Khiển trách ¬ cách chức ¬ cảnh cáo ¬ buộc thôi việc","Khiển trách ¬ cảnh cáo ¬ buộc thôi việc = cách chức"],c:1},{id:"vb10-94",s:"PHÂN BỐ SUNG 2 - CHƯƠNG II: CÁC HÌNH THỨC KỶ LUẬT VÀ HÀNH VI TƯƠNG ỨNG (TRỌNG TÂM)",cc:"Diômn c khoản Ì Điều ˆ Nghị định số 152 29253/NĐ-C.B.",gt:"Hình thức cách chức đối với cán bộ chỉ áp dụng với cán bộ được phê chuẩn, bổ nhiệm hoặc chỉ định giữ chức vụ, chức danh.",mn:"Cách chức cán bộ: chỉ với người được phê chuẩn/bổ nhiệm/chỉ định giữ chức vụ...34",t:"m",q:"Một tình huống vận dụng: Ông H là cán bộ giữ chức vụ do được phê chuẩn, có hành vi vi phạm. Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, hình thức “cách chức” đối với ông H được áp dụng trong điều kiện nào?",o:["Áp dụng với mọi cán bộ đủ không giữ chức vụ","Chỉ áp dụng với công chức lãnh đạo","Chỉ áp dụng đối với cán bộ được phê chuẩn, bổ nhiệm hoặc chỉ định giữ chức vụ, chức danh","Không áp dụng cho cán bộ"],c:2},{id:"vb10-95",s:"PHÂN BỐ SUNG 2 - CHƯƠNG II: CÁC HÌNH THỨC KỶ LUẬT VÀ HÀNH VI TƯƠNG ỨNG (TRỌNG TÂM)",cc:"Khoản 2 Điều 7 Nghị định số 172/2025,/NID-CP.",gt:"Điểm mới: hình thức kỷ luật đối với công chức không còn “hạ bậc lương” và “giáng chức”; chỉ còn khiển trách, cảnh cáo, cách chức, buộc thôi việc — tinh gọn, gắn với vị trí việc làm. Š® Miẹo nhớ: Diểm mới: bỏ hạ bậc lương, giáng chức; công chức còn 4 hình thức. 35 Phạm vi: Điều 13 đến Điều 23 — thôm quyền và trình tự, thủ tục xử lý kỷ luật đối với cán bộ (Mục 1): đổi với công chức gồm họp kiểm điểm, Hội đồng kỷ luật, quyết định kỷ luật (Mục 2); đối với người đã thôi việc, nghỉ hưu (Mục 3). Lưu ý các móc thời gian và thành phần Hội đồng kỷ luật.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, so với quy định trước đây, hình thức kỷ luật đối với công chức theo Nghị định này có điểm mới nào?",o:["Bổ sung thêm hình thức hạ bậc lương và giảng chức","Áp dụng chung một hình thức cho cá cán bộ và công chức","Bỏ hình thức buộc thôi việc","Không còn hình thức “hạ bậc lương” và “giáng chức”; chỉ còn khiển trách, cảnh cáo, cách chức, buộc thôi việc"],c:3},{id:"vb10-96",s:"CHƯƠNG 1II - THẨM QUYỀN VÀ TRÌNH TỰ, THỦ TỤC XỬ LÝ KỶ LUẬT",cc:"Khoản 2 Điều 13 Nghị định số 172/2025/NĐ-CP.",gt:"Đối với các chức vụ, chức danh trong cơ quan hành chính nhà nước do Quốc hội phê chuẩn thì Thủ tướng Chính phủ ra quyết định xử lý kỷ luật. Nguyên tắc chung: cấp có thẩm quyền phê chuẩn, phê duyệt kết quả bầu cử thì có thẩm quyền xử lý kỷ luật.",mn:"Chức danh do Quốc hội phê chuẩn (cơ quan hành chính). › Thủ tướng kỷ luật.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, đối với các chức vụ, chức danh trong cơ quan hành chính nhà nước do Quốc hội phê chuẩn thì ai ra quyết định xử lý kỷ luật?",o:["Bộ trưởng Bộ Nội vụ","Ủy ban Thường vụ Quốc hội","Chủ tịch nước","Thủ tướng Chính phủ"],c:3},{id:"vb10-97",s:"CHƯƠNG 1II - THẨM QUYỀN VÀ TRÌNH TỰ, THỦ TỤC XỬ LÝ KỶ LUẬT",cc:"Khoan I và khoản 3 Điều 13 Nghị định số 172/2025/NI)-CP.",gt:"Thẩm quyền xử lý kỷ luật cán bộ: cấp có thẩm quyền phê chuẩn, phê duyệt kết quả bầu cử thì có thẩm quyền xử lý kỷ luật; nếu không có hoặc đang chờ quyết định phê chuẩn, phê duyệt kết quả bầu cử thì cấp có thẩm quyền bầu cử quyết định xử lý kỷ luật.",mn:"Kỷ luật cán bộ: cấp phê chuẩn/phê duyệt bầu cử xử lý; chưa có thì cấp bầu cử xử lý.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, nguyên tắc xác định thẩm quyền xử lý kỷ luật đối với cán bộ được quy định như thế nào?",o:["Người đứng đầu cơ quan, tổ chức nơi cán bộ công tác xử lý kỷ luật","Cấp có thẩm quyền phê chuẩn, quyết định phê duyệt kết quả bầu cử thì có thẩm quyền xử lý kỷ luật; trường hợp không có hoặc đang chờ quyết định phê chuẩn, phê duyệt kết quả bầu cử thì cấp có thẩm quyền bầu cử quyết định xử lý kỷ luật","Bộ Nội vụ xử lý kỷ luật mới cán bộ","Cơ quan thanh tra nhà nước quyết định xử lý kỷ luật"],c:1},{id:"vb10-98",s:"CHƯƠNG 1II - THẨM QUYỀN VÀ TRÌNH TỰ, THỦ TỤC XỬ LÝ KỶ LUẬT",cc:"Khoan I liệu 15 Nghị định số 172/2025/NĐ-CP.",gt:"Đối với công chức giữ chức vụ lãnh đạo, quản lý, người đứng đầu cơ quan có thẩm quyền bổ nhiệm (hoặc theo phân cấp, ủy quyền) tiến hành xử lý kỷ luật và quyết định hình thức kỷ luật.",mn:"Công chức lãnh đạo: người đứng đầu cơ quan có thẩm quyền bổ nhiệm xử lý.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, đối với công chức giữ chức vụ lãnh đạo, quản lý thì ai có thẩm quyền tiến hành xử lý kỷ luật và quyết định hình thức kỷ luật?",o:["Hội đồng kỷ luật của cơ quan","Người đứng đầu cơ quan có thẩm quyền tuyển dụng","Người đứng đầu cơ quan có thẩm quyền bổ nhiệm hoặc theo phân cấp, ủy quyền..36","Cơ quan quản lý công chức cấp trên"],c:2},{id:"vb10-99",s:"CHƯƠNG 1II - THẨM QUYỀN VÀ TRÌNH TỰ, THỦ TỤC XỬ LÝ KỶ LUẬT",cc:"Khoản 2 Điều 15 Nghị định số 172/2025/NĐ-CP.",gt:"Đối với công chức không giữ chức vụ lãnh đạo, quản lý, người đứng đầu cơ quan có thẩm quyền tuyển dụng (hoặc theo phân cấp, ủy quyền) tiến hành xử lý kỷ luật. (Phân biệt: lãnh đạo, quản lý. cơ quan có thẩm quyền bổ nhiệm; không giữ chức vụ › cơ quan có thẩm quyền tuyển dụng.)",mn:"Công chức không chức vụ: người đứng đầu cơ quan có thẩm quyền tuyển dụng xử lý.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, đối với công chức KHÔNG giữ chức vụ lãnh đạo, quản lý thì ai có thẩm quyền xử lý kỷ luật?",o:["Người đứng đầu cơ quan có thẩm quyền tuyển dụng hoặc theo phân cấp, ủy quyền","Người đứng đầu cơ quan có thẩm quyền bổ nhiệm","Chủ tịch Hội đồng kỷ luật","Cơ quan thanh tra cùng cấp"],c:0},{id:"vb10-100",s:"CHƯƠNG 1II - THẨM QUYỀN VÀ TRÌNH TỰ, THỦ TỤC XỬ LÝ KỶ LUẬT",cc:"Khoản 3 Điều 15 Nghị định số 172/2025'NĐ-CP.",gt:"Đối với công chức biệt phái, người đứng đầu cơ quan nơi công chức được cử biệt phái tiến hành xử lý kỷ luật, thống nhất hình thức kỷ luật với cơ quan cử biệt phái trước khi quyết định; hồ sơ, quyết định kỷ luật phải gửi về cơ quan quản lý công chức biệt phái. Riêng buộc thôi việc thì cơ quan cử biệt phái ra quyết định.",mn:"Biệt phái: nơi nhận biệt phái xử lý + thống nhất với nơi cử + gửi hồ sơ về nơi quản lý.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, đối với công chức biệt phái, việc xử lý kỷ luật được thực hiện như thế nào?",o:["Công chức biệt phái không thuộc diện xử lý kỷ luật","Cơ quan cử biệt phái xử lý kỷ luật toàn bộ","Hội đồng kỷ luật của cơ quan quản lý cấp trên xử lý","Người đứng đầu cơ quan, tổ chức nơi công chức được cử biệt phái tiến hành xử lý kỷ luật, thống nhất hình thức kỷ luật với cơ quan cử biệt phái trước khi quyết định; hồ sơ, quyết định kỷ luật phải gửi về cơ quan quản lý công chức biệt phái"],c:3},{id:"vb10-101",s:"CHƯƠNG 1II - THẨM QUYỀN VÀ TRÌNH TỰ, THỦ TỤC XỬ LÝ KỶ LUẬT",cc:"khoơn J Điều Eö Nghị định số 1732025-NĐ-CP,",gt:"Trình tự xử lý kỷ luật công chức gồm 3 bước: (1) tổ chức họp kiểm điểm; (2) thành lập Hội đồng kỷ luật; (3) cấp có thẩm quyền ra quyết định xử lý kỷ luật. Một số trường hợp được bỏ bước kiểm điểm hoặc cả kiểm điểm và Hội đồng kỷ luật.",mn:"3 bước: kiểm điểm. Hội đồng kỷ luật. quyết định.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, trình tự xử lý kỷ luật đối với công chức gồm các bước nào?",o:["Thanh tra; kết luận; xử phạt","Lập biên bản vi phạm; ra quyết định kỷ luật; thông báo cho công chức ”; / ¡.3 LÀI LIỆU ÔN CE CÔNG €HUC VIÊN CHỨC FÐI NGUYỄN YONA 09953502H1","Tổ chức họp kiểm điểm; thành lập Hội đồng kỷ luật; cấp có thẩm quyền ra quyết định xử lý kỷ luật","Kiểm điểm; thông báo; chấp hành"],c:2},{id:"vb10-102",s:"CHƯƠNG 1II - THẨM QUYỀN VÀ TRÌNH TỰ, THỦ TỤC XỬ LÝ KỶ LUẬT",cc:"khoản 3 Điều lò Nghị định số 172⁄2025:NĐ-CD.",gt:"Không tổ chức kiểm điểm và không thành lập Hội đồng kỷ luật khi: đã có kết luận của cơ quan có thẩm quyền về hành vi vi phạm kèm đề xuất hình thức kỷ luật; bị Tòa án kết án phạt tù không hưởng án treo hoặc về hành vi tham nhũng; đã có quyết định xử lý kỷ luật về đảng (trừ trường hợp riêng). Các trường hợp này được sử dụng kết luận sẵn có, không phải điều tra, xác minh lại.",mn:"Bỏ cả kiểm điểm + hội đồng: đã có kết luận - bị từ;tham nhũng — đã có kỷ luật đảng.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, trường hợp nào sau đây KHÔNG phải tổ chức họp kiểm điểm và KHÔNG phải thành lập Hội đồng kỷ luật?",o:["Đã có kết luận của cơ quan có thẩm quyền về hành vi vi phạm kèm đề xuất hình thức kỷ luật; công chức bị Tòa án kết án phạt tù không hưởng án treo hoặc bị kết án về hành vi tham nhũng: đã có quyết định xử lý kỷ luật về đảng (trừ trường hợp riêng)","Mọi trường hợp công chức vi phạm lần đầu","Công chức tự nhận hình thức kỷ luật khiển trách","Công chức vắng mặt tại cuộc họp kiểm điểm"],c:0},{id:"vb10-103",s:"CHƯƠNG 1II - THẨM QUYỀN VÀ TRÌNH TỰ, THỦ TỤC XỬ LÝ KỶ LUẬT",cc:"Điền c khoản 3 Điều 17 Nghị định số 17522025. ND CD.",gt:"Tại cuộc họp kiểm điểm. không tiến hành biểu quyết, bỏ phiếu; thành viên phát biểu ý kiến, người chủ trì kết luận, nội dung lập thành biên bản. Việc bỏ phiếu kín về hình thức kỷ luật chỉ diễn ra tại Hội đồng kỷ luật.",mn:"Họp kiểm điểm: không bỏ phiếu; bỏ phiếu kín là ở Hội đồng kỷ luật...838 LÀI LIỆU ÔN CE CÔNG €HUC VIÊN CHỨC FÐI NGUYỄN YONA 09953502H1",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, tại cuộc họp kiểm điểm công chức, việc biểu quyết, bỏ phiếu được thực hiện như thế nào?",o:["Tiến hành bỏ phiếu kín để quyết định hình thức kỷ luật","Tại cuộc họp kiểm điểm không tiến hành biểu quyết, bỏ phiếu; thành viên phát biểu ý kiến và người chủ trì kết luận, lập biên bản","Biểu quyết công khai bằng giơ tay về hình thức kỷ luật","Bỏ phiếu về việc có kỷ luật hay không"],c:1},{id:"vb10-104",s:"CHƯƠNG 1II - THẨM QUYỀN VÀ TRÌNH TỰ, THỦ TỤC XỬ LÝ KỶ LUẬT",cc:"Nhuan 4 Điều 17 Nghị định số 172/2025/N9)-CP.",gt:"Trong thời hạn 03 ngày làm việc kể từ ngày kết thúc cuộc họp kiểm điểm, người chủ trì gửi báo cáo và biên bản cuộc họp kiểm điểm đến cấp có thẩm quyền xử lý kỷ luật.",mn:"Sau kiểm điểm: 03 ngày làm việc gửi báo cáo, biên bản.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, trong thời hạn bao lâu kể từ ngày kết thúc cuộc họp kiểm điểm, người chủ trì phải gửi báo cáo và biên bản đến cấp có thẩm quyền xử lý kỷ luật?",o:["10 ngày làm việc","05 ngày làm việc","07 ngày làm việc","03 ngày làm việc"],c:3},{id:"vb10-105",s:"CHƯƠNG 1II - THẨM QUYỀN VÀ TRÌNH TỰ, THỦ TỤC XỬ LÝ KỶ LUẬT",cc:"Nhoan Ì Điều 18 Nghị định số 122/2025.NĐ-C.Đ.",gt:"(Chậm nhất 05 ngày làm việc kể từ khi nhận được báo cáo và biên bản cuộc họp kiểm điểm, cấp có thẩm quyền quyết định thành lập Hội đồng kỷ luật (trừ các trường hợp không thành lập Hội đồng).",mn:"Nhận báo cáo kiểm điểm.. 05 ngày làm việc thành lập Hội đồng kỷ luật.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, chậm nhất bao nhiêu ngày làm việc kể từ khi nhận được báo cáo và biên bản cuộc họp kiểm điểm, cấp có thẩm quyền phải quyết định thành lập Hội đồng kỷ luật?",o:["03 ngày làm việc","05 ngày làm việc","07 ngày làm việc","10 ngày làm việc"],c:1},{id:"vb10-106",s:"CHƯƠNG 1II - THẨM QUYỀN VÀ TRÌNH TỰ, THỦ TỤC XỬ LÝ KỶ LUẬT",cc:"Nhoan 2 Điều 1# Vqhi định số 1722025 NĐ-CP.",gt:"Nguyên tắc làm việc của Hội đồng kỷ luật: họp khi có đủ 03 thành viên tham dự: kiến nghị hình thức kỷ luật thông qua bỏ phiếu kín; lập biên bản thể hiện rõ ý kiến và kết quả bỏ phiếu; tự giải thể sau khi hoàn thành nhiệm vụ.",mn:"Hội đồng kỷ luật: đủ 03 thành viên — bỏ phiếu kín - tự giải thể.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, Hội đồng kỷ luật công chức làm việc theo nguyên tắc nào?",o:["Họp khi có đủ 03 thành viên tham dự; kiến nghị áp dụng hình thức kỷ luật thông qua bỏ phiếu kín; lập biên bản thể hiện rõ ý kiến và kết quả bỏ phiếu; tự giải thể sau khi hoàn thành nhiệm vụ","Họp khi có quá nửa số thành viên; quyết định bằng biểu quyết công khai","Họp khi có đủ toàn bộ thành viên; kiến nghị bằng biểu quyết giơ tay","Họp khi có đại diện cơ quan thanh tra; quyết định bằng đa số tương đối"],c:0},{id:"vb10-107",s:"CHƯƠNG 1II - THẨM QUYỀN VÀ TRÌNH TỰ, THỦ TỤC XỬ LÝ KỶ LUẬT",cc:"J)iều 19 Nghị định số 172:2025/N1)D-CP.",gt:"Hội đồng kỷ luật công chức có 03 thành viên: Chủ tịch là người đứng đầu hoặc cấp phó của người đứng đầu cơ quan có thẩm quyền xử lý kỷ luật; 01 ủy viên đại diện lãnh đạo cơ quan trực tiếp sử dụng công chức; 01 ủy viên đại diện bộ phận tham mưu về tổ chức cán bộ.",mn:"Hội đồng kỷ luật: 3 thành viên (Chủ tịch + ủy viên sử dụng + ủy viên tổ chức cán bộ).",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, Hội đồng kỷ luật công chức có bao nhiêu thành viên và gồm những ai?",o:["07 thành viên do tập thể cơ quan bầu..39","05 thành viên gồm đại diện các tổ chức đoàn thể","03 thành viên: Chủ tịch Hội đồng là người đứng đầu hoặc cấp phó của người đứng đầu cơ quan có thẩm quyền xử lý kỷ luật; 01 ủy viên là đại diện lãnh đạo cơ quan trực tiếp sử dụng công chức; 01 ủy viên là đại diện bộ phận tham mưu về công tác tổ chức cán bộ","03 thành viên gồm Chủ tịch và 02 đại diện công đoàn"],c:2},{id:"vb10-108",s:"CHƯƠNG 1II - THẨM QUYỀN VÀ TRÌNH TỰ, THỦ TỤC XỬ LÝ KỶ LUẬT",cc:"liêm a khoản 1 Điều 20 Nghị định số 172/2025/NĐ-CP.",gt:"Chậm nhất 05 ngày làm việc trước ngày tổ chức cuộc họp của Hội đồng kỷ luật, giấy triệu tập phải được gửi tới công chức có hành vi vi phạm. $® Miẹo nhớ: Giấy triệu tập họp Hội đồng: gửi trước 05 ngày làm việc.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, chậm nhất bao nhiêu ngày làm việc trước ngày tổ chức cuộc họp của Hội đồng kỷ luật, giấy triệu tập phải được gửi tới công chức có hành vi vi phạm?",o:["03 ngày làm việc","05 ngày làm việc","07 ngày làm việc","10 ngày làm việc"],c:1},{id:"vb10-109",s:"CHƯƠNG 1II - THẨM QUYỀN VÀ TRÌNH TỰ, THỦ TỤC XỬ LÝ KỶ LUẬT",cc:"l)iêm ở khoản 1Í liệu 20 Nghị định số 172/20205N)2-CP.",gt:"Trường hợp công chức có hành vi vi phạm vắng mặt theo giấy triệu tập lần thứ 2 thì Hội đồng kỷ luật vẫn tiến hành họp - tránh việc có tình vắng mặt để kéo dài, né tránh.",mn:"Vắng mặt lần 2. Hội đồng kỷ luật vẫn họp.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, trường hợp công chức có hành vi vi phạm vắng mặt tại cuộc họp Hội đồng kỷ luật theo giấy triệu tập lần thứ 2 thì xử lý như thế nào?",o:["Hủy bỏ việc xử lý kỷ luật","Hoãn cuộc họp cho đến khi công chức có mặt","Hội đồng kỷ luật vẫn tiến hành họp","Chuyển sang hình thức kỷ luật nặng hơn"],c:2},{id:"vb10-110",s:"CHƯƠNG 1II - THẨM QUYỀN VÀ TRÌNH TỰ, THỦ TỤC XỬ LÝ KỶ LUẬT",cc:"J)iệm b khoản 1 liệu 2U Nghị định số 172/2025/NĐ- CP.",gt:"Người được mời dự họp có quyền phát biểu ý kiến và đề xuất hình thức kỷ luật nhưng KHÔNG được bỏ phiếu về hình thức kỷ luật. Quyền bỏ phiếu chỉ thuộc về thành viên Hội đồng kỷ luật.",mn:"Người được mời: được phát biểu, đề xuất nhưng không được bỏ phiếu.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, người được mời dự họp Hội đồng kỷ luật (đại diện tổ chức chính trị, tổ chức chính trị - xã hội, cá nhân liên quan) có quyền gì?",o:["Có quyền quyết định hình thức kỷ luật cuối cùng","Có quyền bỏ phiếu về hình thức kỷ luật như thành viên Hội đồng „40","Chỉ được dự thính, không được phát biểu","Có quyền phát biểu ý kiến và đề xuất hình thức kỷ luật nhưng không được bỏ phiếu về hình thức kỷ luật"],c:3},{id:"vb10-111",s:"CHƯƠNG 1II - THẨM QUYỀN VÀ TRÌNH TỰ, THỦ TỤC XỬ LÝ KỶ LUẬT",gt:"Hội đồng kỷ luật bỏ phiếu về việc có kỷ luật hay không: nếu đa số phiếu kiến nghị kỷ luật thì bỏ phiếu về việc áp dụng hình thức kỷ luật; việc bỏ phiếu tiến hành bằng bỏ phiếu kín theo phương pháp tích phiếu. ® Miẹo nhớ: Hội đồng: bỏ phiếu kín 2 bước (có kỷ luật không. hình thức nào).",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, tại cuộc họp Hội đồng kỷ luật, việc bỏ phiếu về hình thức kỷ luật được tiến hành như thế nào?",o:["Hội đồng bỏ phiếu về việc có kỷ luật hay không; nếu đa số phiếu kiến nghị kỷ luật thì bỏ phiếu về việc áp dụng hình thức kỷ luật; việc bỏ phiếu tiến hành bằng hình thức bỏ phiếu kín","Biểu quyết công khai về hình thức kỷ luật bằng giơ tay","Chủ tịch Hội đồng quyết định hình thức kỷ luật, không bỏ phiếu","Người có hành vi vi phạm tự chọn hình thức kỷ luật"],c:0},{id:"vb10-112",s:"CHƯƠNG 1II - THẨM QUYỀN VÀ TRÌNH TỰ, THỦ TỤC XỬ LÝ KỶ LUẬT",cc:"Điểm a khoản 1 Điều 21 Nghị định số 172/2025/NĐ-CP.",gt:"Trong thời hạn 05 ngày làm việc kể từ ngày kết thúc cuộc họp, Hội đồng kỷ luật phải có kiến nghị xử lý kỷ luật bằng văn bản (kèm biên bản và hồ sơ) gửi cấp có thẩm quyền xử lý kỷ luật.",mn:"Sau họp Hội đồng: 05 ngày làm việc gửi kiến nghị.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, trong thời hạn bao lâu kể từ ngày kết thúc cuộc họp, Hội đồng kỷ luật phải có kiến nghị việc xử lý kỷ luật bằng văn bản gửi cấp có thẩm quyền?",o:["07 ngày làm việc","03 ngày làm việc","05 ngày làm việc","10 ngày làm việc"],c:2},{id:"vb10-113",s:"CHƯƠNG 1II - THẨM QUYỀN VÀ TRÌNH TỰ, THỦ TỤC XỬ LÝ KỶ LUẬT",cc:"Điểm b khoôn Í Điều 21 Nghị định số E72 D005 NĐ-CP.",gt:"Trong thời hạn 05 ngày làm việc kể từ ngày nhận được văn bản kiến nghị của Hội đồng kỷ luật (hoặc biên bản kiểm điểm, văn bản đề xuất), cấp có thẩm quyền ra quyết định kỷ luật hoặc kết luận công chức không vi phạm.",mn:"Nhận kiến nghị -„ 05 ngày làm việc ra quyết định kỷ luật.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, trong thời hạn bao lâu kể từ ngày nhận được văn bản kiến nghị của Hội đồng kỷ luật (hoặc biên bản kiểm điểm, văn bản đề xuất), cấp có thẩm quyền phải ra quyết định kỷ luật hoặc kết luận công chức không vi phạm?",o:["05 ngày làm việc","03 ngày làm việc","10 ngày làm việc „4l LÀI LIỆU ÔN CE CÔNG €HUC VIÊN CHỨC FÐI NGUYỄN YONA 09953502H1","15 ngày làm việc"],c:0},{id:"vb10-114",s:"CHƯƠNG 1II - THẨM QUYỀN VÀ TRÌNH TỰ, THỦ TỤC XỬ LÝ KỶ LUẬT",cc:"khoản 2 Điều 21 Nghị định số 172.20205,AD-CP.",gt:"Trường hợp công chức bị Tòa án kết án phạt tù không hưởng án treo hoặc bị kết án về hành vi tham nhũng, trong thời hạn 15 ngày làm việc kể từ ngày nhận được quyết định, bản án có hiệu lực, cấp có thẩm quyền ra quyết định buộc thôi việc.",mn:"Bị từ tham nhũng: 15 ngày làm việc ra quyết định buộc thôi việc.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, trường hợp công chức bị Tòa án kết án phạt tù không hưởng án treo hoặc bị kết án về hành vi tham nhũng, trong thời hạn bao lâu kể từ ngày nhận được bản án có hiệu lực, cấp có thẩm quyền ra quyết định buộc thôi việc?",o:["30 ngày làm việc","05 ngày làm việc","07 ngày làm việc","15 ngày làm việc"],c:3},{id:"vb10-115",s:"CHƯƠNG 1II - THẨM QUYỀN VÀ TRÌNH TỰ, THỦ TỤC XỬ LÝ KỶ LUẬT",cc:"Rhonn 1, khoản 3 và khoản 4 Điều 22 Nghị định sẽ 173 2025/NĐ-CP (được xưa đổi, bổ sung ĐỔI Nghề định số 251200. ND).",gt:"Người đã thôi việc, nghỉ hưu bị xóa tư cách chức vụ, chức danh thì cấp có thẩm quyền bầu, phê chuẩn, phê duyệt kết quả bầu cử, bổ nhiệm hoặc chỉ định giữ chức vụ, chức danh cao nhất ra quyết định. `. ] Theo Nghị định số 251/2025/NĐ- (;P: chức danh do Thủ tướng trình Quốc hội phê chuẩn thì Thủ tướng Chính phủ quyết định; chức danh do Quốc hội bầu thì Ủy ban Thường vụ Quốc hội quyết định.",mn:"Người đã nghỉ, xóa tư cách: cấp phê chuẩn/bầu chức vụ cao nhất xử lý; (}H phê chuẩn (Thủ tướng trình) › Thủ tướng: „J QH bầu. Ủy ban Thường vụ Quốc hội (ND 251)...42",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, đối với người đã thôi việc, nghỉ hưu bị xử lý kỷ luật bằng hình thức xóa tư cách chức vụ, chức danh thì ai ra quyết định xử lý kỷ luật?",o:["Người đứng đầu cơ quan nơi người đó từng công tác","Cấp có thẩm quyền bầu, phê chuẩn, phê duyệt kết quả bầu cử, bổ nhiệm hoặc chỉ định giữ chức vụ, chức danh cao nhất; trừ trường hợp do Thủ tướng Chính phủ trình Quốc hội phê chuẩn thì Thủ tướng Chính phủ, do Quốc hội bầu thì Ủy ban Thường vụ Quốc hội ra quyết định","Cơ quan bảo hiểm xã hội nơi chi trả lương hưu","Hội đồng kỷ luật của cơ quan cử"],c:1},{id:"vb10-116",s:"CHƯƠNG 1II - THẨM QUYỀN VÀ TRÌNH TỰ, THỦ TỤC XỬ LÝ KỶ LUẬT",gt:"Người đã thôi việc, nghỉ hưu bị khiển trách hoặc cảnh cáo thì cấp có thẩm quyền bầu, phê chuẩn, phê duyệt kết quả bầu cử, bổ nhiệm hoặc chỉ định giữ chức vụ, chức danh ra quyết định. 5¬ Theo Nghị định số 251/2025/NĐ-CP: chức danh do Thủ tướng trình Quốc hội phê chuẩn thì Thủ tướng Chính phủ, do Quốc hội bầu thì Ủy ban Thường vụ Quốc hội quyết định.",mn:"Người đã nghỉ, khiển trách/cảnh cáo: cấp phê chuẩn/bầu chức vụ xử lý; ¬ QH bầu ¬ Ủy ban Thường vụ Quốc hội (ND 251).",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, đối với người đã thôi việc, nghỉ hưu bị xử lý kỷ luật bằng hình thức khiển trách hoặc cảnh cáo thì ai ra quyết định?",o:["Cấp có thẩm quyền bầu, phê chuẩn, phê duyệt kết quả bầu cử, bổ nhiệm hoặc chỉ định giữ chức vụ, chức danh; trừ trường hợp do Thủ tướng Chính phủ trình Quốc hội phê chuẩn thì Thủ tướng Chính phủ, do Quốc hội bầu thì Ủy ban Thường vụ Quốc hội ra quyết định","Cơ quan bảo hiểm xã hội","Người đứng đầu đơn vị sự nghiệp nơi người đó công tác","Tòa án nhân dân nơi cư trú"],c:0},{id:"vb10-117",s:"CHƯƠNG 1II - THẨM QUYỀN VÀ TRÌNH TỰ, THỦ TỤC XỬ LÝ KỶ LUẬT",cc:"Điểm a khoản 1 Điều 17 Nghị định số 172:2025/NĐ-CP.",gt:"Khi người đứng đầu và tất cả cấp phó của cơ quan sử dụng công chức trong cùng vụ việc bị xem xét kỷ luật (hoặc thuộc trường hợp có quan hệ liên quan), lãnh đạo cơ quan cấp trên trực tiếp của cơ quan sử dụng công chức chủ trì cuộc họp kiểm điểm — bảo đảm khách quan.",mn:"Lãnh đạo cơ quan cùng vụ việc ¬ cấp trên trực tiếp chủ trì kiểm điểm.",t:"m",q:"Một tình huống: Công chức M (không giữ chức vụ lãnh đạo) vi phạm và bị xem xét kỷ luật. Người đứng đầu và tất cả cấp phó của cơ quan sử dụng M đều thuộc cùng vụ việc bị xem xét kỷ luật. Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, ai chủ trì cuộc họp kiểm điểm M?",o:["Hội đồng kỷ luật chủ trì","Một công chức khác trong cơ quan được cử chủ trì","Lãnh đạo cơ quan cấp trên trực tiếp của cơ quan sử dụng công chức chủ trì cuộc họp","Không tổ chức họp kiểm điểm"],c:2},{id:"vb10-118",s:"CHƯƠNG 1II - THẨM QUYỀN VÀ TRÌNH TỰ, THỦ TỤC XỬ LÝ KỶ LUẬT",cc:"Điểm d khoản Ì Điều 20 Nghị định số 172/2025/NĐ-CP,",gt:"Hồ sơ trình Hội đồng kỷ luật gồm: bản tự kiểm điểm, trích ngang sơ yếu lý lịch của công chức, biên bản cuộc họp kiểm điểm của cơ quan sử dụng công chức và các tài liệu khác có liên quan.",mn:"Hồ sơ Hội đồng: bản tự kiểm điểm + sơ yếu lý lịch + biên bản kiểm điểm + tài liệu liên quan.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, hồ sơ xử lý kỷ luật trình Hội đồng kỷ luật gồm những tài liệu nào?",o:["Chỉ gồm biên bản vi phạm và đơn tố cáo","Chỉ gồm bản tự kiểm điểm của công chức","Chỉ gồm quyết định kỷ luật về đảng","Bản tự kiểm điểm, trích ngang sơ yếu lý lịch của công chức, biên bản cuộc họp kiểm điểm của cơ quan sử dụng công chức và các tài liệu khác có liên quan"],c:3},{id:"vb10-119",s:"CHƯƠNG 1II - THẨM QUYỀN VÀ TRÌNH TỰ, THỦ TỤC XỬ LÝ KỶ LUẬT",cc:"Khoản 1 Điều 14 Nghị định số 172/2025/NĐ-CP.",gt:"Trường hợp thuộc thẩm quyền xử lý kỷ luật của Thủ tướng Chính phủ, văn bản đề xuất được gửi đồng thời tới Bộ Nội vụ để thẩm định, báo cáo Thủ tướng Chính phủ xem xét, quyết định.",mn:"Thuộc thẩm quyền Thủ tướng., Bộ Nội vụ thẩm định trước.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, trường hợp thuộc thẩm quyền xử lý kỷ luật của Thủ tướng Chính phủ thì văn bản đề xuất hình thức kỷ luật được gửi đến cơ quan nào để thẩm định?",o:["Gửi tới Văn phòng Chính phủ","Gửi đồng thời tới Bộ Nội vụ để thẩm định, báo cáo Thủ tướng Chính phủ xem xét, quyết định","Gửi tới Thanh tra Chính phủ","Gửi tới Ủy ban Thường vụ Quốc hội"],c:1},{id:"vb10-120",s:"CHƯƠNG 1II - THẨM QUYỀN VÀ TRÌNH TỰ, THỦ TỤC XỬ LÝ KỶ LUẬT",cc:"Khoản 1 Điều 14 Nghị định số 172/2025°NĐ-CP.",gt:"Trường hợp thuộc thẩm quyền xử lý của Ủy ban Thường vụ Quốc hội, Thủ tướng Chính phủ, cơ quan có thẩm quyền quản lý, sử dụng trong thời hạn 07 ngày kể từ ngày công bố quyết định kỷ luật về đảng phải có văn bản đề xuất hình thức kỷ luật, thời điểm và thời gian thi hành.",mn:"UBTVQH;/Thùủ tướng: 07 ngay sau công bố kỷ luật đảng phải đề xuất.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, trường hợp thuộc thẩm quyền xử lý kỷ luật của Ủy ban Thường vụ Quốc hội, Thủ tướng Chính phủ thì cơ quan có thẩm quyền quản lý, sử dụng phải có văn bản đề xuất trong thời hạn nào kể từ ngày công bố quyết định kỷ luật về đảng?",o:["07 ngày","05 ngày","10 ngày","15ngày"],c:0},{id:"vb10-121",s:"CHƯƠNG 1II - THẨM QUYỀN VÀ TRÌNH TỰ, THỦ TỤC XỬ LÝ KỶ LUẬT",cc:"Khoản 3 Điều 21 Voghi định số 172:20]25/NI)- CP. LÀI LIỆU ÔN CE CÔNG €HUC VIÊN CHỨC FÐI NGUYỄN YONA 09953502H1",gt:"Quyết định kỷ luật phải ghi rõ thời điểm có hiệu lực thi hành - làm căn cứ tính thời gian thi hành quyết định kỷ luật (12 tháng).",mn:"Quyết định kỷ luật: ghi rõ thời điểm có hiệu lực.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, quyết định kỷ luật công chức phải bảo đảm yêu cầu nào sau đây?",o:["Phải được công khai trên phương tiện thông tin đại chúng","Phải được sự đồng ý của công chức bị kỷ luật","Phải ghi rõ thời điểm có hiệu lực thi hành","Phải có ý kiến chấp thuận của cơ quan cấp trên"],c:2},{id:"vb10-122",s:"CHƯƠNG 1II - THẨM QUYỀN VÀ TRÌNH TỰ, THỦ TỤC XỬ LÝ KỶ LUẬT",cc:"Khoản 4 Điều E5 Nghị định số 172/2025/NĐ-CP.",gt:"Đối với công chức làm việc trong Tòa án nhân dân và Viện kiểm sát nhân dân. thẩm quyền xử lý kỷ luật thực hiện theo quy định của cơ quan có thẩm quyền quản lý công chức - có tính đặc thù.",mn:"Công chức TAND, VKSND: theo quy định của cơ quan có thẩm quyền quản lý.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, đối với công chức làm việc trong Tòa án nhân dân và Viện kiểm sát nhân dân thì thẩm quyền xử lý kỷ luật được thực hiện như thế nào?",o:["Theo quyết định của Chánh án Tòa án nhân dân tối cao trong mọi trường hợp","Theo quy định của cơ quan có thẩm quyền quản lý công chức","Theo quy định chung như mọi công chức hành chính","Theo quyết định của Bộ Nội vụ"],c:1},{id:"vb10-123",s:"CHƯƠNG 1II - THẨM QUYỀN VÀ TRÌNH TỰ, THỦ TỤC XỬ LÝ KỶ LUẬT",cc:"ĐDiểu J9 và điểm b khoản ‡ Điều 20 Nghị định số I2 2025. NgÉ-C D.",gt:"Chỉ 03 thành viên Hội đồng kỷ luật được bỏ phiếu về hình thức kỷ luật; người được mời (đại diện công đoàn) chỉ phát biểu, đề xuất, không được bỏ phiếu.",mn:"Chỉ 3 thành viên Hội đồng bỏ phiếu; người được mời không bỏ phiếu.",t:"m",q:"Một tình huống: Công chức N bị Hội đồng kỷ luật họp xem xét. Tại cuộc họp, có 03 thành viên Hội đồng tham dự và 01 đại diện tổ chức công đoàn được mời. Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, ai được bỏ phiếu về hình thức kỷ luật?",o:["Đại diện công đoàn bỏ phiếu thay công chức vi phạm","Cả 04 người đều được bỏ phiếu","Chỉ Chủ tịch Hội đồng bỏ phiếu","Chỉ 03 thành viên Hội đồng kỷ luật được bỏ phiếu; đại diện công đoàn được mời chỉ phát biểu, đề xuất, không được bỏ phiếu"],c:3},{id:"vb10-124",s:"CHƯƠNG 1II - THẨM QUYỀN VÀ TRÌNH TỰ, THỦ TỤC XỬ LÝ KỶ LUẬT",cc:"Các điều 1Ô, 17, 18.29, 0, 21 Nghị định số 1722025 NĐ-CP..45 LÀI LIỆU ÔN CE CÔNG €HUC VIÊN CHỨC FÐI NGUYỄN YONA 09953502H1",gt:"Quy trình đầy đủ: họp kiểm điểm (không bỏ phiếu) ~ 03 ngày làm việc gửi báo cáo.. 05 ngày làm việc thành lập Hội đồng kỷ luật (03 thành viên) ›- họp Hội đồng bỏ phiếu kín. 05 ngày làm việc Hội đồng kiến nghị. cấp có thẩm quyền ra quyết định trong 05 ngày làm việc, quyết định ghi rõ thời điểm có hiệu lực.",mn:"Kiểm điểm (3 ngày).. Hội đồng (5 ngày lập).. kiến nghị (5 ngày) quyết định (5 ngày)...846 PHÂN BỔ SUNG 3 - CHƯƠNG 1II: THẨM QUYỀN, TRÌNH TỰ, THỦ TỤC, HỘI ĐỒNG KỶ LUẬT (TRỌNG TÂM) Phôũn bổ sung cho Chương 1H: thành phần và nguyên tắc làm việc của Hội đồng hỷ luật, tổ chức họp. thời hạn các bước, quyết định kỷ luật, người đã thôi việc/nghỉ hưu. Đáp dân đối chiếu văn bản gốc.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, phương án nào sau đây phản ánh ĐÚNG và ĐẦY ĐỦ nhất quy trình xử lý kỷ luật công chức theo thủ tục đầy đủ?",o:["Tổ chức họp kiểm điểm (không bỏ phiếu) -- trong 03 ngày làm việc gửi báo cáo ¬ trong 05 ngày làm việc thành lập Hội đồng kỷ luật (03 thành viên) ¬ họp Hội đồng bỏ phiếu kín ¬ trong 05 ngày làm việc Hội đồng kiến nghị ¬ cấp có thẩm quyền ra quyết định trong 05 ngày làm việc, quyết định ghi rõ thời điểm có hiệu lực","Lập biên bản vi phạm rồi ra quyết định kỷ luật ngay","Họp toàn cơ quan biểu quyết công khai về hình thức kỷ luật","Cơ quan thanh tra kết luận và ra quyết định kỷ luật"],c:0},{id:"vb10-125",s:"CHƯƠNG 1II - THẨM QUYỀN VÀ TRÌNH TỰ, THỦ TỤC XỬ LÝ KỶ LUẬT",cc:"Khoan I Điều 18 Nghị định số 172/2025/NĐ-CP.",gt:"Chậm nhất 05 ngày làm việc kể từ khi nhận được báo cáo và biên bản cuộc họp kiểm điểm, cấp có thẩm quyền quyết định thành lập Hội đồng kỷ luật (trừ trường hợp không thành lập Hội đồng).",mn:"Thành lập Hội đồng kỷ luật: chậm nhất 5 ngày làm việc.",t:"m",q:"Điền vào chỗ trọng: Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, chậm nhất là [......... | kể từ khi nhận được báo cáo và biên bản cuộc họp kiểm điểm, cấp có thẩm quyền xử lý kỷ luật quyết định thành lập Hội đồng kỷ luật.",o:["03 ngày làm việc","05 ngày làm việc","07 ngày làm việc","10 ngày làm việc"],c:1},{id:"vb10-126",s:"CHƯƠNG 1II - THẨM QUYỀN VÀ TRÌNH TỰ, THỦ TỤC XỬ LÝ KỶ LUẬT",cc:"Điểm a khoản 2 Điều 18 Nghị định số 172/2023/NĐ-CP.",gt:"Hội đồng kỷ luật họp khi có đủ 03 thành viên tham dự; kiến nghị hình thức kỷ luật thông qua bỏ phiếu kín.",mn:"Hội đồng kỷ luật họp: đủ 3 thành viên; bỏ phiếu kín.",t:"m",q:"Điền vào chỗ trọng: Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, Hội đồng kỷ luật công chức họp khi có đủ |[........ | thành viên tham dự.",o:["02","05","04","03"],c:3},{id:"vb10-127",s:"CHƯƠNG 1II - THẨM QUYỀN VÀ TRÌNH TỰ, THỦ TỤC XỬ LÝ KỶ LUẬT",cc:"l)iem b khoản 2 liệu 19 Nghị định số 172/2025/NĐ-CP",gt:"Hội đồng kỷ luật kiến nghị áp dụng hình thức kỷ luật thông qua bỏ phiếu kín; việc họp phải lập biên bản thể hiện rõ ý kiến thành viên và kết quả bỏ phiếu.",mn:"Kiến nghị hình thức kỷ luật: bỏ phiếu kín. 47",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, Hội đồng kỷ luật kiến nghị áp dụng hình thức kỷ luật thông qua hình thức nào?",o:["Biểu quyết giơ tay công khai","Quyết định của Chủ tịch Hội đồng","Bỏ phiếu kín","Lấy ý kiến bằng văn bản"],c:2},{id:"vb10-128",s:"CHƯƠNG 1II - THẨM QUYỀN VÀ TRÌNH TỰ, THỦ TỤC XỬ LÝ KỶ LUẬT",cc:"Khoản 1 Điều 19 Nghị định số 172/2025/NĐ-CP.",gt:"Hội đồng kỷ luật công chức có 03 thành viên: Chủ tịch là người đứng đầu hoặc cấp phó của cơ quan có thẩm quyền xử lý kỷ luật; 01 ủy viên là đại diện lãnh đạo cơ quan trực tiếp sử dụng công chức; 01 ủy viên là đại diện bộ phận tham mưu về tổ chức cán bộ.",mn:"HDKL: 3 thành viên = Chủ tịch + đại diện cơ quan sử dụng + đại diện tổ chức cán bộ.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, Hội đồng kỷ luật công chức (đối với công chức không giữ chức vụ lãnh đạo, quản lý) gồm bao nhiêu thành viên và thành phần như thế nào?",o:["05 thành viên gồm toàn bộ lãnh đạo cơ quan","03 thành viên: Chủ tịch (người đứng đầu hoặc cấp phó cơ quan có thẩm quyền xử lý kỷ luật); 01 ủy viên đại diện lãnh đạo cơ quan trực tiếp sử dụng công chức; 01 ủy viên đại diện bộ phận tham mưu tổ chức cán bộ","02 thành viên: Chủ tịch và một thư ký","07 thành viên do tập thể cơ quan bầu"],c:1},{id:"vb10-129",s:"CHƯƠNG 1II - THẨM QUYỀN VÀ TRÌNH TỰ, THỦ TỤC XỬ LÝ KỶ LUẬT",cc:"Điểm a khoản Ì Đriều 20 Nghị định số 172/2025/NĐ-CP.",gt:"Chậm nhất 05 ngày làm việc trước ngày họp Hội đồng kỷ luật, giấy triệu tập phải được gửi tới công chức có hành vi vi phạm.",mn:"Gửi giấy triệu tập họp HDKL: chậm nhất 5 ngày làm việc trước.",t:"m",q:"Điền vào chỗ trọng: Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, chậm nhất là [......... | trước ngày tổ chức cuộc họp của Hội đồng kỷ luật, giấy triệu tập họp phải được gửi tới công chức có hành vi vi phạm.",o:["03 ngày làm việc","10 ngày làm việc","07 ngày làm việc","05 ngày làm việc"],c:3},{id:"vb10-130",s:"CHƯƠNG 1II - THẨM QUYỀN VÀ TRÌNH TỰ, THỦ TỤC XỬ LÝ KỶ LUẬT",cc:"Điểm a khoản Ì Điều 20 Nghị định số 172/2025/NĐ-CP.",gt:"Trường hợp công chức có hành vi vi phạm vắng mặt theo giấy triệu tập lần thứ 2 thì Hội đồng kỷ luật vẫn tiến hành họp.",mn:"Vắng mặt lần triệu tập thứ 2., vẫn họp. LÀI LIỆU ÔN CE CÔNG €HUC VIÊN CHỨC FÐI NGUYỄN YONA 09953502H1",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, trường hợp công chức có hành vi vi phạm vắng mặt ở cuộc họp Hội đồng kỷ luật theo giấy triệu tập lần thứ 2 thì xử lý như thế nào?",o:["Hội đồng kỷ luật vẫn tiến hành họp","Hoãn hợp vợ thời hạn","Hủy bỏ việc xử lý kỷ luật","Chuyển hồ sơ lên cấp trên"],c:0},{id:"vb10-131",s:"CHƯƠNG 1II - THẨM QUYỀN VÀ TRÌNH TỰ, THỦ TỤC XỬ LÝ KỶ LUẬT",cc:"Điểm b khoản Í Điều ”O Nghị định số 1ˆ” 200 M-CP.",gt:"Người được mời dự họp có quyền phát biểu ý kiến và đề xuất hình thức kỷ luật nhưng không được bỏ phiếu về hình thức kỷ luật.",mn:"Người được mời: phát biểu, đề xuất nhưng KHÔNG bỏ phiếu.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, người được mời dự họp Hội đồng kỷ luật (đại diện tổ chức chính trị - xã hội, cá nhân liên quan) có quyền gì?",o:["Quyết định hình thức kỷ luật","Được bỏ phiếu như thành viên Hội đồng","Phát biểu ý kiến và đề xuất hình thức kỷ luật nhưng không được bỏ phiếu về hình thức kỷ luật","Không được phát biểu"],c:2},{id:"vb10-132",s:"CHƯƠNG 1II - THẨM QUYỀN VÀ TRÌNH TỰ, THỦ TỤC XỬ LÝ KỶ LUẬT",cc:"liệm g khoản ^ hiệu 2U Nghị định số 1522025. MI-C P.",gt:"Hội đồng bỏ phiếu về việc có kỷ luật hay không: nếu đa số kiến nghị kỷ luật thì bỏ phiếu về hình thức kỷ luật; việc bỏ phiếu tiến hành bằng bỏ phiếu kín theo phương pháp tích phiếu.",mn:"Bỏ phiếu HĐKL: kín, theo phương pháp tích phiếu.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, trong trình tự họp Hội đồng kỷ luật, việc bỏ phiếu về việc có kỷ luật hay không và về hình thức kỷ luật được tiến hành như thế nào?",o:["Biểu quyết công khai bằng giơ tay","Bỏ phiếu kín theo phương pháp tích phiếu","Do Chủ tịch Hội đồng quyết định","Lấy ý kiến qua email"],c:1},{id:"vb10-133",s:"CHƯƠNG 1II - THẨM QUYỀN VÀ TRÌNH TỰ, THỦ TỤC XỬ LÝ KỶ LUẬT",cc:"Diện ở khoản 1 liệu 21 Nghị định số 1222005 N)-C P.",gt:"Trong thời hạn 05 ngày làm việc kể từ ngày kết thúc cuộc họp. Hội đồng kỷ luật phải kiến nghị bằng văn bản (kèm biên bản họp và hồ sơ) gửi cấp có thẩm quyền xử lý kỷ luật.",mn:"Kiến nghị sau họp HDKL: 5 ngày làm việc...49 LÀI LIỆU ÔN CE CÔNG €HUC VIÊN CHỨC FÐI NGUYỄN YONA 09953502H1",t:"m",q:"Điền vào chỗ trọng: Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, trong thời hạn |........ ] kể từ ngày kết thúc cuộc họp, Hội đồng kỷ luật phải có kiến nghị việc xử lý kỷ luật bằng văn bản gửi cấp có thẩm quyền xử lý kỷ luật.",o:["03 ngày làm việc","10 ngày làm việc","07 ngày làm việc","05 ngày làm việc"],c:3},{id:"vb10-134",s:"CHƯƠNG 1II - THẨM QUYỀN VÀ TRÌNH TỰ, THỦ TỤC XỬ LÝ KỶ LUẬT",cc:"Khoản 2 Điều 21 Nghị định số 172/2025/NĐ-CP.",gt:"Trường hợp công chức bị Tòa án kết án phạt tù không hưởng án treo hoặc kết án về tham nhũng, trong thời hạn 15 ngày làm việc kể từ ngày nhận được quyết định, bản án có hiệu lực, cấp có thẩm quyền ra quyết định buộc thôi việc.",mn:"Ấn tử (không treo)/tham nhũng -. buộc thôi việc trong 15 ngày làm việc.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, trường hợp công chức bị Tòa án kết án phạt tù mà không được hưởng án treo hoặc bị kết án về hành vi tham nhũng, cấp có thẩm quyền ra quyết định buộc thôi việc trong thời hạn nào?",o:["Trong thời hạn 15 ngày làm việc kể từ ngày nhận được quyết định, bản án có hiệu lực pháp luật","Trong thời hạn 10 ngày làm việc","Trong thời hạn 05 ngày làm việc","Trong thời hạn 30 ngày"],c:0},{id:"vb10-135",s:"CHƯƠNG 1II - THẨM QUYỀN VÀ TRÌNH TỰ, THỦ TỤC XỬ LÝ KỶ LUẬT",cc:"Diện U khoản ở Điều 18 Nghị định số 172.202) NĐ-CP.",gt:"Hội đồng kỷ luật tự giải thể sau khi hoàn thành nhiệm vụ.",mn:"HDKL,: tự giải thể sau khi hoàn thành nhiệm vụ.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, Hội đồng kỷ luật công chức chấm dứt hoạt động vào thời điểm nào?",o:["Sau khi tổ chức xong cuộc họp đầu tiên","Sau 30 ngày kể từ khi thành lập","Tự giải thể sau khi hoàn thành nhiệm vụ","Khi có quyết định kỷ luật của cấp trên"],c:2},{id:"vb10-136",s:"CHƯƠNG 1II - THẨM QUYỀN VÀ TRÌNH TỰ, THỦ TỤC XỬ LÝ KỶ LUẬT",cc:"Điển d khonn Ì Điều 2O Nghị định số 1727220205 NĐ -CP.",gt:"Hồ sơ trình Hội đồng kỷ luật gồm: bản tự kiểm điểm, trích ngang sơ yếu lý lịch. biên bản cuộc họp kiểm điểm của cơ quan sử dụng công chức và các tài liệu khác có liên quan.",mn:"Hồ sơ HĐDKL,: tự kiểm điểm - sơ yếu lv lịch - biên bản kiểm điểm + tài liệu liên quan.. s50",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, hồ sơ xử lý kỷ luật trình Hội đồng kỷ luật gồm những tài liệu nào?",o:["Chỉ cần biên bản họp kiểm điểm","Chỉ cần bản tự kiểm điểm","Bản tự kiểm điểm, trích ngang sơ yếu lý lịch của công chức, biên bản cuộc họp kiểm điểm và các tài liệu khác có liên quan","Chỉ cần sơ yếu lý lịch"],c:2},{id:"vb10-137",s:"CHƯƠNG 1II - THẨM QUYỀN VÀ TRÌNH TỰ, THỦ TỤC XỬ LÝ KỶ LUẬT",cc:"Khoản 3 Điều 19 Nghị định số 172/2025/NĐ-CP.",gt:"Khi người đứng đầu và tất cả cấp phó thuộc trường hợp phải tránh (người thân thích hoặc trong cùng vụ việc) thì người đứng đầu hoặc cấp phó của cơ quan cấp trên trực tiếp, hoặc người được ủy quyền làm Chủ tịch Hội đồng.",mn:"Lãnh đạo đều phải tránh ~. cấp trên trực tiếp làm Chủ tịch HĐKL.",t:"m",q:"Một tình huống vận dụng: Tại một cơ quan, người đứng đầu và tất cả cấp phó đều là người thân thích của công chức bị xem xét kỷ luật. Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, ai làm Chủ tịch Hội đồng kỷ luật?",o:["Người đứng đầu hoặc cấp phó của người đứng đầu cơ quan cấp trên trực tiếp, hoặc người được ủy quyền","Một công chức bất kỳ trong cơ quan","Chính công chức bị xem xét kỷ luật","Không thành lập Hội đồng kỷ luật"],c:0},{id:"vb10-138",s:"CHƯƠNG 1II - THẨM QUYỀN VÀ TRÌNH TỰ, THỦ TỤC XỬ LÝ KỶ LUẬT",cc:"Điều 22 và Điều 23 Nghị định số 172/2025/NĐ-CP.",gt:"Người đã thôi việc, nghỉ hưu có hành vi vi phạm trong thời gian công tác văn bị xử lý kỷ luật theo thẩm quyền, trình tự, thủ tục quy định tại Nghị định (Mục 3 Chương I1).",mn:"Đã thôi việc/nghỉ hưu vẫn bị xử lý kỷ luật vi phạm thời gian công tác.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, đối với người đã thôi việc, nghỉ hưu có hành vi vi phạm trong thời gian công tác, việc xử lý kỷ luật được thực hiện như thế nào?",o:["Không xử lý vi đã thôi việc, nghỉ hưu","Vẫn bị xử lý kỷ luật theo thẩm quyền, trình tự, thủ tục do Nghị định quy định","Chỉ xử lý nếu con là đảng viên","Chuyến toàn bộ sang xử lý hình sự"],c:1},{id:"vb10-139",s:"CHƯƠNG 1II - THẨM QUYỀN VÀ TRÌNH TỰ, THỦ TỤC XỬ LÝ KỶ LUẬT",cc:"Khoản 3 Điều 20 Nghị định số 172,/20D25/NIE)-CP.",gt:"Trường hợp nhiều công chức trong cùng cơ quan có hành vi vi phạm thì Hội đồng kỷ luật họp để xem xét xử lý kỷ luật đối với từng công chức.",mn:"Nhiêu người vi phạm. xét kỷ luật từng người. s51]",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, trường hợp nhiều công chức trong cùng cơ quan, tổ chức, đơn vị có hành vi vi phạm thì Hội đồng kỷ luật xử lý như thế nào?",o:["Họp chứng và ra một quyết định cho tất cả","Chuyến toàn bộ lên cấp trên xử lý","Chỉ xử lý người vi phạm nặng nhất","Họp để tiến hành xem xét xử lý kỷ luật đối với từng công chức"],c:3},{id:"vb10-140",s:"CHƯƠNG 1II - THẨM QUYỀN VÀ TRÌNH TỰ, THỦ TỤC XỬ LÝ KỶ LUẬT",cc:"J)iem b khoản 1Ì Điều 21 Nghị định số 172/2025/N)D- CP.",gt:"Trong thời hạn 05 ngày làm việc kể từ ngày nhận được văn bản kiến nghị của Hội đồng (nếu có Hội đồng) hoặc biên bản cuộc họp kiểm điểm/văn bản đề xuất của cơ quan tham mưu (nếu không thành lập Hội đồng), cấp có thẩm quyền ra quyết định kỷ luật hoặc kết luận không vi phạm.",mn:"Ra QD kỷ luật: 5 ngày làm việc kể từ khi nhận kiến nghị/biên bản.",t:"m",q:"Một tình huống vận dụng: Sau cuộc họp kiểm điểm, cấp có thẩm quyền nhận được biên bản nhưng vụ việc thuộc trường hợp không phải thành lập Hội đồng kỷ luật. Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, thời hạn ra quyết định kỷ luật được tính như thế nào?",o:["Trong thời hạn 30 ngày","Trong thời hạn 05 ngày làm việc kể từ ngày nhận được biên bản cuộc họp kiểm điểm hoặc văn bản đề xuất của cơ quan tham mưu","Không có thời hạn cụ thể","Trong thời hạn 60 ngày"],c:1},{id:"vb10-141",s:"CHƯƠNG 1II - THẨM QUYỀN VÀ TRÌNH TỰ, THỦ TỤC XỬ LÝ KỶ LUẬT",cc:"Khoản 3 Điều 21 Nghị định số 172/2025/NĐ-CP.",gt:"Quyết định kỷ luật phải ghi rõ thời điểm có hiệu lực thi hành.",mn:"()D kỷ luật: ghi rõ thời điểm có hiệu lực thi hành.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, quyết định kỷ luật công chức bắt buộc phải ghi rõ nội dung nào?",o:["Thời điểm có hiệu lực thi hành","Mức lương mới của công chức","Danh sách thành viên Hội đồng kỷ luật","Số phiếu bầu chi tiết của từng thành viên"],c:0},{id:"vb10-142",s:"CHƯƠNG 1II - THẨM QUYỀN VÀ TRÌNH TỰ, THỦ TỤC XỬ LÝ KỶ LUẬT",cc:"Khoản 3 Điều 19 Nghị định số 172/2025/NĐ-CP.",gt:"Không thành lập Hội đồng kỷ luật đối với trường hợp đã có kết luận của cấp có thẩm quyền về hành vi vi phạm (trường hợp quy định tại khoản 3 Điều 10 Nghị định).",mn:"Không lập HDKL khi đã có kết luận của cấp có thẩm quyền về vị phạm.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, trường hợp nào sau đây KHÔNG thành lập Hội đồng kỷ luật công chức?",o:["Mọi trường hợp công chức vi phạm","Khi vi phạm chỉ đến mức khiển trách","Khi công chức tự nhận lỗi","Trường hợp công chức đã có kết luận về hành vi vi phạm của cấp có thẩm quyền (theo khoản 3 Điều 16)"],c:3},{id:"vb10-143",s:"CHƯƠNG 1II - THẨM QUYỀN VÀ TRÌNH TỰ, THỦ TỤC XỬ LÝ KỶ LUẬT",gt:"Trường hợp công chức có mặt nhưng không làm bản tự kiểm điểm (hoặc vắng mặt không có bản kiểm điểm) thì Hội đồng kỷ luật vẫn tiến hành các trình tự còn lại của cuộc họp.",mn:"Không có bản tự kiểm điểm * Hội động vẫn họp tiếp.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, trong cuộc họp Hội đồng kỷ luật, nếu công chức có hành vi vi phạm có mặt nhưng không làm bản tự kiểm điểm thì xử lý thế nào?",o:["Hoãn cuộc họp đến khi có bản tự kiểm điểm","Hủy bỏ việc xử lý kỷ luật ¡152","Hội đồng kỷ luật tiến hành các trình tự còn lại của cuộc họp","Buộc công chức rời cuộc họp"],c:2},{id:"vb10-144",s:"CHƯƠNG 1II - THẨM QUYỀN VÀ TRÌNH TỰ, THỦ TỤC XỬ LÝ KỶ LUẬT",cc:"Điều 27 Nghị định số 172/2025/NĐ-CP.",gt:"Công chức không đồng ý với quyết định xử lý kỷ luật có quyền khiếu nại quyết định đó theo quy định của pháp luật về khiếu nại.",mn:"Không đồng ý QĐÐ kỷ luật. khiếu nại theo pháp luật về khiếu nại.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, công chức có quyền gì nếu không đồng ý với quyết định xử lý kỷ luật?",o:["Khiếu nại quyết định xử lý kỷ luật theo quy định của pháp luật về khiếu nại","Tự ý không chấp hành quyết định","Yêu cầu hủy bỏ quyết định mà không cần thủ tục","Không có quyền khiếu nại"],c:0},{id:"vb10-145",s:"CHƯƠNG 1II - THẨM QUYỀN VÀ TRÌNH TỰ, THỦ TỤC XỬ LÝ KỶ LUẬT",cc:"Điều 17 Nghị định số 172/2025/NĐ-CP.",gt:"Họp kiểm điểm nhãm để công chức tự kiểm điểm, làm rõ hành vi vi phạm, cơ quan, tổ chức nhận xét và đề xuất, làm cơ sở cho cấp có thẩm quyền xem xét xử lý kỷ luật.",mn:"Họp kiểm điểm: công chức tự kiểm điểm + cơ quan nhận xét, đề xuất...53 hận xét, đề xuất...53 LÀI LIỆU ÔN CE CÔNG €HUC VIÊN CHỨC FÐI NGUYỄN YONA 09953502H1 Phạm vi: Điều 24 đến Điều 27 — các quy định liên quan khi xem xét xử lý kỷ luật: các quy định sau khi có quyết định kỷ luật Ctbuộc thôi việc, oan sai): chế độ, chính sách khi bị tạm QIỪ, tạm giam: hhiều nại quyết định xử lý kỷ luật,",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, việc tổ chức họp kiểm điểm công chức có hành vi vi phạm nhằm mục đích gì?",o:["Để quyết định ngay hình thức kỷ luật mà không qua thủ tục khác","Để công khai phê bình trước toàn cơ quan","Để thay thế hoàn toàn cho Hội đồng kỷ luật","Để công chức từ kiểm điểm, làm rõ hành vi vi phạm, cơ quan nhận xét và đề xuất, làm cơ sở cho cấp có thẩm quyền xem xét"],c:3},{id:"vb10-146",s:"CHƯƠNG 1V - QUY ĐỊNH KHÁC CÓ LIÊN QUAN ĐẾN XỬ LÝ KỶ LUẬT",cc:"Khoan Ì Điều 24 Nghị định số 122/240125.NĐ-CĐ.",gt:"Cán bộ. công chức đang trong thời gian thi hành quyết định kỷ luật, đang trong thời hạn xử lý kỷ luật hoặc đang bị điều tra, truy tố, xét xử mà đến tuổi nghỉ hưu thì vẫn được giải quyết thủ tục hưởng chế độ hưu trí - bảo đảm quyền an sinh, việc xử lý kỷ luật/vì phạm được tiếp tục xem xét theo quy định về người đã nghỉ hưu.",mn:"Đến tuổi nghỉ hưu (dự đang bị xử lý).. văn giải quyết hưu trí.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, cán bộ, công chức có hành vi vi phạm đang trong thời gian thi hành quyết định kỷ luật, đang trong thời hạn xử lý kỷ luật hoặc đang bị điều tra, truy tố, xét xử mà đến tuổi nghỉ hưu thì được giải quyết như thế nào?",o:["Tạm dừng giải quyết chế độ hưu trí cho đến khi có kết luận","Vẫn thực hiện giải quyết thủ tục hưởng chế độ hưu trí","Không được hưởng chế độ hưu trí","Chỉ được hưởng 50% chế độ hưu trí"],c:1},{id:"vb10-147",s:"CHƯƠNG 1V - QUY ĐỊNH KHÁC CÓ LIÊN QUAN ĐẾN XỬ LÝ KỶ LUẬT",cc:"liên ở khoan Í Điều 2Ÿ Nghị định số 122 20059. MỞ-C P.",gt:"Công chức bị buộc thôi việc thì không được hưởng chế độ thôi việc nhưng được cơ quan bảo hiểm xã hội xác nhận thời gian làm việc đã đóng bảo hiểm xã hội để thực hiện chế độ bảo hiểm xã hội theo quy định.",mn:"Buộc thôi việc: không có chế độ thôi việc. nhưng được xác nhận thời gian đóng BHXH.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, công chức bị xử lý kỷ luật buộc thôi việc được hưởng quyền lợi nào về bảo hiểm xã hội?",o:["Mất toàn bộ quyền lợi bảo hiểm xã hội đã đóng","Được hưởng đầy đủ chế độ thôi việc như nghỉ việc thông thường","Không được hưởng chế độ thôi việc nhưng được cơ quan bảo hiểm xã hội xác nhận thời gian làm việc đã đóng bảo hiểm xã hội để thực hiện chế độ bảo hiểm xã hội theo quy định","Được hưởng trợ cấp một lần bằng 50% chế độ thôi việc"],c:2},{id:"vb10-148",s:"CHƯƠNG 1V - QUY ĐỊNH KHÁC CÓ LIÊN QUAN ĐẾN XỬ LÝ KỶ LUẬT",cc:"liêm c khoản 1 Điều 25 Nghị định số 172/2025/NĐ-CP.",gt:"Sau 12 tháng kể từ ngày quyết định buộc thôi việc có hiệu lực, công chức bị buộc thôi việc được quyền đăng ký dự tuyển vào các cơ quan, tổ chức, đơn vị của Nhà nước.",mn:"Buộc thôi việc: sau 12 tháng được đăng ký dự tuyển lại.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, sau bao lâu kể từ ngày quyết định kỷ luật buộc thôi việc có hiệu lực, công chức bị buộc thôi việc được quyền đăng ký dự tuyển vào các cơ quan, tổ chức, đơn vị của Nhà nước?",o:["Sau 12 tháng","Sau 06 tháng","Sau 24 tháng..54","Sau 36 tháng"],c:0},{id:"vb10-149",s:"CHƯƠNG 1V - QUY ĐỊNH KHÁC CÓ LIÊN QUAN ĐẾN XỬ LÝ KỶ LUẬT",cc:"Điểm c khoản 1 Điều 25 Nghị định số 172/2025/NĐ-CP.",gt:"Trường hợp bị buộc thôi việc do tham nhũng, tham ô hoặc vi phạm đạo đức công vụ thì không được đăng ký dự tuyển vào các cơ quan hoặc vị trí công tác có liên quan đến nhiệm vụ, công vụ đã đảm nhiệm - hạn chế đặc thù để phòng ngừa tái diện.",mn:"Buộc thôi việc do tham nhũng/đạo đức công vụ: không dự tuyển vào vị trí liên quan đã đảm nhiệm.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, công chức bị buộc thôi việc do tham nhũng, tham ô hoặc vi phạm đạo đức công vụ bị hạn chế quyền gì khi đăng ký dự tuyển lại?",o:["Vĩnh viên không được dự tuyển vào bất kỳ cơ quan nhà nước nào","Không bị hạn chế gì, được dự tuyển bình thường sau 12 tháng","Không được đăng ký dự tuyển vào các cơ quan hoặc vị trí công tác có liên quan đến nhiệm vụ, công vụ đã đảm nhiệm","Chỉ được dự tuyển vào đơn vị sự nghiệp công lập"],c:2},{id:"vb10-150",s:"CHƯƠNG 1V - QUY ĐỊNH KHÁC CÓ LIÊN QUAN ĐẾN XỬ LÝ KỶ LUẬT",cc:"Khoản 2 Điều 25 Nghị định số 172/2025/NĐ- CĐ.",gt:"Khi quyết định kỷ luật bị kết luận là oan, sai thì chậm nhất 10 ngày làm việc kể từ ngày có văn bản kết luận hoặc từ ngày quyết định của Tòa án có hiệu lực, người đứng đầu cơ quan nơi cán bộ, công chức làm việc công bố công khai tại cơ quan nơi đang công tác — phục hồi danh dự.",mn:"Oan sai: 10 ngày làm việc công bố công khai.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, khi quyết định kỷ luật được cơ quan có thẩm quyền hoặc Tòa án kết luận là oan, sai thì việc công bố công khai được thực hiện trong thời hạn nào?",o:["Chậm nhất 30 ngày làm việc","Chậm nhất 10 ngày làm việc kể từ ngày có văn bản kết luận hoặc từ ngày quyết định của Tòa án có hiệu lực, người đứng đầu cơ quan nơi cán bộ, công chức làm việc công bố công khai","Chậm nhất 05 ngày làm việc","Không bắt buộc công bố công khai"],c:1},{id:"vb10-151",s:"CHƯƠNG 1V - QUY ĐỊNH KHÁC CÓ LIÊN QUAN ĐẾN XỬ LÝ KỶ LUẬT",cc:"Khoản 3 Điều 25 Nghị định số 172/2025/NH)-CP.",gt:"Công chức bị cách chức, buộc thôi việc sau đó được kết luận oan, sai mà vị trí cũ đã có người thay thế thì người đứng đầu cơ quan có thẩm quyền có trách nhiệm bố trí vào vị trí công tác, chức vụ lãnh đạo, quản lý phù hợp - bảo đảm quyền lợi người bị oan, sai.",mn:"Oan sai mà vị trí cũ đã có người: bố trí vào vị trí phù hợp.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, công chức bị cách chức, buộc thôi việc sau đó được kết luận là oan, sai mà vị trí công tác cũ đã bố trí người khác thay thế thì được giải quyết như thế nào?",o:["Được trở lại đúng vị trí cử, người thay thế bị điều chuyển","Phải cho đến khi có vị trí trong mới được bố trí lại","Chỉ được nhận trợ cấp, không được bố trí lại công tác s55","Người đứng đầu cơ quan có thẩm quyền có trách nhiệm bố trí vào vị trí công tác, chức vụ lãnh đạo, quản lý phù hợp"],c:3},{id:"vb10-152",s:"CHƯƠNG 1V - QUY ĐỊNH KHÁC CÓ LIÊN QUAN ĐẾN XỬ LÝ KỶ LUẬT",gt:"Trong thời gian bị tạm giữ, tạm giam (hoặc tại ngoại nhưng bị cấm đi khỏi nơi cư trú, không thể đi làm) mà chưa bị xem xét kỷ luật thì được hưởng 50% của mức lương hiện hưởng, cộng với phụ cấp chức vụ lãnh đạo, phụ cấp thâm niên vượt khung, phụ cấp thâm niên nghề và hệ số chênh lệch bảo lưu lương (nếu có).",mn:"Tạm giữ, tạm giam: hưởng 50% lương + một số phụ cấp.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, cán bộ, công chức đang trong thời gian bị tạm giữ, tạm giam (chưa bị xử lý kỷ luật) được hưởng chế độ tiền lương như thế nào?",o:["Được hưởng 50% của mức lương hiện hưởng, cộng với phụ cấp chức vụ lãnh đạo, phụ cấp thâm niên vượt khung, phụ cấp thâm niên nghề và hệ số chênh lệch bảo lưu lương (nếu có)","Được hưởng 100% mức lương hiện hưởng","Được hưởng 70% mức lương hiện hưởng","Không được hưởng lương trong thời gian tạm giữ, tạm giam"],c:0},{id:"vb10-153",s:"CHƯƠNG 1V - QUY ĐỊNH KHÁC CÓ LIÊN QUAN ĐẾN XỬ LÝ KỶ LUẬT",cc:"Khoản 2 liệu 2b Nghị định số 172/2025/NĐ-CP.",gt:"Trường hợp không bị xử lý kỷ luật hoặc được kết luận oan, sai thì được truy lĩnh 50% còn lại của mức lương và các khoản theo quy định (đã hưởng 50% trong thời gian tạm giữ, tạm giam).",mn:"Không bị kỷ luật / oan sai -. truy lĩnh 50% còn lại.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, trường hợp cán bộ, công chức sau khi tạm giữ, tạm giam KHÔNG bị xử lý kỷ luật hoặc được kết luận là oan, sai thì được giải quyết về tiền lương như thế nào?",o:["Không được truy lĩnh phần lương còn lại","Được truy lĩnh 50% còn lại của mức lương và các khoản theo quy định","Chỉ được truy lĩnh 25% còn lại","Được truy lĩnh toàn bộ 100% lương kể cả phần đã hưởng"],c:1},{id:"vb10-154",s:"CHƯƠNG 1V - QUY ĐỊNH KHÁC CÓ LIÊN QUAN ĐẾN XỬ LÝ KỶ LUẬT",cc:"Khoản 3 Điều 2b Nghị định số 15223023 NĐ-CP.",gt:"Trường hợp bị buộc thôi việc hoặc bị Tòa án tuyên là có tội thì không được truy lĩnh 50% còn lại của mức lương trong thời gian tạm giữ, tạm giam.",mn:"Buộc thôi việc: cótội. › không truy lĩnh 50% còn lại.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, trường hợp cán bộ, công chức bị buộc thôi việc hoặc bị Tòa án tuyên là có tội thì phần 50% lương còn lại trong thời gian tạm giữ, tạm giam được giải quyết như thế nào?",o:["Được bảo lưu để hướng sau khi chấp hành xong bản án","Được truy lĩnh đầy đủ 50% còn lại..56 LÀI LIỆU ÔN CE CÔNG €HUC VIÊN CHỨC FÐI NGUYỄN YONA 09953502H1","Được truy lĩnh 25% còn lại","Không được truy lĩnh 50% còn lại"],c:3},{id:"vb10-155",s:"CHƯƠNG 1V - QUY ĐỊNH KHÁC CÓ LIÊN QUAN ĐẾN XỬ LÝ KỶ LUẬT",cc:"Nhuan 3 Điều 2b Nghị định số 172 -202057NĐ-CP.",gt:"Cán bộ, công chức đang trong thời gian bị tạm giữ, tạm giam thì đương nhiên bị tạm đình chỉ công tác, tạm đình chỉ chức vụ (nếu có). Khi được tại ngoại thì việc tạm đình chỉ thực hiện theo đề nghị của cơ quan tiến hành tố tụng hoặc quyết định của cấp có thẩm quyền.",mn:"lạm giữ, tạm giam -- đương nhiên tạm đình chỉ công tác, chức vụ.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, cán bộ, công chức đang trong thời gian bị tạm giữ, tạm giam thì việc tạm đình chỉ công tác, chức vụ được thực hiện như thế nào?",o:["Chỉ tạm đình chỉ khi có quyết định của Tòa án","Vẫn tiếp tục công tác bình thường","Đương nhiên bị tạm đình chỉ công tác, tạm đình chỉ chức vụ (nếu có)","Phải có đề nghị của cơ quan điều tra mới tạm đình chỉ"],c:2},{id:"vb10-156",s:"CHƯƠNG 1V - QUY ĐỊNH KHÁC CÓ LIÊN QUAN ĐẾN XỬ LÝ KỶ LUẬT",cc:"f)i0ÓU 27 Nghị định số 172:2025/N12-C.P.",gt:"Cán bộ, công chức bị xử lý kỷ luật có quyền khiếu nại đối với quyết định kỷ luật theo quy định của pháp luật về khiếu nại - bảo đảm quyền bảo vệ lợi ích hợp pháp.",mn:"Bị kỷ luật: có quyền khiếu nại theo pháp luật về khiếu nại.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, cán bộ, công chức bị xử lý kỷ luật có quyền gì đối với quyết định kỷ luật?",o:["Không có quyền khiếu nại quyết định kỷ luật","Có quyền khiếu nại đối với quyết định kỷ luật theo quy định của pháp luật về khiếu nại","Chỉ có quyền kiến nghị, không có quyền khiếu nại","Có quyền từ chối thi hành quyết định kỷ luật"],c:1},{id:"vb10-157",s:"CHƯƠNG 1V - QUY ĐỊNH KHÁC CÓ LIÊN QUAN ĐẾN XỬ LÝ KỶ LUẬT",cc:"Khoản 4 Điều 25 Nghị định số 172/2025/N)-CP.",gt:"Nếu kết luận việc xử lý kỷ luật không đúng quy định về áp dụng hình thức, trình tự, thủ tục, thẩm quyền thì cấp có thẩm quyền phải ra quyết định hủy bỏ quyết định xử lý kỷ luật đã ban hành và tiến hành xem xét xử lý kỷ luật lại theo đúng quy định.",mn:"Kỷ luật sai quy định —› hủy bỏ quyết định và làm lại đúng quy định.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, trường hợp cơ quan giải quyết khiếu nại, tố cáo kết luận việc xử lý kỷ luật công chức tiến hành không đúng quy định về áp dụng hình thức, trình tự, thủ tục, thẩm quyền thì xử lý như thế nào?",o:["Chuyển hồ sơ cho cơ quan thanh tra xử lý","Giữ nguyên quyết định kỷ luật đã ban hành","Chỉ điều chỉnh hình thức kỷ luật, không hủy bỏ quyết định","Cấp có thẩm quyền kỷ luật phải ra quyết định hủy bỏ quyết định xử lý kỷ luật đã ban hành và tiến hành xem xét xử lý kỷ luật lại theo đúng quy định"],c:3},{id:"vb10-158",s:"CHƯƠNG 1V - QUY ĐỊNH KHÁC CÓ LIÊN QUAN ĐẾN XỬ LÝ KỶ LUẬT",cc:"Khoản 2 Điều 2b và khoản 2 Điều 25 Nghị định số 172/2025/NĐ-CP.",gt:"Ông K được kết luận oan, không vi phạm nên được truy lĩnh 50% còn lại của mức lương (khoản 2 Điều 26) và được công bố công khai về việc oan, sai trong thời hạn quy định (khoản 2 Điều 25).",mn:"Oan sai: truy lĩnh 50% còn lại + công bố công khai. J",t:"m",q:"Một tình huống: Ông K là công chức bị tạm giam phục vụ điều tra, đã hưởng 50% lương trong thời gian tạm giam. Sau đó ông K được cơ quan có thẩm quyền kết luận là oan, không vi phạm. Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, ông K được giải quyết như thế nào?",o:["Không được truy lĩnh phân lương còn lại","Chỉ được tiếp tục hưởng 50% lương như trong thời gian tạm giam","Được truy lĩnh 50% còn lại của mức lương và các khoản theo quy định, đồng thời được công bố công khai về việc oan, sai","Phải cho Tòa án xét xử mới được giải quyết"],c:2},{id:"vb10-159",s:"CHƯƠNG 1V - QUY ĐỊNH KHÁC CÓ LIÊN QUAN ĐẾN XỬ LÝ KỶ LUẬT",cc:"fiệm c khoản 1 Điều 25 Nghị định số 172/2025/NĐ-CP.",gt:"Dù đã qua 12 tháng, bà L bị buộc thôi việc do tham ô nên không được đăng ký dự tuyển vào cơ quan hoặc vị trí công tác có liên quan đến nhiệm vụ, công vụ đã đảm nhiệm (lĩnh vực tài chính bà từng phụ trách). Quy định 12 tháng chỉ mở lại quyền dự tuyển nói chung, không áp dụng cho vị trí liên quan trong trường hợp tham nhũng, tham ô, vi phạm đạo đức công vụ.",mn:"Đuộc thôi việc do tham ô: vấn cấm dự tuyển vào vị trí liên quan đã đảm nhiệm.",t:"m",q:"Một tình huống: Bà L là công chức bị buộc thôi việc do hành vi tham ô. Sau 14 tháng, bà L muốn đăng ký dự tuyển trở lại vào chính lĩnh vực tài chính mà bà từng phụ trách. Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, bà L có được dự tuyển vào vị trí đó không?",o:["Không được, vi bị buộc thôi việc do tham ô thì không được đăng ký dự tuyển vào cơ quan hoặc vị trí công tác có liên quan đến nhiệm vụ, công vụ đã đảm nhiệm","Được, vì đã qua 12 tháng kể từ ngày buộc thôi việc","Được, nếu có cam kết không tái phạm","Được, nếu được người đứng đầu cơ quan cử đồng ý"],c:0},{id:"vb10-160",s:"CHƯƠNG 1V - QUY ĐỊNH KHÁC CÓ LIÊN QUAN ĐẾN XỬ LÝ KỶ LUẬT",cc:"Khoản 2 liệu 24 Nghị định số 172/2025/NĐ)-CP.",gt:"Trường hợp Hội đồng kỷ luật đã có văn bản kiến nghị nhưng chưa ra quyết định mà phát hiện thêm tình tiết liên quan hoặc hành vi vi phạm khác thì Hội đồng kỷ luật xem xét kiến nghị lại hình thức kỷ luật - bảo đảm xử lý đầy đủ, đúng mức.",mn:"Phát hiện thêm tình tiếUvi phạm —„ Hội đồng kiến nghị lại hình thức kỷ luật.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, trường hợp Hội đồng kỷ luật đã có văn bản kiến nghị nhưng chưa ra quyết định kỷ luật mà phát hiện thêm tình tiết liên quan đến vi phạm hoặc phát hiện hành vi vi phạm khác thì xử lý như thế nào?",o:["Hội đồng kỷ luật xem xét kiến nghị lại hình thức kỷ luật","Giữ nguyên kiến nghị đã có và ra quyết định kỷ luật..58","Hủy bỏ toàn bộ quá trình và bắt đầu lại từ đầu","Chuyển hồ sơ cho cơ quan điều tra"],c:0},{id:"vb10-161",s:"CHƯƠNG 1V - QUY ĐỊNH KHÁC CÓ LIÊN QUAN ĐẾN XỬ LÝ KỶ LUẬT",cc:"Khoản 3 Điều 24 Nghị định số 172/200205/NĐ-CP.",gt:"Việc cách chức các chức danh tư pháp đối với công chức được thực hiện theo quy định của pháp luật chuyên ngành (ví dụ pháp luật về tổ chức Tòa án, Viện kiểm sát) — có tính đặc thù.",mn:"Cách chức chức danh tư pháp: theo pháp luật chuyên ngành.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, việc cách chức các chức danh tư pháp đối với công chức được thực hiện theo quy định nào?",o:["Theo quyết định của người đứng đầu cơ quan sử dụng","Theo quy định chung của Nghị định này","Theo quy định của pháp luật chuyên ngành","Theo quy định của pháp luật về khiếu nại"],c:2},{id:"vb10-162",s:"CHƯƠNG 1V - QUY ĐỊNH KHÁC CÓ LIÊN QUAN ĐẾN XỬ LÝ KỶ LUẬT",gt:"Cả ba đều đúng: trong thời gian tạm giữ, tạm giam hưởng 50% lương: nếu không bị kỷ luậUoan sai thì truy lĩnh 50% còn lại; nếu buộc thôi việc hoặc bị tuyên có tội thì không truy lĩnh 50% còn lại.",mn:"Tạm giam: 50% lương ¬ oan sai (truy lĩnh 50%) / có tội (không truv lĩnh).",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, các nội dung sau có cùng đúng về chế độ khi bị tạm giữ, tạm giam hay không: (i) hưởng 50% mức lương hiện hưởng; (ii) không bị kỷ luậUoan sai thì truy lĩnh 50% còn lại; (iii) buộc thôi việc hoặc bị tuyên có tội thì không truy lĩnh 50% còn lại?",o:["Chỉ nội dung (i) đúng","Chỉ nội dung (I) và (Ii) đúng","Cả ba nội dung đều đúng","Không nội dung nào đúng"],c:2},{id:"vb10-163",s:"CHƯƠNG 1V - QUY ĐỊNH KHÁC CÓ LIÊN QUAN ĐẾN XỬ LÝ KỶ LUẬT",cc:"liểm ‹ khoản 1 1iểu 25 Nghị dùnh số 122-2005 N4",gt:"Công chức bị buộc thôi việc do tham nhũng thì không được dự tuyển vào cơ quan hoặc vị trí công tác có liên quan đến nhiệm vụ, công vụ đã đảm nhiệm, kể cả sau 12 tháng. Vì vậy phương án D sai. A, B.C đều đúng.",mn:"Buộc thôi việc do tham nhũng: vấn cầm dự tuyển vào vị trí liên quan đã đảm nhiệm.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, nhận định nào sau đây về các quy định sau khi có quyết định kỷ luật là KHÔNG đúng?",o:["Công chức bị buộc thôi việc được cơ quan bảo hiểm xã hội xác nhận thời gian đã đóng bảo hiểm xã hội..59 LÀI LIỆU ÔN CE CÔNG €HUC VIÊN CHỨC FÐI NGUYỄN YONA 09953502H1","Sau 12 tháng, công chức bị buộc thôi việc được quyền đăng ký dự tuyển vào cơ quan nhà nước","Quyết định kỷ luật bị kết luận oan, sai phải được công bố công khai chậm nhất 10 ngày làm việc","Công chức bị buộc thôi việc do tham nhũng vẫn được dự tuyển vào chính vị trí công tác đã đảm nhiệm sau 12 tháng"],c:3},{id:"vb10-164",s:"CHƯƠNG 1V - QUY ĐỊNH KHÁC CÓ LIÊN QUAN ĐẾN XỬ LÝ KỶ LUẬT",cc:"Nhoan 4 Điều 2b Nghị định số 17220257NĐ-CP.",gt:"Cán bộ, công chức đã có quyết định khởi tố bị can nhưng được tại ngoại thì đương nhiên bị tạm đình chỉ chức vụ (nếu có); cấp có thẩm quyền sử dụng phân công công tác theo thẩm quyền; việc tạm đình chỉ công tác theo đề nghị của cơ quan tiến hành tố tụng hoặc quyết định của cơ quan quản lý.",mn:"Khởi tố bị can nhưng tại ngoại. đương nhiên tạm đình chỉ chức vụ.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, cán bộ, công chức đã có quyết định khởi tố bị can nhưng được tại ngoại thì việc tạm đình chỉ chức vụ được xử lý như thế nào?",o:["Vẫn giữ nguyên chức vụ và tiếp tục công tác bình thường","Đương nhiên bị tạm đình chỉ chức vụ (nếu có); cấp có thẩm quyền sử dụng phân công công tác theo thẩm quyền; việc tạm đình chỉ công tác theo đề nghị của cơ quan tiến hành tố tụng hoặc quyết định của cơ quan quản lý","Đương nhiên bị buộc thôi việc","Đương nhiên bị cách chức"],c:1},{id:"vb10-165",s:"CHƯƠNG 1V - QUY ĐỊNH KHÁC CÓ LIÊN QUAN ĐẾN XỬ LÝ KỶ LUẬT",cc:"Điểm b khoản 1 Điều 25 Nghị định số 17220203 Nh-CP.",gt:"Cơ quan có thẩm quyền quản lý hồ sơ công chức bị buộc thôi việc có trách nhiệm cung cấp bản tóm tắt lý lịch và nhận xét (có xác nhận) khi công chức đó yêu cầu.",mn:"Buộc thôi việc: được cấp bản tóm tắt lý lịch + nhận xét (có xác nhận) khi vêu cầu.. 560 LÀI LIỆU ÔN CE CÔNG €HUC VIÊN CHỨC FÐI NGUYỄN YONA 09953502H1",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, công chức bị buộc thôi việc có được cơ quan quản lý cung cấp tài liệu gì khi có yêu cầu?",o:["Bản tóm tắt lý lịch và nhận xét (có xác nhận) do cơ quan có thẩm quyền quản lý hồ sơ cung cấp","Toàn bộ hồ sơ gốc của công chức","Quyết định kỷ luật về đảng","Không được cung cấp bất kỳ tài liệu nào"],c:0},{id:"vb10-166",s:"CHƯƠNG 1V - QUY ĐỊNH KHÁC CÓ LIÊN QUAN ĐẾN XỬ LÝ KỶ LUẬT",cc:"Các điều 24, 25, 2b. 27 Nghị định vỏ 152 20203/NEĐ-CB.",gt:"Các quy định bảo vệ quyền lợi gồm: giải quyết hưu trí đủ đang bị xử lý: hưởng 50% lương khi tạm giữ, tạm giam, truy lĩnh phần còn lại nếu oan, sai; công bố công khai và bố trí lại công tác phù hợp nêu oan, sai: quyền khiếu nại quyết định kỷ luật; quyết định sai quy định phải bị hủy bỏ và làm lại.",mn:"Bảo vệ quyền lợi: hưu trí — 50% lương — phục hồi oan sai — khiếu nại — hủy quyết định sai. mại",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, phương án nào sau đây phản ánh ĐÚNG và ĐẦY ĐỦ nhất các quy định bảo vệ quyền lợi của cán bộ, công chức trong và sau quá trình xử lý kỷ luật?",o:["Không có cơ chế khiếu nại hay phục hồi quyền lợi","Mọi quyền lợi đều bị chấm dứt ngay khi có quyết định kỷ luật","Được giải quyết hưu trí đủ đang bị xử lý; được hướng 50% lương khi tạm giữ, tạm giam và truy lĩnh phần còn lại nếu oan, sai; được công bố công khai và bố trí lại công tác phù hợp nêu oan, sai; được quyền khiếu nại quyết định kỷ luật; quyết định kỷ luật sai quy định phải bị hủy bỏ","Người bị oan, sai không được bố trí lại công tác"],c:2},{id:"vb10-167",s:"CHƯƠNG V - ĐIỀU KHOẢN THI HÀNH",cc:"Khoản 1 Điều 29 Nghị định số 172/2025/NĐ-CP.",gt:"Nghị định này có hiệu lực thi hành kể từ ngày 01/7/2025 - cùng thời điểm hiệu lực của Luật Cán bộ, công chức năm 2025.",mn:"Hiệu lực ND 172: 01/7/2025.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, Nghị định này có hiệu lực thi hành từ thời điểm nào?",o:["Từ ngày 01 tháng 01 năm 2026","Từ ngày 01 tháng 7 năm 2025","Từ ngày 24 tháng 6 năm 2025","Từ ngày 18 tháng 9 năm 2025"],c:1},{id:"vb10-168",s:"CHƯƠNG V - ĐIỀU KHOẢN THI HÀNH",cc:"Khoản 2 Điều 29 Nghị định số 172/2025/NĐ-CP.",gt:"Nghị định bãi bỏ các quy định về xử lý kỷ luật cán bộ, công chức tại Nghị định số 112/2020/NĐ-CP (về xử lý kỷ luật cán bộ, công chức, viên chức) và Nghị định số 71/2023/NĐ-CP (sửa đổi, bổ sung NÐ 112/2020). Lưu ý: chỉ bãi bỏ phân liên quan đến cán bộ, công chức, không bãi bỏ toàn bộ NÐ 112/2020 (phân viên chức vấn còn).",mn:"ĐDãi bộ phân kỷ luật CBCC tại NÐ 112/2020 và NÐ 71/2023.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, văn bản nào sau đây bị bãi bỏ các quy định về xử lý kỷ luật cán bộ, công chức kể từ ngày Nghị định này có hiệu lực?",o:["Nghị định về tuyển dụng, sử dụng và quản lý công chức","Toàn bộ Nghị định số 112/2020/NĐ-CP","Luật Cán bộ, công chức năm 2025","Các quy định về xử lý kỷ luật cán bộ, công chức tại Nghị định số 112/2020/NĐ- CP và Nghị định số 71/2023/NĐ-CP"],c:3},{id:"vb10-169",s:"CHƯƠNG V - ĐIỀU KHOẢN THI HÀNH",cc:"Khoản 1 Điều 28 Nghị định số 172/2025/NĐ- CP.",gt:"Đối với hành vi vi phạm xảy ra trước ngày Nghị định có hiệu lực nhưng xem xét, xử lý sau thì áp dụng quy định của Nghị định này hoặc quy định pháp luật ở thời điểm xảy ra vi phạm nếu có lợi cho người vi phạm - nguyên tắc áp dụng có lợi...62",mn:"Vi phạm trước, xử lý sau: áp dụng ND này hoặc luật cũ nếu có lợi cho người vi phạm.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, đối với hành vi vi phạm xảy ra trước ngày Nghị định có hiệu lực nhưng việc xem xét, xử lý diễn ra sau ngày Nghị định có hiệu lực thì áp dụng quy định nào?",o:["Bắt buộc áp dụng quy định pháp luật tại thời điểm xảy ra vi phạm","Bắt buộc áp dụng quy định của Nghị định này trong mọi trường hợp","Áp dụng quy định của Nghị định này hoặc quy định của pháp luật ở thời điểm xảy ra vi phạm nếu có lợi cho cán bộ, công chức có hành vi vi phạm","Không xử lý vị hành vi xảy ra trước khi Nghị định có hiệu lực"],c:2},{id:"vb10-170",s:"CHƯƠNG V - ĐIỀU KHOẢN THI HÀNH",cc:"Khoản 1 Điều 28 Nghị định số 172/2025/NĐ-CP.",gt:"Đối với các hành vi vi phạm được xem xét, xử lý trước ngày Nghị định có hiệu lực thì tiếp tục áp dụng quy định của pháp luật tại thời điểm xảy ra hành vi vi phạm để xử lý.",mn:"Đã xử lý trước hiệu lực: theo luật tại thời điểm vi phạm. s",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, đối với các hành vi vi phạm được xem xét, xử lý trước ngày Nghị định này có hiệu lực thì áp dụng quy định nào?",o:["Áp dụng quy định của Nghị định này","Tiếp tục áp dụng quy định của pháp luật tại thời điểm xảy ra hành vi vi phạm để xử lý","Hủy bỏ kết quả xử lý và xem xét lại theo Nghị định này","Áp dụng quy định có lợi nhất cho cán bộ, công chức"],c:1},{id:"vb10-171",s:"CHƯƠNG V - ĐIỀU KHOẢN THI HÀNH",cc:"Khoản 2 Điều 28 NVohi định số 1722025°NĐ-CP.",gt:"Hành vi vi phạm pháp luật về xử lý vi phạm hành chính, phòng, chống tham nhũng được áp dụng theo pháp luật chuyên ngành; trường hợp pháp luật chuyên ngành chưa quy định hoặc quy định khác với Nghị định này về cùng một nội dung thì áp dụng theo Nghị định này.",mn:"Vi phạm hành chính, tham nhũng: theo pháp luật chuyên ngành (chưa có/khác ¬ theo ND này).",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, đối với các hành vi vi phạm pháp luật về xử lý vi phạm hành chính, phòng, chống tham nhũng thì hình thức xử lý được áp dụng theo quy định nào?",o:["Theo quy định của pháp luật chuyên ngành; trường hợp pháp luật chuyên ngành chưa quy định hoặc quy định khác với Nghị định này về cùng một nội dung thì áp dụng theo Nghị định này","Chỉ áp dụng theo Nghị định này","Chỉ áp dụng theo pháp luật chuyên ngành trong mọi trường hợp","Không thuộc phạm vi điều chỉnh của pháp luật"],c:0},{id:"vb10-172",s:"CHƯƠNG V - ĐIỀU KHOẢN THI HÀNH",cc:"liêu 30 Nghị định số 172/2025/NI)-CP.",gt:"Chịu rách nhiệm thi hành Nghị định: các Bộ trưởng, Thủ trưởng cơ quan ngang bộ, Thủ trưởng cơ quan thuộc Chính phủ, Chủ tịch Ủy ban nhân dân..63 LÀI LIỆU ÔN CE CÔNG €HUC VIÊN CHỨC FÐI NGUYỄN YONA 09953502H1 tỉnh, thành phố trực thuộc trung ương và các cơ quan, tổ chức, cá nhân có liên quan.",mn:"Thi hành: Bộ trưởng, Thủ trưởng cơ quan ngang bộ, Chủ tịch UBND tỉnh và cơ quan, cá nhân liên quan.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, ai chịu trách nhiệm thi hành Nghị định?",o:["Chỉ Chủ tịch Ủy ban nhân dân cấp tỉnh","Chỉ Bộ trưởng Bộ Nội vụ","Chỉ Thủ tướng Chính phủ","Các Bộ trưởng, Thủ trưởng cơ quan ngang bộ, Thủ trưởng cơ quan thuộc Chính phủ, Chủ tịch Ủy ban nhân dân tỉnh, thành phố trực thuộc trung ương và các cơ quan, tổ chức, cá nhân có liên quan"],c:3},{id:"vb10-173",s:"CHƯƠNG V - ĐIỀU KHOẢN THI HÀNH",cc:"Phún còn cứ ban hònh Nghị định số 1222025 NĐ- CD.",gt:"Nghị định được ban hành căn cứ Luật Tổ chức Chính phủ năm 2025 và Luật Cán bộ, công chức năm 2025 - thể hiện sự đồng bộ với hệ thống pháp luật mới về công vụ.",mn:"Căn cứ: Luật Tổ chức Chính phủ 2025 + Luật CCBCC; 2025.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, căn cứ pháp lý để ban hành Nghị định gồm những văn bản nào?",o:["Luật Thanh tra và Luật Khiếu nại","Luật Cán bộ, công chức năm 2008 và Luật Viên chức năm 2010","Hiến pháp năm 2013 và Luật Tổ chức chính quyền địa phương","Luật Tổ chức Chính phủ năm 2025 và Luật Cán bộ, công chức năm 2025"],c:3},{id:"vb10-174",s:"CHƯƠNG V - ĐIỀU KHOẢN THI HÀNH",cc:"l)iÖu 2Ø về ‡iểu 2U Nghị định vô 122 2025. Ng- C.P.",gt:"Tổng hợp: Nghị định có hiệu lực từ 01/7/2025; bãi bỏ phần xử lý kỷ luật cán bộ, công chức tại NÐ 112/2020 và NÐ 71/2023: áp dụng nguyên tắc có lợi cho người vi phạm với hành vi xảy ra rước nhưng xử lý sau ngày Nghị định có hiệu lực.",mn:"Hiệu lực 01/7/2025 — bãi bỏ phần kỷ luật CBCC ND 11272020 + 71/2023 áp dụng có lợi. Phũn nâng cao ở mức thông hiểu, vận dụng và liên hệ tổng thể toàn bộ Nghị định số 172/2025/NĐ-CP: mối quan hệ giữa kỷ luật đảng - kỷ luật hành chính — trách nhiệm hình sự: phân biệt thời hiệu và thời hạn; logic thang hình thức Rÿ luật: bảo vệ cán bộ dám nghĩ, dám làm: xử lý người đã thôi việc, nghỉ hưu, Câu hỏi và dạáp án trình bày dài, đây đủ ngữ canh.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, phương án nào sau đây phản ánh ĐÚNG về hiệu lực và chuyển tiếp của Nghị định?",o:["Nghị định có hiệu lực từ 01/01/2026 và không bãi bỏ văn bản nào","Nghị định có hiệu lực từ 01/7/2025; bãi bỏ các quy định về xử lý kỷ luật cán bộ, công chức tại Nghị định 112/2020 và Nghị định 71/2023; áp dụng nguyên tắc có lợi cho người vi phạm đối với hành vi xảy ra trước nhưng xử lý sau ngày Nghị định có hiệu lực","Nghị định áp dụng hội tổ cho mọi hành vi đã xử lý trước đó","Nghị định chỉ áp dụng cho viên chức"],c:1},{id:"vb10-175",s:"CHUYÊN ĐỀ NÂNG CAO - TRỌNG TÂM, LIÊN HỆ TỔNG THỂ TOÀN VĂN BẢN (Phần 1)",cc:"Khoản 5 và khoản 6© Điều 2 Nghị định số 172/2025/NĐ-CP.",gt:"Ba loại trách nhiệm độc lập nhưng có liên hệ: kỷ luật đảng dẫn đến phải xử lý kỷ luật hành chính tương xứng trong 30 ngày; kỷ luật hành chính không thay cho truy cứu hình sự; không dùng xử phạt hành chính thay cho kỷ luật hành chính. Một người có thể đồng thời chịu nhiều loại trách nhiệm.",mn:"Đảng.. hành chính (30 ngày, tương xứng); hành chính Z hình sự; xử phạt hành chính Z kỷ luật hành chính.",t:"m",q:"Phân tích mối quan hệ giữa ba loại trách nhiệm khi cán bộ, công chức vi phạm, theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, nhận định nào sau đây là DÙNG nhất?",o:["Chỉ áp dụng một loại trách nhiệm duy nhất cho mỗi hành vi vi phạm","Ba loại trách nhiệm có thể thay thế lẫn nhau tùy trường hợp","Kỷ luật về đảng, kỷ luật hành chính và trách nhiệm hình sự là ba loại trách nhiệm độc lập nhưng có liên hệ: kỷ luật đảng dẫn đến phải xử lý kỷ luật hành chính tương xứng trong 30 ngày; kỷ luật hành chính không thay cho truv cứu hình sự; không dùng xử phạt hành chính thay cho kỷ luật hành chính","Trách nhiệm hình sự luôn loại trừ kỷ luật hành chính và kỷ luật đảng"],c:2},{id:"vb10-176",s:"CHUYÊN ĐỀ NÂNG CAO - TRỌNG TÂM, LIÊN HỆ TỔNG THỂ TOÀN VĂN BẢN (Phần 1)",cc:"Điều 5 Nghị định số I72/2025-NĐ-CP.",gt:"Thời hiệu là khoảng thời gian mà khi hết thì người vi phạm không bị xử lý kỷ luật (5 năm với khiển trách, 10 năm với trường hợp khác), tính từ thời điểm có hành vi vi phạm; thời hạn là khoảng thời gian từ khi phát hiện đến khi có quyết định xử lý kỷ luật (90 ngày, phức tạp 150 ngày).",mn:"Thời hiệu (5/10 năm, từ khi vi phạm) Z thời hạn (90/150 ngày, từ khi phát hiện). „65",t:"m",q:"Phân biệt 'thời hiệu xử lý kỷ luật' và 'thời hạn xử lý kỷ luật' theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, nhận định nào sau đây là DÙNG?",o:["Thời hiệu là khoảng thời gian mà khi hết thì người vi phạm không bị xử lý kỷ luật (5 năm hoặc 10 năm), tính từ thời điểm có hành vi vi phạm; còn thời hạn là khoảng thời gian từ khi phát hiện vi phạm đến khi có quyết định xử lý kỷ luật (90 ngày, phức tạp 150 ngày)","Thời hiệu và thời hạn là hai khái niệm đồng nghĩa","Thời hiệu là 90 ngày, thời hạn là 5 năm hoặc 10 năm","Cả thời hiệu và thời hạn đều tính từ thời điểm phát hiện vi phạm"],c:0},{id:"vb10-177",s:"CHUYÊN ĐỀ NÂNG CAO - TRỌNG TÂM, LIÊN HỆ TỔNG THỂ TOÀN VĂN BẢN (Phần 1)",cc:"Khoan ö Điều 2 Nghị định số 172:2025/NID-CP.",gt:"Khi có kỷ luật về đảng, trong thời hạn 30 ngày kể từ ngày công bố quyết định, cơ quan phải thực hiện quy trình xử lý kỷ luật hành chính (nếu có), bảo đảm hình thức tương xứng với kỷ luật về đảng.",mn:"Kỷ luật đảng -—. 30 ngày xử lý kỷ luật hành chính tương xứng.",t:"m",q:"Một tình huống vận dụng: Công chức A bị kỷ luật về đảng bằng hình thức cảnh cáo. Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, cơ quan phải thực hiện việc gì và trong thời hạn nào?",o:["Cho đến kỳ đánh giá cuối năm mới xử lý","Không phải xử lý kỷ luật hành chính vi đã có kỷ luật đảng","Xử lý kỷ luật hành chính trong thời hạn 90 ngày","Trong thời hạn 30 ngày kể từ ngày công bố quyết định kỷ luật về đảng, cơ quan phải thực hiện quy trình xử lý kỷ luật hành chính (nếu có), bảo đảm hình thức kỷ luật hành chính tương xứng với kỷ luật về đảng"],c:3},{id:"vb10-178",s:"CHUYÊN ĐỀ NÂNG CAO - TRỌNG TÂM, LIÊN HỆ TỔNG THỂ TOÀN VĂN BẢN (Phần 1)",gt:"Cơ chế miễn kỷ luật đối với đề xuất đổi mới, sáng tạo cụ thể hóa chủ trương bảo vệ cán bộ năng động, sáng tạo, dám nghĩ, dám làm vì lợi ích chung (đồng bộ với Điều 34 Luật CBCC 2025): người thực hiện đối mới được cho phép, đúng chủ trương, động cơ trong sáng nhưng có thiệt hại thì được miễn kỷ luật.",mn:"Miễn kỷ luật cho đổi mới = cụ thể hóa bảo vệ cán bộ dám nghĩ, dám làm (gắn Điều 34 Luật CBCC).",t:"m",q:"Liên hệ với Luật Cán bộ, công chức năm 2025, cơ chế 'miễn kỷ luật' đối với đề xuất đổi mới, sáng tạo trong Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức thể hiện chủ trương nào?",o:["Khuyến khích cán bộ, công chức tránh né trách nhiệm","Miễn trách nhiệm cho mọi sai phạm của cán bộ, công chức","Cụ thể hóa chủ trương bảo vệ cán bộ năng động, sáng tạo, dám nghĩ, dám làm vì lợi ích chung: người thực hiện đề xuất đổi mới được cấp có thẩm quyền cho phép, đúng chủ trương, động cơ trong sáng nhưng có thiệt hại thì được miễn kỷ luật","Chỉ áp dụng cho cán bộ lãnh đạo cấp cao"],c:2},{id:"vb10-179",s:"CHUYÊN ĐỀ NÂNG CAO - TRỌNG TÂM, LIÊN HỆ TỔNG THỂ TOÀN VĂN BẢN (Phần 1)",cc:"Các điều 4.0,8.9, 10, 11 Nghị định số 172/2025/NĐ- CĐ...66",gt:"Việc lựa chọn hình thức kỷ luật là sự kết hợp của ba yếu tố: mức độ hậu quả (ít nghiêm trọng/nghiêm trọng/rất nghiêm trọng); lần đầu hay tái phạm; thái độ tiếp thu, khác phục cùng các tình tiết tăng nặng, giảm nhẹ. Ví dụ: lần đầu, ítnghiêm trọng ¬ khiển trách; rất nghiêm trọng nhưng tiếp thu, sửa chữa.. có thể chỉ cách chức thay vì buộc thôi việc.",mn:"Hình thức kỷ luật = mức độ hậu quả + lần đầu/tái phạm + thái độ. tình tiết.",t:"m",q:"Phân tích logic của thang hình thức kỷ luật theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, yếu tố nào quyết định việc lựa chọn hình thức kỷ luật?",o:["Chỉ phụ thuộc vào chức vụ của người vi phạm","Sự kết hợp của ba yếu tố: mức độ hậu quả (ít nghiêm trọng, nghiêm trọng, rất nghiêm trọng); tính chất lần đầu hay tái phạm; và thái độ tiếp thu, khắc phục cùng các tình tiết tăng nặng, giảm nhẹ","Chỉ phụ thuộc vào ý kiến của người đứng đầu","Chỉ phụ thuộc vào số lần vi phạm"],c:1},{id:"vb10-180",s:"CHUYÊN ĐỀ NÂNG CAO - TRỌNG TÂM, LIÊN HỆ TỔNG THỂ TOÀN VĂN BẢN (Phần 1)",cc:"Khoản 2 liÖu ID Nghị định số 172,2025/NĐ-CP.",gt:"Công chức lãnh đạo vi phạm lần đầu gây hậu quả rất nghiêm trọng nhưng chưa đến mức buộc thôi việc, có thái độ tiếp thu, sửa chữa, chủ động khác phục hậu quả và thuộc trường hợp giảm nhẹ thì bị cách chức (không phải buộc thôi việc). Thái độ tiếp thu, khắc phục là yếu tố quyết định mức nhẹ hơn.",mn:"Lãnh đạo, rất nghiêm trọng nhưng tiếp thu, khác phục › cách chức (không buộc thôi việc).",t:"m",q:"Một tình huống vận dụng tổng hợp: Công chức B (giữ chức vụ lãnh đạo) vi phạm lần đầu gây hậu quả rất nghiêm trọng nhưng có thái độ tiếp thu, chủ động khác phục hậu quả, chưa đến mức buộc thôi việc. Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, hình thức kỷ luật phù hợp nhất là gì?",o:["Cách chức","Khiển trách","Cảnh cáo","Buộc thôi việc"],c:0},{id:"vb10-181",s:"CHUYÊN ĐỀ NÂNG CAO - TRỌNG TÂM, LIÊN HỆ TỔNG THỂ TOÀN VĂN BẢN (Phần 1)",cc:"Khoản 2 Điều 11 Nghị định số 172/2025-NĐ-CP.",gt:"Cùng là vi phạm lần đầu rất nghiêm trọng, những công chức C không tiếp thu, không khác phục hậu quả và thuộc trường hợp tăng nặng thì bị buộc thôi việc (nặng hơn so với công chức B có thái độ tiếp thu chỉ bị cách chức). Đây là mình họa cho vai trò của thái độ và tình tiết tăng nặng/giảm nhẹ.",mn:"Rất nghiêm trọng + không tiếp thu, tăng nặng ¬ buộc thôi việc.",t:"m",q:"Một tình huống vận dụng tổng hợp: Công chức C (giữ chức vụ lãnh đạo) vi phạm lần đầu gây hậu quả rất nghiêm trọng, KHÔNG có thái độ tiếp thu, không khác phục hậu quả và thuộc trường hợp tăng nặng. Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, hình thức kỷ luật phù hợp nhất là gì?",o:["Buộc thôi việc","Cách chức","Cảnh cáo","Khiển trách"],c:0},{id:"vb10-182",s:"CHUYÊN ĐỀ NÂNG CAO - TRỌNG TÂM, LIÊN HỆ TỔNG THỂ TOÀN VĂN BẢN (Phần 1)",cc:"Khoản 2 liều I và Mục 3 Chương 1H Nghị định số 172/2025/N1)-CP.",gt:"Việc mở rộng đối tượng đến người đã thôi việc, nghỉ hưu nhằm bảo đảm nguyên tắc 'không có vùng cấm, không có hạ cánh an toàn”, xử lý đến cùng các hành vi vi phạm trong thời gian công tác, giữ nghiêm kỷ luật, kỷ cương và phòng, chống tham nhũng, tiêu cực. ® Miẹo nhớ: Xử lý người đã nghỉ: không 'vùng cấm), không 'hạ cánh an toàn.",t:"m",q:"Liên hệ tổng thể, vì sao Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức quy định mở rộng đối tượng áp dụng đến cả người đã thôi việc, nghỉ hưu?",o:["Nhằm hạn chế quyền lợi hưu trí của người đã nghỉ","Nhằm tăng thêm thủ tục hành chính „67","Nhằm bảo đảm nguyên tắc 'không có vùng cấm, không có hạ cánh an toàn', xử lý đến cùng các hành vi vi phạm trong thời gian công tác, giữ nghiêm kỷ luật, kỷ cương và phòng, chống tham nhũng, tiêu cực","Nhằm thay thế cơ chế truy cứu trách nhiệm hình sự"],c:2},{id:"vb10-183",s:"CHUYÊN ĐỀ NÂNG CAO - TRỌNG TÂM, LIÊN HỆ TỔNG THỂ TOÀN VĂN BẢN (Phần 1)",gt:"Hình thức xóa tư cách chức vụ, chức danh đã đảm nhiệm tước bỏ danh nghĩa chức vụ, chức danh mà người đó đã giữ trong thời gian công tác, gắn với hệ quả pháp lý tương ứng - thể hiện việc xử lý nghiêm vi phạm dù người vi phạm đã rời công vụ.",mn:"Xóa tư cách chức vụ: tước danh nghĩa chức vụ đã giữ + hệ quả pháp lý tương ứng.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, đối với người đã thôi việc, nghỉ hưu, hình thức kỷ luật đặc thù 'xóa tư cách chức vụ, chức danh đã đảm nhiệm' có ý nghĩa gì?",o:["Buộc người đã nghỉ hưu quay lại làm việc","Tước bö danh nghĩa chức vụ, chức danh mà người đó đã giữ trong thời gian công tác, gắn với hệ quả pháp lý tương ứng, thể hiện việc xử lý nghiêm vi phạm dù người vi phạm đã rời công vụ","Tước toàn bộ lương hưu của người vi phạm","Chỉ mang tính hình thức, không có hệ quả pháp lý"],c:1},{id:"vb10-184",s:"CHUYÊN ĐỀ NÂNG CAO - TRỌNG TÂM, LIÊN HỆ TỔNG THỂ TOÀN VĂN BẢN (Phần 1)",cc:"Điểm c khoản 3 Điều 43 Luật Cán bộ, công chức năm 2025: Điều 22 Nghị định số 172/2025/NĐ-CP.",gt:"Ông D dù đã nghỉ hưu vẫn bị xem xét xử lý kỷ luật với hình thức khiển trách, cảnh cáo hoặc xóa tư cách chức vụ, chức danh đã đảm nhiệm tùy mức độ: nếu đến mức bị xử lý hình sự thì vẫn bị truy cứu trách nhiệm hình sự. „68 LÀI LIỆU ÔN CE CÔNG €HUC VIÊN CHỨC FÐI NGUYỄN YONA 09953502H1",mn:"Nghỉ hưu vẫn xử lý: khiển trách:cảnh cáo¿xóa tư cách + hình sự (nếu cÓ).",t:"m",q:"Một tình huống vận dụng: Ông D đã nghỉ hưu, sau đó bị phát hiện có hành vi vi phạm nghiêm trọng trong thời gian còn công tác và giữ chức vụ. Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, ông D có thể bị xử lý như thế nào?",o:["Bị buộc thôi việc","Không bị xử lý vi đã nghỉ hưu","Chỉ bị nhắc nhở, rút kinh nghiệm","Bị xem xét xử lý kỷ luật với hình thức khiển trách, cảnh cáo hoặc xóa tư cách chức vụ, chức danh đã đảm nhiệm tùy theo tính chất, mức độ vi phạm; nếu đến mức bị xử lý hình sự thì vẫn bị truy cứu trách nhiệm hình sự"],c:3},{id:"vb10-185",s:"CHUYÊN ĐỀ NÂNG CAO - TRỌNG TÂM, LIÊN HỆ TỔNG THỂ TOÀN VĂN BẢN (Phần 1)",cc:"Điều Jˆ và Điều 1# Nghị định vò 1732025. NĐD-C.Đ.",gt:"Họp kiểm điểm nhằm làm rõ hành vi vi phạm, để người vi phạm tự kiểm điểm, nhận trách nhiệm (mang tính phát hiện, làm rõ, không quyết định hình thức) nên không bỏ phiếu; Hội đồng kỷ luật là cơ quan tư vấn về hình thức kỷ luật nên cần bỏ phiếu kín để kiến nghị khách quan.",mn:"Kiểm điểm = làm rõ, nhận trách nhiệm (không bỏ phiếu); Hội đồng = tư vấn hình thức (bỏ phiếu kín).",t:"m",q:"Phân tích vì sao tại cuộc họp kiểm điểm không tiến hành bỏ phiếu, còn tại Hội đồng kỷ luật mới bỏ phiếu kín, theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức?",o:["Vì họp kiểm điểm không quan trọng bảng họp Hội đồng","Họp kiểm điểm nhằm làm rõ hành vi vi phạm và để người vi phạm tự kiểm điểm, nhận trách nhiệm (mang tính phát hiện, làm rõ); con Hội đồng kỷ luật là cơ quan tư vấn về hình thức kỷ luật nên cần bỏ phiếu kín để kiến nghị khách quan","Vi người vi phạm không được tham gia họp kiểm điểm","Vì Hội đồng kỷ luật do tập thể cơ quan bầu"],c:1},{id:"vb10-186",s:"CHUYÊN ĐỀ NÂNG CAO - TRỌNG TÂM, LIÊN HỆ TỔNG THỂ TOÀN VĂN BẢN (Phần 1)",cc:"Rhuan ^ Điếu ở Nghị định số 122 A003 NĐ-C.Đ.",gt:"Khi có từ 02 hành vi vi phạm trở lên trong cùng thời điểm xem xét, xem xét, kết luận về từng hành vi và quyết định chung bằng một hình thức kỷ luật cao nhất tương ứng - ở đây là cảnh cáo (cao hơn khiển trách).",mn:"Nhiều hành vi. 1 quyết định, lấy hình thức cao nhất (cảnh cáo).",t:"m",q:"Một tình huống vận dụng: Công chức E có 02 hành vi vi phạm được xem xét trong cùng một thời điểm: một hành vi đến mức khiển trách, một hành vi đến mức cảnh cáo. Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, công chức E bị xử lý như thế nào?",o:["Chỉ bị xử lý hành vi nhẹ hơn là khiển trách","Bị xử lý cộng dồn cả khiển trách và cảnh cáo","Xem xét, kết luận về từng hành vi vi phạm và quyết định chung bằng một hình thức kỷ luật cao nhất tương ứng, tức là cảnh cáo","Bị xử lý hai lần bằng hai quyết định riêng"],c:2},{id:"vb10-187",s:"CHUYÊN ĐỀ NÂNG CAO - TRỌNG TÂM, LIÊN HỆ TỔNG THỂ TOÀN VĂN BẢN (Phần 1)",cc:"Các điều 1,2, 4,.25, 206, 27 Nghị định số 172/2025/M)0)-C P.",gt:"Nghị định căn bằng hai vêu cấu: xử lý nghiêm (mở rộng đối tượng, không vùng cấm, tăng nặng với hành vi đối phó, che giấu) và bảo vệ quyền lợi (miễn, giảm nhẹ với người làm đúng, dám đổi mới; 50% lương khi tạm giam; phục hồi danh dự, bố trí lại công tác nếu oan, sai; quyền khiếu nại).",mn:"Vừa xử lý nghiêm (không vùng cấm) vừa bảo vệ quyền lợi (miễn/giảm, oan sai, khiếu nại).",t:"m",q:"Liên hệ tổng thể, Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức cần bằng giữa 'xử lý nghiêm vi phạm' và 'bảo vệ quyền lợi cán bộ, công chức' như thế nào?",o:["Hai mục tiêu này mâu thuẫn, không thể cùng đạt được","Chỉ tập trung xử lý nghiêm, không bảo vệ quyền lợi","Chỉ bảo vệ quyền lợi mà buông lỏng xử lý vi phạm","Một mặt xử lý nghiêm (mở rộng đối tượng, không vùng cấm, tăng nặng với hành vi đối phó, che giấu); mặt khác bảo vệ quyền lợi (miễn, giảm nhẹ với người làm đúng, dám đổi mới; hưởng 50% lương khi tạm giam; phục hồi danh dự, bố trí lại công tác nếu oan, sai; quyền khiếu nại)"],c:3},{id:"vb10-188",s:"CHUYÊN ĐỀ NÂNG CAO - TRỌNG TÂM, LIÊN HỆ TỔNG THỂ TOÀN VĂN BẢN (Phần 1)",cc:"Điểm b khoản 3 Điều 2 Nghị định số 172/2025/NĐ-CP.",gt:"Đang thi hành khiển trách mà vi phạm tiếp ở mức nặng hơn (cảnh cáo) thì áp dụng hình thức kỷ luật nặng hơn một mức so với hình thức áp dụng đối với hành vi vi phạm mới (cảnh cáo) - tức mức cao hơn cảnh cáo. (Khác với trường hợp hành vi mới nhẹ hơn/bằng thì tính nặng hơn 1 mức so với hình thức đang thi hành.)",mn:"Dang khiển trách, vi phạm mới nặng hơn (cảnh cáo) › nặng hơn 1 mức so với hành vi mới.",t:"m",q:"Một tình huống vận dụng: Công chức F đang thi hành quyết định kỷ luật khiển trách, trong thời gian đó lại có hành vi vi phạm mới đến mức bị cảnh cáo (nặng hơn). Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, hình thức kỷ luật áp dụng đối với công chức E là gì?",o:["Áp dụng hình thức kỷ luật nặng hơn một mức so với hình thức kỷ luật áp dụng đối với hành vi vi phạm mới (cảnh cáo), tức là mức cao hơn cảnh cáo","Giữ nguyên hình thức khiển trách đang thi hành","Áp dụng hình thức cảnh cáo của hành vi mới","Cộng dồn khiển trách và cảnh cáo"],c:0},{id:"vb10-189",s:"CHUYÊN ĐỀ NÂNG CAO - TRỌNG TÂM, LIÊN HỆ TỔNG THỂ TOÀN VĂN BẢN (Phần 1)",cc:"Khoản 1Í Điều 2 Nghị định số 172/2025/NĐ- CP.",gt:"Quy định này nhằm bảo đảm nguyên tắc khách quan, công bằng, vô tư trong xử lý kỷ luật, tránh xung đột lợi ích và bảo vệ tính nghiêm minh của quá trình xử lý.",mn:"Không cử người thân: tránh xung đột lợi ích, bảo đảm khách quan.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, vì sao quy định không cử người thân thích hoặc người có liên quan làm thành viên Hội đồng kỷ luật, người chủ trì kiểm điểm?",o:["Nhằm rút ngắn thời gian xử lý kỷ luật","Nhằm giảm số lượng người tham gia Hội đồng kỷ luật","Nhằm bảo đảm nguyên tắc khách quan, công bằng, vô tư trong xử lý kỷ luật, tránh xung đột lợi ích và bảo vệ tính nghiêm minh của quá trình xử lý","Nhằm bảo vệ người vi phạm khỏi bị xử lý nặng"],c:2},{id:"vb10-190",s:"CHUYÊN ĐỀ NÂNG CAO - TRỌNG TÂM, LIÊN HỆ TỔNG THỂ TOÀN VĂN BẢN (Phần 1)",cc:"Nhonn Ì Điều 24 và Mục 3 Chương HE Nghị định số (72 2005 NĐ-CP.",gt:"Công chức G đến tuổi nghỉ hưu trong thời gian bị điều tra, tạm giam thì vẫn được giải quyết thủ tục hưởng chế độ hưu trí; việc xử lý hành vi vi phạm (nếu có) tiếp tục theo quy định đối với người đã nghỉ hưu.",mn:"Đến tuổi hưu khi đang bị điều tra, vẫn giải quyết hưu trí; xử lý vi phạm theo diện người đã nghỉ.",t:"m",q:"Một tình huống vận dụng: Công chức G bị tạm giam phục vụ điều tra. Trong thời gian đó công chức G đến tuổi nghỉ hưu. Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, công chức G được giải quyết như thế nào?",o:["Tạm dừng giải quyết hưu trí cho đến khi có kết luận điều tra „70 LÀI LIỆU ÔN CE CÔNG €HUC VIÊN CHỨC FÐI NGUYỄN YONA 09953502H1","Vẫn được thực hiện giải quyết thủ tục hưởng chế độ hưu trí; việc xử lý hành vi vi phạm (nếu có) được tiếp tục theo quy định đối với người đã nghỉ hưu","Không được hưởng chế độ hưu trí","Bị buộc thôi việc trước khi giải quyết hưu trí"],c:1},{id:"vb10-191",s:"CHUYÊN ĐỀ NÂNG CAO - TRỌNG TÂM, LIÊN HỆ TỔNG THỂ TOÀN VĂN BẢN (Phần 1)",cc:"Điện b khoón © Điều 5 Auhi định và 1752322025730) CP.",gt:"Thời gian điều tra, truy tố, xét xử không tính vào thời hiệu, thời hạn vị trong thời gian này việc xử lý kỷ luật hành chính bị tạm dụng để chờ kết quả tố tụng; nêu tính vào thời hiệu, thời hạn sẽ làm mất khả năng xử lý kỷ luật đối với hành vi vi phạm sau khi có kết quả tố tụng.",mn:"Không tính thời gian tố tụng: đề không 'mất' quyền xử lý kỷ luật sau khi có kết quả.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, vì sao thời gian điều tra, truy tố, xét xử theo thủ tục tố tụng hình sự không được tính vào thời hiệu, thời hạn xử lý kỷ luật?",o:["Vì cơ quan tố tụng đã thay cơ quan quản lý xử lý kỷ luật","Vì thời gian tố tụng không liên quan đến hành vi vi phạm","Vi người vi phạm không phải chịu trách nhiệm trong thời gian tố tụng","Vị trong thời gian này việc xử lý kỷ luật hành chính bị tạm dụng để chờ kết quả tố tụng; nếu tính vào thời hiệu, thời hạn sẽ làm mất khả năng xử lý kỷ luật đối với hành vi vi phạm sau khi có kết quả tố tụng"],c:3},{id:"vb10-192",s:"CHUYÊN ĐỀ NÂNG CAO - TRỌNG TÂM, LIÊN HỆ TỔNG THỂ TOÀN VĂN BẢN (Phần 1)",cc:"J)iều © Nghị định số 172.205 N12-C P: Địcn t5. Điều 36 Í uạt Cán bộ, công chức nam 2035,",gt:"Các hình thức kỷ luật trong Nghị định thống nhất hoàn toàn với Luật CBCGC 2025: cán bộ có khiển trách, cảnh cáo, cách chức, bãi nhiệm; công chức có khiển trách, cảnh cáo, cách chức, buộc thôi việc. Nghị định cụ thể hóa điều kiện áp dụng từng hình thức..7",mn:"Hình thức kỷ luật ND 172 = Luật CBCC, 2025 (cán bộ: bãi nhiệm; công chức: buộc thôi việc).",t:"m",q:"Liên hệ với Luật Cán bộ, công chức năm 2025, các hình thức kỷ luật trong Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức có sự thống nhất nào?",o:["Thống nhất hoàn toàn với Luật: cán bộ có khiển trách, cảnh cáo, cách chức, bãi nhiệm; công chức có khiển trách, cảnh cáo, cách chức, buộc thôi việc; Nghị định cụ thể hóa điều kiện áp dụng từng hình thức","Khác với Luật, Nghị định bổ sung thêm hình thức hạ bậc lương","Nghị định chỉ quy định hình thức kỷ luật cho công chức","Nghị định bổ hình thức bãi nhiệm đối với cán bộ"],c:0},{id:"vb10-193",s:"CHUYÊN ĐỀ NÂNG CAO - TRỌNG TÂM, LIÊN HỆ TỔNG THỂ TOÀN VĂN BẢN (Phần 1)",cc:"Diên d khoản 4 Điều 5 và khoản 3 Điều 1] Nghị định số 172/2025/NĐ- cP.",gt:"Hành vi sử dụng văn bằng gia thuộc trường hợp không áp dụng thời hiệu (xử lý bắt kể thời gian) và việc dùng văn bằng giả để được tuyển dụng bị áp dụng hình thức buộc thôi việc.",mn:"Văn bằng giả tuyển dụng: không thời hiệu + buộc thôi việc.",t:"m",q:"Một tình huống vận dụng: Công chức H sử dụng văn bằng giả để được tuyển dụng (phát hiện sau nhiều năm). Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, việc xử lý đối với công chức H có bí giới hạn bởi thời hiệu không và bị áp dụng hình thức gì?",o:["Không bị giới hạn bởi thời hiệu (vị sử dụng văn bằng gia thuộc trường hợp không áp dụng thời hiệu) và bị áp dụng hình thức buộc thôi việc","Bị giới hạn bởi thời hiệu 05 năm và chỉ bị khiển trách","Bị giới hạn bởi thời hiệu 10 năm và bị cảnh cáo","Không bị xử lý vi đã qua lâu"],c:0},{id:"vb10-194",s:"CHUYÊN ĐỀ NÂNG CAO - TRỌNG TÂM, LIÊN HỆ TỔNG THỂ TOÀN VĂN BẢN (Phần 1)",cc:"Điều 16 Nghị định số 172/2005/NĐ-CP.",gt:"Việc bỏ bước kiểm điểm và/hoặc Hội đồng kỷ luật phản ánh nguyên tắc xử lý kịp thời, tránh trùng lặp thủ tục khi đã có kết luận rõ ràng (đã có kết luận của cơ quan có thẩm quyền, đã có bản án, đã có kỷ luật về đảng); các trường hợp này sử dụng kết luận sẵn có mà không phải điều tra, xác minh lại.",mn:"Bỏ bước thủ tục khi đã có kết luận/bản án/kỷ luật đảng, tránh trùng lặp, xử lý kỊp thời.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, các trường hợp được bỏ bước họp kiểm điểm và/hoặc bỏ bước thành lập Hội đồng kỷ luật phản ánh nguyên tắc nào?",o:["Nguyên tắc xử lý kỷ luật không cần căn cứ","Nguyên tắc rút gọn mọi quy trình để giảm thủ tục","Nguyên tắc bỏ qua quyền tự kiểm điểm của công chức","Nguyên tắc bảo đảm xử lý kịp thời, tránh trùng lặp thủ tục khi đã có kết luận rõ ràng (như đã có kết luận của cơ quan có thẩm quyền, đã có bản án, đã có kỷ luật về đảng); các trường hợp này được sử dụng kết luận sẵn có mà không phải điều tra, xác minh lại"],c:3},{id:"vb10-195",s:"CHUYÊN ĐỀ NÂNG CAO - TRỌNG TÂM, LIÊN HỆ TỔNG THỂ TOÀN VĂN BẢN (Phần 1)",cc:"Khoản 4 liệu 25 và liệu 27 Nghị định số 172/2025,N1)-CP.",gt:"Công chức K có quyền khiếu nại quyết định kỷ luật theo pháp luật về khiếu nại; nếu cơ quan giải quyết khiếu nại kết luận việc xử lý không đúng quy định (về hình thức, trình tự, thủ tục, thẩm quyền) thì quyết định kỷ luật bị hủy bỏ và xem xét xử lý lại đúng quy định.",mn:"Bảo vệ quyền lợi: khiếu nại -› nếu sai quy định thì hủy bỏ, làm lại.",t:"m",q:"Một tình huống vận dụng: Công chức K bị xử lý kỷ luật nhưng cho rằng quyết định kỷ luật không đúng quy định. Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, công chức K có những cơ chế nào để bảo vệ quyền lợi?",o:["Không có cơ chế nào để bảo vệ quyền lợi","Có quyền khiếu nại quyết định kỷ luật theo pháp luật về khiếu nại; nếu cơ quan giải quyết khiếu nại kết luận việc xử lý không đúng quy định thì quyết định kỷ luật bị hủy bỏ và xem xét xử lý lại đúng quy định","Chỉ có thể chấp hành quyết định kỷ luật ¡172","Phải khởi kiện ngày ra Tòa án mà không được khiếu nại"],c:1},{id:"vb10-196",s:"CHUYÊN ĐỀ NÂNG CAO - TRỌNG TÂM, LIÊN HỆ TỔNG THỂ TOÀN VĂN BẢN (Phần 1)",gt:"Điểm mới nội bật: Nghị định quy định riêng về xử lý kỷ luật cán bộ, công chức (đồng bộ với Luật CBCC 2025), tách khỏi viên chức (trước đây gộp chung tài NÐ 112/2020); gắn với mô hình tổ chức bộ máy mới và chế độ công vụ thống nhất, liên thông.",mn:"Điệêm mới: nghị định riêng cho CBCC (tách khỏi viên chức), đồng bộ Luật CBCC 2025.",t:"m",q:"Liên hệ tổng thể, đầu là điểm mới nội bật nhất của Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức so với quy định trước đây (tách riêng xử lý kỷ luật cán bộ, công chức khỏi viên chức)?",o:["Nghị định bổ hoàn toàn các hình thức kỷ luật","Nghị định gộp chung việc xử lý kỷ luật cán bộ, công chức và viên chức","Nghị định quy định riêng về xử lý kỷ luật cán bộ, công chức (đồng bộ với Luật Cán bộ, công chức năm 2025), không gộp chung với viên chức như trước; gắn với mô hình tổ chức bộ máy mới và chế độ công vụ thống nhất, liên thông","Nghị định chỉ áp dụng cho công chức cấp xã"],c:2},{id:"vb10-197",s:"CHUYÊN ĐỀ NÂNG CAO - TRỌNG TÂM, LIÊN HỆ TỔNG THỂ TOÀN VĂN BẢN (Phần 1)",cc:"Toàn văn Nghị định số 172/2025/NĐ-CP.",gt:"Tinh thần của Nghị định: khách quan, công bằng, nghiêm minh, đúng thẩm quyền, trình tự, thủ tục; phân loại hình thức theo mức độ vi phạm và thái độ: tương xứng với kỷ luật đảng, không thay thế trách nhiệm hình sự; mở rộng đến người đã nghỉ hưu; đồng thời bảo vệ người làm đúng, dám đổi mới và bảo đảm quyền khiếu nại, phục hồi quyền lợi khi oan, sai. 1.73 LÀI LIỆU ÔN CE CÔNG €HUC VIÊN CHỨC FÐI NGUYỄN YONA 09953502H1",mn:"Nghiêm minh, đúng quy trình — phân loại theo mức độ — không vùng cấm - bảo vệ người làm đúng — phục hồi oan sai. 74 Phầũn nâng cao tiếp theo, tập trung vận dụng tổng hợp và phân biệt các trường hợp đề nhâm của Nghị định số 172/2025/NĐ-CP: chưa xem xét -— loại trừ — miền - giảm nhẹ = tăng ngng: thẩm quyền xử lý Kỷ luật trong tình huống cụ thể; tái phạm và hiệu lực quyết định; quy trình Hội đồng Rv luật. Cầu hội và đáp án trình bày đại, đầy đủ ngữ cảnh.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, phương án nào sau đây khái quát ĐÚNG và ĐẦY ĐỦ nhất tinh thần của Nghị định?",o:["Xử lý kỷ luật không cần theo trình tự, thủ tục","Xử lý kỷ luật chỉ nhằm trừng phạt mọi vi phạm bằng hình thức nặng nhất","Xử lý kỷ luật tùy thuộc hoàn toàn vào ý chí của người đứng đầu","Xử lý kỷ luật khách quan, công bằng, nghiêm minh, đúng thẩm quyền, trình tự, thủ tục; phân loại hình thức theo mức độ vi phạm và thái độ; bảo đảm tương xứng với kỷ luật đảng và không thay thế trách nhiệm hình sự; mở rộng đến người đã nghỉ hưu; đồng thời bảo vệ người làm đúng, dám đổi mới và bảo đảm quyền khiếu nại, phục hồi quyền lợi khi oan, sai"],c:3},{id:"vb10-198",s:"CHUYÊN ĐỀ NÂNG CAO - TRỌNG TÂM, LIÊN HỆ TỔNG THỂ TOÀN VĂN BẢN (Phần 2)",cc:"liệu 3 và Điều 4 Nghị định số 1722025/NDĐ- CP.",gt:"Chưa xem xét xử lý kỷ luật là tạm hoãn việc xem xét trong một thời gian (đang điều trị bệnh hiểm nghèo, nuôi con dưới 12 tháng, đang bị khởi tố, tạm giữ, tạm giam) rồi vẫn xem xét sau; miễn kỷ luật là không áp dụng hình thức kỷ luật đối với hành vi vi phạm (mất năng lực hành vi dân sự khi vì phạm, bất khả kháng, đổi mới được cho phép, đã qua đời...).",mn:"Chưa xem xét = hoãn (xử lý sau); miễn kỷ luật = không áp dụng hình thức kỷ luật.",t:"m",q:"Phân biệt 'chưa xem xét xử lý kỷ luật' và 'miễn kỷ luật' theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, nhận định nào sau đây là DÙNG?",o:["Chưa xem xét xử lý kỷ luật là tạm hoãn việc xem xét trong một thời gian (như đang điều trị bệnh hiểm nghèo, nuôi con dưới 12 tháng, đang bị khởi tố) rồi vẫn xem xét sau; con miễn kỷ luật là không áp dụng hình thức kỷ luật đối với hành vi vi phạm (như mất năng lực hành vi dân sự khi vi phạm, bất khả kháng, đổi mới được cho phép)","Hai trường hợp này hoàn toàn giống nhau về hệ quả","Chưa xem xét là không bao giờ xử lý; miễn kỷ luật là hoãn xử lý","Cả hai đều dẫn đến chấm dứt hoàn toàn việc xử lý kỷ luật"],c:0},{id:"vb10-199",s:"CHUYÊN ĐỀ NÂNG CAO - TRỌNG TÂM, LIÊN HỆ TỔNG THỂ TOÀN VĂN BẢN (Phần 2)",gt:"Loại trừ kỷ luật được thực hiện theo quy định của Bộ luật Hình sự và các quy định pháp luật khác có liên quan; miễn kỷ luật áp dụng khi vi phạm có một hoặc một số tình tiết cụ thể được Nghị định liệt kề (mất năng lực hành vi dân sự khi vi phạm, bất khả kháng, đổi mới được cho phép, đã qua đời...).",mn:"Loại trừ: theo Bộ luật Hình sự; miễn: theo tình tiết cụ thể Nghị định liệt kế. u75 LÀI LIỆU ÔN CE CÔNG €HUC VIÊN CHỨC FÐI NGUYỄN YONA 09953502H1",t:"m",q:"Phân biệt 'loại trừ kỷ luật' và 'miễn kỷ luật' theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, nhận định nào sau đây là DÙNG?",o:["Loại trừ kỷ luật do người đứng đầu tự quyết định","Loại trừ và miễn kỷ luật là hai khái niệm đồng nghĩa","Loại trừ kỷ luật được thực hiện theo quy định của Bộ luật Hình sự và các quy định pháp luật khác có liên quan; con miễn kỷ luật áp dụng khi vi phạm có một hoặc một số tình tiết cụ thể được Nghị định liệt kề (mất năng lực hành vi dân sự, bất khả kháng, đổi mới được cho phép...)","Miễn kỷ luật chỉ áp dụng cho cán bộ lãnh đạo"],c:2},{id:"vb10-200",s:"CHUYÊN ĐỀ NÂNG CAO - TRỌNG TÂM, LIÊN HỆ TỔNG THỂ TOÀN VĂN BẢN (Phần 2)",cc:"khoản 3 và khoản 3 Điều 4 Nghị định số 172. 2025/NĐ-CP.",gt:"Công chức M chủ động báo cáo, tự giác nhận trách nhiệm, nộp lại tài sản, khắc phục hậu quả. giảm nhẹ mức kỷ luật; công chức N quanh co, đối phó, cản trở kiểm tra. tăng nặng mức kỷ luật.",mn:"Tự giác, khắc phục.. giảm nhẹ; đối phó, cản trở. tăng nặng.",t:"m",q:"Một tình huống vận dụng: Công chức M chủ động báo cáo vi phạm, tự giác nhận trách nhiệm, tự nguyện nộp lại tài sản và khắc phục hậu quả. Đồng thời, trong vụ việc còn có công chức Ñ quanh co, đối phó, cản trở quá trình kiểm tra. Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, hai công chức này được xem xét tình tiết như thế nào?",o:["Cả hai đều được giảm nhẹ mức kỷ luật","Công chức M được xem xét tình tiết giảm nhẹ mức kỷ luật; công chức Ñ bị xem xét tình tiết tăng nặng mức kỷ luật","Cả hai đều bị tăng nặng mức kỷ luật","Tình tiết tăng nặng, giảm nhẹ không ảnh hưởng đến mức kỷ luật"],c:1},{id:"vb10-201",s:"CHUYÊN ĐỀ NÂNG CAO - TRỌNG TÂM, LIÊN HỆ TỔNG THỂ TOÀN VĂN BẢN (Phần 2)",cc:"tiệm b khoản 3 Điều 1Ở và khoản 2 Diện 21 Nghị dùnh số E1 20025/N‡}: cP.",gt:"Công chức bị lòa án kết án về tội tham nhũng (bản án có hiệu lực) thì không phải họp kiểm điểm, không phải thành lập Hội đồng kỷ luật; trong thời hạn 15 ngày làm việc kể từ ngày nhận được bản án có hiệu lực, cập có thẩm quyền ra quyết định buộc thôi việc.",mn:"Bị kết án tham nhũng: bỏ kiểm điểm + hội đồng.. 15 ngày ra quyết định buộc thôi việc.",t:"m",q:"Một tình huống vận dụng tổng hợp: Công chức P (không giữ chức vụ) bị Tòa án kết án phạt tù về tội tham nhũng, bản án đã có hiệu lực pháp luật. Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, việc xử lý kỷ luật đối với P được thực hiện như thế nào?",o:["Không bị xử lý kỷ luật hành chính vi đã bị xử lý hình sự","Phải tổ chức đầy đủ họp kiểm điểm và Hội đồng kỷ luật trước khi quyết định","Chỉ bị cảnh cáo vi không giữ chức vụ","Không phải tổ chức họp kiểm điểm và không phải thành lập Hội đồng kỷ luật; trong thời hạn 15 ngày làm việc kể từ ngày nhận được bản án có hiệu lực, cấp có thẩm quyền ra quyết định buộc thôi việc"],c:3},{id:"vb10-202",s:"CHUYÊN ĐỀ NÂNG CAO - TRỌNG TÂM, LIÊN HỆ TỔNG THỂ TOÀN VĂN BẢN (Phần 2)",cc:"Khoản 10 Điều 2 Nghị định số 172/2025/NĐ-CP.",gt:"Cơ quan, tổ chức, đơn vị mới thực hiện xem xét xử lý kỷ luật và áp dụng hình thức tương ứng với vị trí Q hiện đang đảm nhiệm; cơ quan cử phối hợp, cung cấp toàn bộ hồ sơ liên quan.",mn:"Vi phạm ở cơ quan cử, phát hiện sau khi điều động: cơ quan mới xử lý.",t:"m",q:"Một tình huống vận dụng: Công chức Q được điều động (chuyển hắn) sang cơ quan mới, sau đó cơ quan mới phát hiện Q có hành vi vi phạm từ thời gian công tác ở cơ quan cử, vẫn còn trong thời hiệu. Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, ai xử lý kỷ luật Q?",o:["Cơ quan cử phải xử lý vi vi phạm xảy ra tại cơ quan cử","Cơ quan, tổ chức, đơn vị mới thực hiện xem xét xử lý kỷ luật và áp dụng hình thức tương ứng với vị trí Q hiện đang đảm nhiệm; cơ quan cử có trách nhiệm phối hợp, cung cấp toàn bộ hồ sơ liên quan","Không xử lý vi Q đã chuyển công tác","Cơ quan quản lý cấp trên xử lý trực tiếp..76"],c:1},{id:"vb10-203",s:"CHUYÊN ĐỀ NÂNG CAO - TRỌNG TÂM, LIÊN HỆ TỔNG THỂ TOÀN VĂN BẢN (Phần 2)",cc:"Khoản 8 Điều 2 Nghị định số 172/2025/NĐ-CP.",gt:"R vi phạm lại chính hành vi đã bị kỷ luật (ngày 01/8/2026) trong thời hạn 12 tháng kể từ ngày quyết định kỷ luật có hiệu lực (01/3/2026) nền được xác định là tái phạm. Tái phạm khiển trách sẽ bị nâng lên cảnh cáo.",mn:"Vi phạm lại trong 12 tháng, tái phạm.",t:"m",q:"Một tình huống vận dụng: Công chức R bị kỷ luật khiển trách, quyết định có hiệu lực ngay 01/3/2026. Đến ngày 01/8/2026, R lại vi phạm chính hành vi đã bị kỷ luật. Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, hành vi vi phạm mới của R được xác định như thế nào?",o:["Không phải tái phạm vi là hành vi khác","Không phải tái phạm vi đã qua 03 tháng","Được xác định là tái phạm, vì R vi phạm lại hành vi đã bị kỷ luật trong thời hạn 12 tháng kể từ ngày quyết định kỷ luật có hiệu lực","Là vi phạm lần đầu"],c:2},{id:"vb10-204",s:"CHUYÊN ĐỀ NÂNG CAO - TRỌNG TÂM, LIÊN HỆ TỔNG THỂ TOÀN VĂN BẢN (Phần 2)",gt:"Quyết định kỷ luật có hiệu lực 12 tháng: trong thời gian này nếu không tiếp tục vi phạm đến mức phải kỷ luật thì quyết định đương nhiên chấm dứt hiệu lực mà không cần văn bản về việc chấm dứt. S đã qua 13 tháng không vi phạm nên quyết định đã đương nhiên chấm dứt.",mn:"Hết 12 tháng không vi phạm — quyết định đương nhiên chấm dứt (không cần văn bản).",t:"m",q:"Một tình huống vận dụng: Công chức S bị kỷ luật cảnh cáo, quyết định có hiệu lực được 13 tháng và trong thời gian đó S không có vi phạm mới. Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, hiệu lực của quyết định kỷ luật đối với S được xử lý như thế nào?",o:["Quyết định kỷ luật đương nhiên chấm dứt hiệu lực (vi đã hết 12 tháng và không có vi phạm mới) mà không cần phải có văn bản về việc chấm dứt hiệu lực","Quyết định kỷ luật vẫn còn hiệu lực cho đến khi có văn bản chấm dứt","Quyết định kỷ luật được tự động gia hạn thêm 12 tháng","S phải làm đơn đề nghị chấm dứt hiệu lực quyết định"],c:0},{id:"vb10-205",s:"CHUYÊN ĐỀ NÂNG CAO - TRỌNG TÂM, LIÊN HỆ TỔNG THỂ TOÀN VĂN BẢN (Phần 2)",cc:"kRhoơn 3 Điều 19 Nghị định số 1723,2025.NĐ-CB.",gt:"Khi người đứng đầu và tất cả cấp phó thuộc cùng vụ việc bị xem xét kỷ luật (hoặc có quan hệ liên quan), người đứng đầu hoặc cấp phó của cơ quan cấp trên trực tiếp hoặc người được ủy quyền làm Chủ tịch Hội đồng kỷ luật — bảo đảm khách quan.",mn:"Lãnh đạo cùng vụ việc.. cấp trên trực tiếp làm Chủ tịch Hội đồng.",t:"m",q:"Một tình huống vận dụng: Trong cơ quan, người đứng đầu và tất cả cấp phó đều thuộc cùng vụ việc bị xem xét kỷ luật với công chức không giữ chức vụ. Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, ai làm Chủ tịch Hội đồng kỷ luật?",o:["Đại diện công đoàn làm Chủ tịch","Một công chức trong cơ quan được bầu làm Chủ tịch 77 Ũ Z ý LÀI LIỆU ÔN CE CÔNG €HUC VIÊN CHỨC FÐI NGUYỄN YONA 09953502H1","Người đứng đầu hoặc cấp phó của người đứng đầu cơ quan cấp trên trực tiếp hoặc người được ủy quyền làm Chủ tịch Hội đồng","Không thành lập Hội đồng kỷ luật"],c:2},{id:"vb10-206",s:"CHUYÊN ĐỀ NÂNG CAO - TRỌNG TÂM, LIÊN HỆ TỔNG THỂ TOÀN VĂN BẢN (Phần 2)",cc:"DiÖm e khoản › Điều 4 Nghị định số 172 2025/NĐD-C.BP.",gt:"Người có hành vi vi phạm đến mức bị xử lý kỷ luật nhưng đã qua đời thuộc trường hợp miễn kỷ luật — mang tính nhận văn, phù hợp nguyên tắc trách nhiệm cá nhân.",mn:"Đã qua đời. miễn kỷ luật.",t:"m",q:"Một tình huống vận dụng: Công chức T có hành vi vi phạm nhưng đã qua đời trước khi xem xét xử lý kỷ luật. Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, việc xử lý kỷ luật đối với T được giải quyết như thế nào?",o:["Vẫn xử lý kỷ luật và ghi vào lý lịch","Được miễn kỷ luật, vì người có hành vi vi phạm đến mức bị xử lý kỷ luật nhưng đã qua đời thuộc trường hợp miễn kỷ luật","Chuyên trách nhiệm kỷ luật cho người thân của T","Tạm hoãn xử lý kỷ luật vô thời hạn"],c:1},{id:"vb10-207",s:"CHUYÊN ĐỀ NÂNG CAO - TRỌNG TÂM, LIÊN HỆ TỔNG THỂ TOÀN VĂN BẢN (Phần 2)",cc:"Điểm a khoản Í Điều 20 Nghệ định số 172 2025.MD-CP.",gt:"Trường hợp công chức vắng mặt theo giấy triệu tập lần thứ 2 thì Hội đồng kỷ luật vẫn tiến hành họp - tranh việc có tình vắng mặt để né tránh, kéo dài.",mn:"Vắng mặt lần 2. Hội động vẫn họp.",t:"m",q:"Một tình huống vận dụng: Công chức U vắng mặt tại cuộc họp Hội đồng kỷ luật theo giấy triệu tập lần thứ nhất, sau đó tiếp tục vắng mặt theo giấy triệu tập lần thứ hai mà không có lý do chính đáng. Theo Nghị định số 172/2025/NĐ- CP về xử lý kỷ luật cán bộ, công chức, Hội đồng kỷ luật xử lý như thế nào?",o:["Chuyển hồ sơ cho cơ quan điều tra","Hoãn hợp cho đến khi U có mặt","Hủy bỏ việc xử lý kỷ luật đối với U","Hội đồng kỷ luật vẫn tiến hành họp"],c:3},{id:"vb10-208",s:"CHUYÊN ĐỀ NÂNG CAO - TRỌNG TÂM, LIÊN HỆ TỔNG THỂ TOÀN VĂN BẢN (Phần 2)",cc:"liệu 5 Nghị định số 172/2025/NĐ-CP: Điều 37 Luật Cán bộ, công chưt nam 2025.",gt:"Việc giữ nguyên thời hiệu 5/10 năm và thời hạn 90/150 ngày bảo đảm thống nhất, đồng bộ giữa Luật và Nghị định hướng dẫn; Nghị định cụ thể hóa cách tính thời hiệu, thời điểm vi phạm và các thời gian không tính vào thời hiệu, thời hạn.",mn:"ND 172 đồng bộ thời hiệu/thời hạn với Luật CBCC + cụ thể hóa cách tính.",t:"m",q:"Liên hệ tổng thể, việc Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức giữ nguyên thời hiệu 5 năm/10 năm và thời hạn 90/150 ngày như Luật Cán bộ, công chức năm 2025 có ý nghĩa gì?",o:["Bảo đảm sự thống nhất, đồng bộ giữa Luật và văn bản hướng dẫn thi hành; Nghị định cụ thể hóa cách tính thời hiệu, thời điểm vi phạm và các thời gian không tính vào thời hiệu, thời hạn..78","Tạo sự khác biệt giữa Luật và Nghị định","Làm cho thời hiệu, thời hạn không còn ý nghĩa","Chỉ áp dụng thời hiệu, thời hạn cho công chức cấp xã"],c:0},{id:"vb10-209",s:"CHUYÊN ĐỀ NÂNG CAO - TRỌNG TÂM, LIÊN HỆ TỔNG THỂ TOÀN VĂN BẢN (Phần 2)",cc:"Khoản 3 Điều 15 Nghị định số 172/2025/NĐ-CP.",gt:"Đối với công chức biệt phái, trường hợp kỷ luật buộc thôi việc, cơ quan nơi nhận biệt phái căn cứ đề xuất của Hội đồng xử lý kỷ luật, đề nghị cơ quan cử công chức biệt phái ra quyết định buộc thôi việc (vì biên chế vẫn thuộc cơ quan cử).",mn:"Biệt phái + buộc thôi việc: nơi nhận đề nghị, cơ quan cử ra quyết định.",t:"m",q:"Một tình huống vận dụng: Công chức V (biệt phái) có hành vi vi phạm đến mức buộc thôi việc tại cơ quan nơi được cử biệt phái. Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, ai ra quyết định buộc thôi việc?",o:["Cơ quan quản lý cấp trên ra quyết định","Cơ quan nơi nhận biệt phái trực tiếp ra quyết định buộc thôi việc","Cơ quan nơi công chức được cử biệt phái căn cứ đề xuất của Hội đồng xử lý kỷ luật, đề nghị cơ quan cử công chức biệt phái ra quyết định buộc thôi việc","Hội đồng kỷ luật ra quyết định buộc thôi việc"],c:2},{id:"vb10-210",s:"CHUYÊN ĐỀ NÂNG CAO - TRỌNG TÂM, LIÊN HỆ TỔNG THỂ TOÀN VĂN BẢN (Phần 2)",cc:"Jiêm a khoản 3 liệu 2 Nghị định số 172,2025/NHD- CP.",gt:"Đang thi hành cảnh cáo mà vi phạm tiếp ở mức bằng (cảnh cáo) thì áp dụng hình thức nặng hơn một mức so với hình thức đang thi hành (cảnh cáo) - tức cách chức (nếu giữ chức vụ) hoặc mức cao hơn tương ứng.",mn:"Đang cảnh cáo, vi phạm mới bằng mức _› nặng hơn 1 mức so với cảnh g cao. 179 LÀI LIỆU ÔN CE CÔNG €HUC VIÊN CHỨC FÐI NGUYỄN YONA 09953502H1",t:"m",q:"Một tình huống vận dụng: Công chức W vi phạm trong thời gian thi hành quyết định kỷ luật cảnh cáo, hành vi mới đến mức bị cảnh cáo (bằng mức đang thi hành). Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, hình thức kỷ luật áp dụng đối với W là gì?",o:["Áp dụng hình thức kỷ luật nặng hơn một mức so với hình thức đang thi hành (cảnh cáo), tức là cách chức nêu W giữ chức vụ hoặc buộc thôi việc tương ứng","Giữ nguyên hình thức cảnh cáo","Áp dụng hình thức khiển trách","Miễn xử lý vi cùng mức"],c:0},{id:"vb10-211",s:"CHUYÊN ĐỀ NÂNG CAO - TRỌNG TÂM, LIÊN HỆ TỔNG THỂ TOÀN VĂN BẢN (Phần 2)",cc:"Diều lù Nghị định số 1722025 NĐ-CP.",gt:"Việc rút gọn quy trình bảo đảm xử lý kịp thời, nghiêm minh đôi với các trường hợp đã rõ ràng (đã có kết luận. bản án, kỷ luật đảng), tránh kéo dài, trùng lặp thủ tục, đồng thời vẫn giữ nguyên tắc khách quan vì dựa trên kết luận đã có.",mn:"Rút gọn quy trình khi đã rõ: kịp thời, tránh trùng lặp, vẫn khách quan.",t:"m",q:"Liên hệ tổng thể, đầu là ý nghĩa của việc Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức quy định rút gọn quy trình (bỏ kiểm điểm, bỏ Hội đồng kỷ luật) trong một số trường hợp?",o:["Nhằm tăng quyền cho người đứng đầu tùy ý quyết định","Nhằm bỏ qua quyền tự bào chữa của công chức trong mọi trường hợp","Nhằm giảm vai trò của cơ quan quản lý công chức","Bảo đảm xử lý kịp thời, nghiêm minh đối với các trường hợp đã rõ ràng (đã có kết luận, bản án, kỷ luật đảng), tránh kéo dài, trùng lặp thủ tục, đồng thời vẫn giữ nguyên tắc khách quan vì dựa trên kết luận đã có"],c:3},{id:"vb10-212",s:"CHUYÊN ĐỀ NÂNG CAO - TRỌNG TÂM, LIÊN HỆ TỔNG THỂ TOÀN VĂN BẢN (Phần 2)",cc:"Điệm ở khoản 3 Điều và khoản 2 Điều 1 Nghị định số 12 2025/NĐ)- cP.",gt:"Hành vi sử dụng văn bằng, giấy chứng nhận giả hoặc không hợp pháp thuộc trường hợp không áp dụng thời hiệu, áp dụng cả với người đã thôi việc, nghỉ hưu. Vì vậy việc xử lý X không bị giới hạn bởi thời hiệu.",mn:"Văn bằng gia: không thời hiệu, áp dụng cả người đã thôi việc, nghỉ hưu.",t:"m",q:"Một tình huống vận dụng: Công chức X đã thôi việc, sau đó bị phát hiện sử dụng văn bằng không hợp pháp trong thời gian công tác. Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, việc xử lý đối với X có bí giới hạn bởi thời hiệu không?",o:["Bị giới hạn bởi thời hiệu 05 năm","Không bị giới hạn bởi thời hiệu, vì sử dụng văn bằng, giấy chứng nhận giả hoặc không hợp pháp thuộc trường hợp không áp dụng thời hiệu xử lý kỷ luật, áp dụng cả với người đã thôi việc, nghỉ hưu","Không xử lý vi X đã thôi việc","Bị giới hạn bởi thời hiệu 10 năm"],c:1},{id:"vb10-213",s:"CHUYÊN ĐỀ NÂNG CAO - TRỌNG TÂM, LIÊN HỆ TỔNG THỂ TOÀN VĂN BẢN (Phần 2)",cc:"khoản 2 Eiếu 2 Nghị định số 172220205. M-C DĐ.. n0",gt:"Có 02 hành vi vi phạm trở lên thì xem xét, kết luận từng hành vi và quyết định chung bằng một hình thức cao nhất - ở đây là cách chức (cao hơn cảnh cáo), áp dụng nếu Ý giữ chức vụ lãnh đạo, quản lý. ® Miẹo nhớ: Nhiều hành vi „. 1 quyết định, lấy hình thức cao nhất (cách chức).",t:"m",q:"Một tình huống vận dụng tổng hợp: Công chức Ý có 02 hành vi vi phạm trong cùng thời điểm xem xét: hành vi thứ nhất đến mức cách chức, hành vi thứ hai đến mức cảnh cáo. Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, Y bị xử lý như thế nào?",o:["Xem xét, kết luận về từng hành vi và quyết định chung bằng một hình thức kỷ luật cao nhất tương ứng, tức là cách chức (nếu Ý giữ chức vụ lãnh đạo, quản lý)","Bị xử lý cộng dồn cả cách chức và cảnh cáo","Chỉ bị xử lý hành vi nhẹ hơn là cảnh cáo","Bị xử lý hai lần bằng hai quyết định"],c:0},{id:"vb10-214",s:"CHUYÊN ĐỀ NÂNG CAO - TRỌNG TÂM, LIÊN HỆ TỔNG THỂ TOÀN VĂN BẢN (Phần 2)",cc:"Cúc điều 2, 3, 4.20. 25 Nghị định số 172/2025/NĐ-CP.",gt:"Tính nhận văn thể hiện qua: nghiêm cấm xâm phạm thân thể, tinh thần, danh dự, nhân phẩm: chưa xem xét kỷ luật khi điều trị bệnh hiểm nghèo, thai sản, nuôi con dưới 12 tháng: miễn kỷ luật khi đã qua đời hoặc bất khả kháng: 50% lương khi tạm giam; phục hồi danh dự, quyền lợi khi oan, sai.",mn:"Nhận văn: cấm xâm phạm danh dự - hoàn khi bệnh, thai sản — miên khi qua đời — 50% lương — phục hồi oan sai.",t:"m",q:"Liên hệ tổng thể, Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức bảo đảm tính nhận văn trong xử lý kỷ luật thông qua những quy định nào?",o:["Chỉ tập trung trừng phạt mọi vi phạm bằng hình thức nặng nhất","Nghiêm cấm xâm phạm thân thể, tinh thần, danh dự, nhân phẩm; chưa xem xét kỷ luật khi đang điều trị bệnh hiểm nghèo, thai sản, nuôi con dưới 12 tháng: miễn kỷ luật khi đã qua đời hoặc bất khả kháng; bảo đảm 50% lương khi tạm giam; phục hồi danh dự, quyền lợi khi oan, sai","Không có quy định nào mang tính nhận văn","Chỉ bảo vệ cán bộ lãnh đạo cấp cao"],c:1},{id:"vb10-215",s:"CHUYÊN ĐỀ NÂNG CAO - TRỌNG TÂM, LIÊN HỆ TỔNG THỂ TOÀN VĂN BẢN (Phần 2)",cc:"khoản 4 Điều 25 Nghị định số 172/2025/NĐ-CP.",gt:"Khi việc xử lý kỷ luật không đúng quy định về trình tự, thủ tục (theo kết luận giải quyết khiếu nại, tố cáo), cấp có thẩm quyền phải hủy bỏ quyết định xử lý kỷ luật đã ban hành và xem xét xử lý kỷ luật lại theo đúng quy định.",mn:"Xử lý sai trình tự, thủ tục + hủy bỏ và làm lại đúng quy định.",t:"m",q:"Một tình huống vận dụng: Công chức Z bị xử lý kỷ luật nhưng quá trình xử lý có vi phạm về trình tự, thủ tục. Cơ quan giải quyết khiếu nại kết luận việc xử lý không đúng quy định. Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, hệ quả là gì?",o:["Chỉ điều chỉnh hình thức kỷ luật cho phù hợp","Giữ nguyên quyết định kỷ luật đã ban hành","Cấp có thẩm quyền kỷ luật phải ra quyết định hủy bỏ quyết định xử lý kỷ luật đã ban hành, đồng thời tiến hành xem xét xử lý kỷ luật lại theo đúng quy định","Chuyển hồ sơ cho Tòa án giải quyết"],c:2},{id:"vb10-216",s:"CHUYÊN ĐỀ NÂNG CAO - TRỌNG TÂM, LIÊN HỆ TỔNG THỂ TOÀN VĂN BẢN (Phần 2)",cc:"liệu 29 Nghị định số 172/2005/NĐ-CP; Điều 44 Luật Cdn bộ, công chứti năm 2025.",gt:"Nghị định có hiệu lực cùng thời điểm (01/7/2025) với Luật CBCC 2025 để bảo đảm đồng bộ, kịp thời hướng dẫn thi hành Luật trong bối cảnh sắp xếp tổ chức bộ máy, chính quyền hai cấp và chế độ công vụ thống nhất, liên thông: tránh khoảng trong pháp lý về xử lý kỷ luật.",mn:"ND 172 hiệu lực cùng Luật CBCC (01/7/2025): đồng bộ, tranh khoảng trong pháp lý.",t:"m",q:"Liên hệ với cải cách tổ chức bộ máy, vì sao Nghị định số 172/2025/NĐ- CP về xử lý kỷ luật cán bộ, công chức được ban hành cùng thời điểm có hiệu lực với Luật Cán bộ, công chức năm 2025?",o:["Vị không liên quan đến Luật Cán bộ, công chức","Để thay thế hoàn toàn Luật Cán bộ, công chức","Để áp dụng cho viên chức thay vì cán bộ, công chức s8]","Để bảo đảm đồng bộ, kịp thời hướng dẫn thi hành Luật trong bối cảnh sắp xếp tổ chức bộ máy, thực hiện mô hình chính quyền địa phương hai cấp và chế độ công vụ thống nhất, liên thông: tránh khoảng trong pháp lý về xử lý kỷ luật"],c:3},{id:"vb10-217",s:"CHUYÊN ĐỀ NÂNG CAO - TRỌNG TÂM, LIÊN HỆ TỔNG THỂ TOÀN VĂN BẢN (Phần 2)",cc:"Khoan ö liệu 2 Nghị định số 172/2005/NĐ-CP.",gt:"Trường hợp cấp có thẩm quyền của Đảng quyết định xóa bỏ quyết định kỷ luật về đảng thì cấp có thẩm quyền xử lý kỷ luật hành chính phải ban hành quyết định hủy bỏ quyết định xử lý kỷ luật hành chính - bảo đảm tính tương xứng, đồng bộ giữa kỷ luật đảng và kỷ luật hành chính.",mn:"Xóa bỏ kỷ luật đảng., hủy bỏ kỷ luật hành chính tương ứng.",t:"m",q:"Một tình huống vận dụng: Công chức AA bị cảnh cáo về đảng liên quan đến hoạt động công vụ. Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, nếu sau đó cấp có thẩm quyền của Đảng quyết định xóa bỏ quyết định kỷ luật về đảng thì quyết định kỷ luật hành chính được xử lý như thế nào?",o:["Cấp có thẩm quyền xử lý kỷ luật hành chính phải ban hành quyết định hủy bỏ quyết định xử lý kỷ luật hành chính","Giữ nguyên quyết định kỷ luật hành chính","Tự động chấm dứt hiệu lực mà không cần văn bản","Chuyển sang hình thức kỷ luật nhẹ hơn"],c:0},{id:"vb10-218",s:"CHUYÊN ĐỀ NÂNG CAO - TRỌNG TÂM, LIÊN HỆ TỔNG THỂ TOÀN VĂN BẢN (Phần 2)",cc:"Điều 15, khoản 5 Điều 5 và điểm b khoản 3 Điều 9 Nghị định số I72/2025/NĐ-CP.",gt:"Người đứng đầu vừa có thẩm quyền xử lý kỷ luật (theo phân cấp), vừa chịu trách nhiệm bảo đảm xử lý trong thời hạn; nếu để xảy ra vi phạm pháp luật nghiêm trọng trong phạm vi phụ trách mà không ngăn chặn thì chính người đứng đầu cũng bị xử lý kỷ luật (cảnh cáo). „82",mn:"Người đứng đầu: có thẩm quyền + chịu trách nhiệm (để xảy ra vi phạm cùng bị kỷ luật).",t:"m",q:"Liên hệ tổng thể, trách nhiệm của người đứng đầu trong xử lý kỷ luật theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức được thể hiện như thế nào?",o:["Người đứng đầu được miễn mọi trách nhiệm khi cấp dưới vi phạm","Người đứng đầu chỉ có quyền, không có trách nhiệm gì","Người đứng đầu không liên quan đến xử lý kỷ luật","Người đứng đầu vừa có thẩm quyền xử lý kỷ luật (theo phân cấp), vừa chịu trách nhiệm bảo đảm xử lý trong thời hạn; nếu để xảy ra vi phạm pháp luật nghiêm trọng trong phạm vi phụ trách mà không ngăn chặn thì chính người đứng đầu cũng bị xử lý kỷ luật"],c:3},{id:"vb10-219",s:"CHUYÊN ĐỀ NÂNG CAO - TRỌNG TÂM, LIÊN HỆ TỔNG THỂ TOÀN VĂN BẢN (Phần 2)",cc:"Khoản 2 Điều 38 Luật Cán bộ, công chức năm 2025.",gt:"Cán bộ, công chức đang trong thời hạn xử lý kỷ luật, đang bị điều tra, truy tố, xét xử thì không được ứng cử, đề cử, bổ nhiệm, điều động, luân chuyển, biệt phái, đào tạo, bồi dưỡng. Vì vậy BB không được bố nhiệm trong thời gian này.",mn:"Đang trong thời hạn xử lý kỷ luật. động bằng' bổ nhiệm, điều động, đào tạo.",t:"m",q:"Một tình huống vận dụng: Công chức BB đang trong thời hạn xử lý kỷ luật thì được đề nghị bổ nhiệm vào chức vụ lãnh đạo. Theo Luật Cán bộ, công chức năm 2025 và tinh thần Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, việc bổ nhiệm BB được xử lý như thế nào?",o:["Được bổ nhiệm nêu cam kết khắc phục vi phạm","Được bố nhiệm bình thường vị chưa có quyết định kỷ luật","Không được bổ nhiệm trong thời gian đang trong thời hạn xử lý kỷ luật; cán bộ, công chức đang trong thời hạn xử lý kỷ luật, đang bị điều tra, truy tố, xét xử thì không được ứng cử, đề cử, bổ nhiệm, điều động, luân chuyển, biệt phái, đào tạo, bồi dưỡng","Được bổ nhiệm nêu cấp trên đồng ý"],c:2},{id:"vb10-220",s:"CHUYÊN ĐỀ NÂNG CAO - TRỌNG TÂM, LIÊN HỆ TỔNG THỂ TOÀN VĂN BẢN (Phần 2)",cc:"loàn văn Nghị định số 172/2025/NĐ-CP.",gt:"Giá trị của Nghị định: cụ thể hóa nguyên tắc, hình thức, thẩm quyền, trình tự, thủ tục xử lý kỷ luật đồng bộ với Luật CBCC 2025; bảo đảm kỷ luật, kỷ cương nghiêm minh, không vùng cấm; đồng thời bảo vệ cán bộ dám nghĩ, dám làm và bảo đảm quyền, lợi ích hợp pháp. góp phần xây dựng nền công vụ liêm chính, chuyên nghiệp.",mn:"ND 172: nghiêm minh, không vùng cấm + bảo vệ người dám làm + nền công vụ liêm chính, chuyên nghiệp. 83 LÀI LIỆU ÔN CE CÔNG €HUC VIÊN CHỨC FÐI NGUYỄN YONA 09953502H1 _ ] PHẨN CẬP NHẬT THEO NGHỊ ĐỊNH SỐ 251/2025/NĐ-CP (SỬA ĐỔI",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP về xử lý kỷ luật cán bộ, công chức, phương án nào sau đây khái quát ĐÚNG và ĐẦY ĐỦ nhất giá trị của Nghị định trong tổng thể cải cách chế độ công vụ?",o:["Nghị định chỉ nhằm xử phạt cán bộ, công chức vi phạm","Nghị định cụ thể hóa nguyên tắc, hình thức, thẩm quyền, trình tự, thủ tục xử lý kỷ luật cán bộ, công chức một cách đồng bộ với Luật Cán bộ, công chức năm 2025; bảo đảm kỷ luật, kỷ cương nghiêm minh, không vùng cấm; đồng thời bảo vệ cán bộ dám nghĩ, dám làm và bảo đảm quyền, lợi ích hợp pháp, góp phần xây dựng nền công vụ liêm chính, chuyên nghiệp","Nghị định làm phức tạp thêm quy trình quản lý cán bộ","Nghị định không có vai trò trong cải cách chế độ công vụ"],c:1},{id:"vb10-221",s:"ĐIỀU 22, 23— NGƯỜI ĐÃ THÔI VIỆC, NGHỈ HƯU)",cc:"khoản 1.2.3.4 Điều 22 Nghị định số 1722025: NG-C P (được sửa đổi, bộ xung bởi Nghị định số 25121025.NME)-C.P).",gt:"Nghị định số 251/2025/NĐ-CP sửa đổi Điều 22, nâng từ 03 khoản (bản gốc) lên 04 khoản: bổ sung khoản 4 về trường hợp chức danh do Quốc hội bầu.",mn:"Điều 22 sau sửa đổi cơ 4 khoản (thêm khoản 4 - Quốc hội bầu).",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP (được sửa đổi, bổ sung bởi Nghị định số 251/2025/NĐ-CP) về xử lý kỷ luật cán bộ, công chức, thẩm quyền xử lý kỷ luật đối với người đã thôi việc, nghỉ hưu tại Điều 22 hiện được quy định thành mấy khoản?",o:["02 khoản","03 khoản","04 khoản","05 khoản"],c:2},{id:"vb10-222",s:"ĐIỀU 22, 23— NGƯỜI ĐÃ THÔI VIỆC, NGHỈ HƯU)",cc:"khoản 3 Đinu 22 äuụh) định số 12220125 NE-C P (được bổ sung bởi Nghị định số 251.2025 NĐ-CDP).",gt:"Đây là điểm MỚI của Nghị định số 251: người giữ chức vụ, chức danh do Quốc hội bầu thì Ủy ban Thường vụ Quốc hội ra quyết định xử lý kỷ luật (bản gốc ND 172 chưa có quy định này).",mn:"- Quốc hội BẦU.. Ủy ban Thường vụ Quốc hội (diểm mới NÐ 251).",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP (được sửa đổi, bổ sung bởi Nghị định số 251/2025/NĐ-CP) về xử lý kỷ luật cán bộ, công chức, đối với người đã thôi việc, nghỉ hưu giữ chức vụ, chức danh DO QUỐC HỘI BẦU thì ai ra quyết định xử lý kỷ luật?",o:["Thủ tướng Chính phủ","Ủy ban Thường vụ Quốc hội","Bộ trưởng Bộ Nội vụ","Chủ tịch nước"],c:1},{id:"vb10-223",s:"ĐIỀU 22, 23— NGƯỜI ĐÃ THÔI VIỆC, NGHỈ HƯU)",cc:"Nhoan 3 Điều 22 Nghị định số 12220125.NPD-C P (được sữu đôi bởi Nghị định số 231 2025. NI) CD]. mm.”",gt:"Nghị định số 251 nêu rõ hơn: chức danh trong cơ quan hành chính nhà nước do Thủ tướng Chính phủ trình Quốc hội phê chuẩn thì Thủ tướng Chính phủ ra quyết định xử lý kỷ luật.",mn:"Thủ tướng trình (QQ}H phê chuẩn -¬ Thủ tướng ra quyết định.",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP (được sửa đổi, bổ sung bởi Nghị định số 251/2025/NĐ-CP) về xử lý kỷ luật cán bộ, công chức, đối với người đã thôi việc, nghỉ hưu giữ chức vụ, chức danh trong cơ quan hành chính nhà nước DO THỦ TƯỚNG CHÍNH PHỦ TRÌNH QUỐC HỘI PHÊ CHUẤẨN thì ai ra quyết định?",o:["Quốc hội","Ủy ban Thường vụ Quốc hội","Thủ tướng Chính phủ","Bộ Nội vụ"],c:2},{id:"vb10-224",s:"ĐIỀU 22, 23— NGƯỜI ĐÃ THÔI VIỆC, NGHỈ HƯU)",cc:"Khoan Í Điều 23 Nghị định số 172:20025/NE)-CP (được sửa đổi, bổ sung bởi Nghị định số 251/2025/NĐ-CP).",gt:"Nghị định số 251 bổ sung: trường hợp thuộc thẩm quyền của Ủy ban Thường vụ Quốc hội thì Thường trực Ủy ban Công tác đại biểu đề xuất hình thức, thời điểm, thời gian thi hành kỷ luật, báo cáo Ủy ban Thường vụ Quốc hội xem xét, quyết định. ® Miẹo nhớ: Thuộc UBTVQHH. Thường trực Ủy ban Công tác đại biểu đề xuất (điểm mới ND 251).",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP (được sửa đổi, bổ sung bởi Nghị định số 251/2025/NĐ-CP) về xử lý kỷ luật cán bộ, công chức, trường hợp xử lý kỷ luật người đã nghỉ hưu thuộc thẩm quyền của Ủy ban Thường vụ Quốc hội thì cơ quan nào đề xuất hình thức, thời điểm, thời gian thi hành kỷ luật?",o:["Bộ Nội vụ","Thường trực Ủy ban Công tác đại biểu","Văn phòng Chính phủ","Hội đồng kỷ luật của cơ quan cử"],c:1},{id:"vb10-225",s:"ĐIỀU 22, 23— NGƯỜI ĐÃ THÔI VIỆC, NGHỈ HƯU)",cc:"Khoản 2 Điều 23 Nghị định số 172/2025/NĐ-CP (được sửa đổi bởi Nghị định số 251/2025/NĐ-CP).",gt:"Nghị định số 251 tách rõ trường hợp “đã có” và “chưa có” quyết định; khi chưa có quyết định thì cấp có thẩm quyền quy định tại Điều 22 quyết định (bản gốc NDÐ 172 dẫn chiếu Điều 13).",mn:"Chưa có quyết định ¬„ theo Điều 22 (thay vi Điều 13 như bản gốc).",t:"m",q:"Theo Nghị định số 172/2025/NĐ-CP (được sửa đổi, bổ sung bởi Nghị định số 251/2025/NĐ-CP) về xử lý kỷ luật cán bộ, công chức, trường hợp CHƯA có quyết định xử lý kỷ luật đối với người đã thôi việc, nghỉ hưu vi phạm thì cấp có thẩm quyền quy định tại điều nào quyết định việc xử lý kỷ luật?",o:["Điều 13","Điều 15","Điều 22","Điều 23"],c:2},{id:"vb10-226",s:"ĐIỀU 22, 23— NGƯỜI ĐÃ THÔI VIỆC, NGHỈ HƯU)",gt:"Nghị định số 251 chỉ sửa đổi, bổ sung Điều 22 (thẩm quyền) và Điều 23 (trình tự, thủ tục) đối với người đã thôi việc, nghỉ hưu; Nghị định có hiệu lực kể từ ngày ký ban hành.",mn:"ND 251 = sửa Điều 22 & Điều 23. hiệu lực kể từ ngày ký.. s86",t:"m",q:"Nghị định số 251/2025/NĐ-CP sửa đổi, bổ sung những điều nào của Nghị định số 172/2025/NĐ-CP và có hiệu lực khi nào?",o:["Sửa Điều 7 và Điều 12; hiệu lực từ 01/7/2025","Sửa Điều 22 và Điều 23; hiệu lực kể từ ngày ký","Sửa toàn bộ Chương II; hiệu lực sau 45 ngày","Bãi bỏ Điều 22 và Điều 23; hiệu lực từ 01/01/2026"],c:1}];export{h as default};
